window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s25-19","number":19,"surah":25,"verses":[13],"references":[{"surah":25,"verses":[13]}],"verseLabel":"الفرقان: 13","question":"ما نكتة وصف مكان الإلقاء في النار بالضيق؟","answer":"يجمع الوصف حرارة العذاب إلى شدة الحصر، فيمنع الانبساط والحركة ويزيد الكرب فوق كرب النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص553، تحت عنوان «نكتة وصف المكان بالضيق»","url":""}]},{"id":"s25-101","number":101,"surah":25,"verses":[13],"references":[{"surah":25,"verses":[13]}],"verseLabel":"الفرقان: 13","question":"ما نكتة التعبير بـ﴿مُقَرَّنِينَ﴾؟","answer":"تصور اللفظة شدة الربط والاقتران؛ ومن وجوهها قرن الكافر بشيطانه أو جمع الأتباع والمتبوعين أو ربط المعذبين بعضهم ببعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص555، تحت عنوان «نكتة التعبير بـ﴿مقرنين﴾»","url":""}]},{"id":"s25-20","number":20,"surah":25,"verses":[14],"references":[{"surah":25,"verses":[14]}],"verseLabel":"الفرقان: 14","question":"ما دلالة ﴿لا تدعوا اليوم ثبورا واحدا وادعوا ثبورا كثيرا﴾؟","answer":"فيه تقنيط لهم من الخلاص، وبيان أن ما نزل بهم من البلاء أعظم من أن يكفيه دعاء واحد بالهلاك. وتكرار الدعاء لا يقطع العذاب ولا يجلب راحة؛ فالمقصود تهويل حالهم والإياس من النجاة، لا أن الهلاك يتحقق لهم إذا أكثروا طلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص559–560، تحت عنوان «بلاغة الكنايات في التركيب»","url":""}]},{"id":"s25-21","number":21,"surah":25,"verses":[15],"references":[{"surah":25,"verses":[15]}],"verseLabel":"الفرقان: 15","question":"ما دلالة التفضيل بـ﴿خَيْرٌ﴾ في مقابلة جنة الخلد بالسعير؟","answer":"التفضيل للتقرير والتبكيت في أمر بيّن، لا لإثبات خير حقيقي في السعير؛ فهو يكشف فساد اختيار المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص566، تحت عنوان «دلالة التفضيل في ﴿خير﴾»","url":""}]},{"id":"s25-102","number":102,"surah":25,"verses":[15],"references":[{"surah":25,"verses":[15]}],"verseLabel":"الفرقان: 15","question":"ما دلالة إضافة الجنة إلى الخلد؟","answer":"تمدح الجنة بدوام نعيمها وتنزهها عن زوال جنان الدنيا، فتجعل البقاء والنعيم التام جزءًا من المفاضلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص568، تحت عنوان «دلالة الإضافة في ﴿جنة الخلد﴾»","url":""}]},{"id":"s25-22","number":22,"surah":25,"verses":[16],"references":[{"surah":25,"verses":[16]}],"verseLabel":"الفرقان: 16","question":"لماذا حُذف مفعول ﴿يَشَاءُونَ﴾ في قوله: ﴿لَهُمْ فِيهَا مَا يَشَاءُونَ﴾؟","answer":"عم الحذف أنواع النعيم التي تتعلق بها مشيئتهم، لأن ذكر بعض المفعولات قد يوهم الاقتصار ويضيق سعة الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص574، تحت عنوان «علة حذف مفعول المشيئة»","url":""}]},{"id":"s25-103","number":103,"surah":25,"verses":[16],"references":[{"surah":25,"verses":[16]}],"verseLabel":"الفرقان: 16","question":"ما الكناية في وصف نعيم الجنة بأنه ﴿وَعْدًا مَسْئُولًا﴾؟","answer":"التركيب كناية عن تحقق الوعد ولزوم إنجازه وانتفاء إخلافه، فيطمئن أهل الجنة إلى تمام ما وعدوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص577، تحت عنوان «بلاغة الكناية في التركيب»","url":""}]},{"id":"s25-23","number":23,"surah":25,"verses":[17],"references":[{"surah":25,"verses":[17]}],"verseLabel":"الفرقان: 17","question":"ما دلالة سؤال المعبودين أمام عابديهم وتقديمه على سؤال العابدين؟","answer":"توجَّه المواجهة أولا إلى من عظموهم واتخذوهم معبودين، فإذا تبرؤوا من إضلال عابديهم انهارت حجتهم وظهر بطلان تعلقهم بهم. وفي ذلك زيادة في خزي العابدين وحسرتهم، إذ يأتي التكذيب ممن كانوا يرجون نفعه ويعظمون قدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص585، تحت عنوان «نكتة تقديم سؤال المعبودين على سؤال العابدين»","url":""}]},{"id":"s25-24","number":24,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"لماذا صُدر جواب المعبودين بالتسبيح؟","answer":"بادروا بتنزيه الله إجمالًا قبل تفصيل التبرؤ، وقدموه على شأن أنفسهم لأنه الأحق بالتقديم في مقام إنكار الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص596، تحت عنوان «نكتة تصدير القول بالتسبيح»","url":""}]},{"id":"s25-104","number":104,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما الكناية في قول المعبودين: ﴿سُبْحَانَكَ﴾؟","answer":"التسبيح كناية عن استبعاد أن يكونوا أندادًا لله أو أن يدعوا الناس إلى اتخاذهم أولياء من دونه، مع التصريح بتنزيهه عن الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص596، تحت عنوان «بلاغة الكناية في جملة التسبيح»","url":""}]},{"id":"s25-25","number":25,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما دلالة عطف الآباء في قوله: ﴿مَتَّعْتَهُمْ وَآبَاءَهُمْ﴾؟","answer":"أبرز العطف أن النعمة امتدت إلى أجيالهم، وأنهم نشؤوا في تمتع موروث لم يقابلوه بالشكر والإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص601–602، تحت عنوان «دلالة عطف الآباء عليهم»","url":""}]},{"id":"s25-105","number":105,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما دلالة جعل النسيان غاية للتمتيع في قوله: ﴿حَتَّى نَسُوا الذِّكْرَ﴾؟","answer":"صوّر طول التمتع والاستغراق فيه حتى آل حالهم إلى الإعراض عن الذكر، لا لأن النعمة تعذرهم بل لأنها كانت تستوجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص602، تحت عنوان «دلالة جعل النسيان غاية للتمتيع»","url":""}]},{"id":"s25-106","number":106,"surah":25,"verses":[18],"references":[{"surah":25,"verses":[18]}],"verseLabel":"الفرقان: 18","question":"ما دلالة التعبير بالنسيان في قوله: ﴿نَسُوا الذِّكْرَ﴾؟","answer":"عبر بالنسيان عن شدة الترك والإهمال حتى صار الذكر كالمغيّب عن قلوبهم وسلوكهم، وهو نسيان تفريط لا عجز غير مؤاخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص603، تحت عنوان «دلالة التعبير بالنسيان»","url":""}]},{"id":"s25-26","number":26,"surah":25,"verses":[19],"references":[{"surah":25,"verses":[19]}],"verseLabel":"الفرقان: 19","question":"ما موقع جملة ﴿فَقَدْ كَذَّبُوكُمْ﴾ مما قبلها؟","answer":"جاءت نتيجة لمحاكمة دعوى العابدين؛ فلما تبرأ المعبودون مما نسب إليهم صار جوابهم حجة فاصلة على كذب عابديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص607، تحت عنوان «موقع جملة ﴿فقد كذبوكم﴾ مما قبله»","url":""}]},{"id":"s25-107","number":107,"surah":25,"verses":[19],"references":[{"surah":25,"verses":[19]}],"verseLabel":"الفرقان: 19","question":"ما دلالة ﴿قَدْ﴾ في قوله: ﴿فَقَدْ كَذَّبُوكُمْ﴾؟","answer":"حققت وقوع التكذيب وثبوته بعد ظهور شهادة المعبودين، فلم تبق دعوى العابدين محتملة في مقام الفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص608، تحت عنوان «دلالة (قد) التحقيقية في السياق»","url":""}]},{"id":"s25-108","number":108,"surah":25,"verses":[19],"references":[{"surah":25,"verses":[19]}],"verseLabel":"الفرقان: 19","question":"ما معنى الباء في قوله: ﴿بِمَا تَقُولُونَ﴾؟","answer":"تحتمل الملابسة، أي كذبوكم في شأن قولكم، وتحتمل السببية، أي كان قولكم سببًا في إظهار تكذيبهم لكم؛ وكلاهما يربط الحكم بالدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص608، تحت عنوان «معنى الباء في ﴿بما﴾»","url":""}]},{"id":"s25-27","number":27,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"ما دلالة أسلوبي النفي والاستثناء في تقرير بشرية الرسل السابقين؟","answer":"قصر حالهم على ما هو معهود من البشر في الأكل والمشي، ردًا على توهم أن الرسالة تستلزم الخروج عن الطبيعة البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص615–616، تحت عنوان «دلالة أسلوبي النفي والاستثناء في الآية»","url":""}]},{"id":"s25-109","number":109,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"ما الكناية في أكل الرسل الطعام ومشيهم في الأسواق؟","answer":"كناية عن حاجتهم البشرية إلى القوت وقضاء المصالح وطلب المعاش، وهي أحوال لا تنافي اصطفاءهم بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص616، تحت عنوان «بلاغة الكناية في أكل الطعام والمشي في الأسواق»","url":""}]},{"id":"s25-28","number":28,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"إلى من يعود ضمير الخطاب في قوله: ﴿وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً﴾؟","answer":"يعم الخطاب الناس، ويدخل فيه ابتلاء الناس بالرسل وابتلاء الرسل بأقوامهم؛ فاختلاف الأحوال والمواقف امتحان يكشف الصبر والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص617–618، تحت عنوان «فائدة ضمير الخطاب وعوده في ﴿بعضكم لبعض فتنة﴾»","url":""}]},{"id":"s25-110","number":110,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"لماذا اختير لفظ ﴿فِتْنَةً﴾ في قوله: ﴿بَعْضَكُمْ لِبَعْضٍ فِتْنَةً﴾؟","answer":"يصور اللفظ شدة الاختبار الذي يمحص المواقف، وفيه مجاز بجعل الشخص أو اختلاف حاله نفس الفتنة لما يكون سببًا للامتحان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص618، تحت عنوان «سر إيثار لفظ ﴿فتنة﴾، ودلالة المجاز فيه»","url":""}]},{"id":"s25-111","number":111,"surah":25,"verses":[20],"references":[{"surah":25,"verses":[20]}],"verseLabel":"الفرقان: 20","question":"ما بلاغة الاستفهام في قوله: ﴿أَتَصْبِرُونَ﴾؟","answer":"خرج الاستفهام للحث والاختبار، فيحتمل معنى الأمر بالصبر والتحذير من ضعف الاحتمال، لا مجرد طلب خبر عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص618–619، تحت عنوان «بلاغة الاستفهام في الآية ﴿أتصبرون﴾»","url":""}]},{"id":"s25-29","number":29,"surah":25,"verses":[21],"references":[{"surah":25,"verses":[21]}],"verseLabel":"الفرقان: 21","question":"ما غرض تقديم ﴿عَلَيْنَا﴾ في قولهم: ﴿لَوْلَا أُنْزِلَ عَلَيْنَا الْمَلَائِكَةُ﴾؟","answer":"أبرز التقديم تعاظمهم ورؤيتهم أنفسهم أهلًا لتلقي الملائكة مباشرة، وفيه تحكم متكبر في دلائل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص629، تحت عنوان «الغرض من تقديم شبه الجملة ﴿علينا﴾»","url":""}]},{"id":"s25-112","number":112,"surah":25,"verses":[21],"references":[{"surah":25,"verses":[21]}],"verseLabel":"الفرقان: 21","question":"ما دلالة ﴿أَوْ﴾ والتعبير بالرؤية في قولهم: ﴿أَوْ نَرَى رَبَّنَا﴾؟","answer":"نقلت أو تعنتهم إلى اقتراح أشد، وصرحوا بالرؤية الحسية شرطًا للتصديق، فكشفوا أن مقصدهم المكابرة لا طلب الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص629–630، تحت عنوان «معنى ﴿أو﴾، ودلالة التعبير بالرؤية في ﴿أو نرى ربنا﴾»","url":""}]},{"id":"s25-113","number":113,"surah":25,"verses":[21],"references":[{"surah":25,"verses":[21]}],"verseLabel":"الفرقان: 21","question":"ما دلالة التعبير بـ﴿عُتُوًّا﴾ مادة وصيغة؟","answer":"العتو مجاوزة الحد مع الاستكبار، والمصدر يصور تمكنه وعظمه في نفوسهم وأقوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص632، تحت عنوان «دلالة التعبير بالعتو مادة وصيغة»","url":""}]},{"id":"s25-30","number":30,"surah":25,"verses":[22],"references":[{"surah":25,"verses":[22]}],"verseLabel":"الفرقان: 22","question":"ما نكتة فصل قوله: ﴿لَا بُشْرَى يَوْمَئِذٍ لِلْمُجْرِمِينَ﴾؟","answer":"استؤنفت الجملة جوابًا عن سؤال مقدر عن حالهم عند رؤية الملائكة، فبينت أن الرؤية التي طلبوها تأتيهم في مقام الخوف والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص639، تحت عنوان «نكتة فصل قوله: ﴿لا بشرى يومئذ للمجرمين﴾»","url":""}]},{"id":"s25-114","number":114,"surah":25,"verses":[22],"references":[{"surah":25,"verses":[22]}],"verseLabel":"الفرقان: 22","question":"ما غرض النفي بـ﴿لَا﴾ النافية للجنس في قوله: ﴿لَا بُشْرَى﴾؟","answer":"استغرق النفي جنس البشرى كله، فقطع رجاء المجرمين في أي خبر سار أو نجاة يومئذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص640، تحت عنوان «غرض النفي بـ ﴿لا﴾ النافية للجنس في الآية الكريمة»","url":""}]},{"id":"s25-31","number":31,"surah":25,"verses":[23],"references":[{"surah":25,"verses":[23]}],"verseLabel":"الفرقان: 23","question":"ما غرض التشبيه البليغ في قوله: ﴿فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا﴾؟","answer":"جسد ذهاب نفع أعمالهم، فصارت كالدقائق التي تظهر في شعاع الشمس ولا يمكن جمعها أو الانتفاع بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص652، تحت عنوان «الغرض من التعبير بالتشبيه البليغ في قوله: ﴿فجعلناه هباء منثورا﴾»","url":""}]},{"id":"s25-115","number":115,"surah":25,"verses":[23],"references":[{"surah":25,"verses":[23]}],"verseLabel":"الفرقان: 23","question":"لماذا وُصف الهباء بأنه ﴿مَنْثُورًا﴾؟","answer":"زاد الوصف صورة التفرق والضياع، فنفى أن يبقى للعمل أثر مجتمع ينفع صاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص652، تحت عنوان «سر وصف الهباء بأنه منثور»","url":""}]},{"id":"s25-32","number":32,"surah":25,"verses":[24],"references":[{"surah":25,"verses":[24]}],"verseLabel":"الفرقان: 24","question":"ما غرض التفضيل بـ﴿خَيْرٌ﴾ في وصف أصحاب الجنة؟","answer":"جاء للتقرير والتوبيخ للمكذبين والبشارة للمؤمنين، ولا يقتضي إثبات خير في مستقر الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص658، تحت عنوان «الغرض من التعبير بالمسند (أفعل) تفضيل: ﴿خير﴾»","url":""}]},{"id":"s25-116","number":116,"surah":25,"verses":[24],"references":[{"surah":25,"verses":[24]}],"verseLabel":"الفرقان: 24","question":"ما دلالة التعبير عن موضع المؤمنين بـ﴿مُسْتَقَرًّا﴾؟","answer":"يصور ثبات مقامهم وطمأنينته وأمنهم من الزوال والاضطراب، فيقابل مصير أهل العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص659، تحت عنوان «دلالة التعبير عن موضع المؤمنين بالاستقرار»","url":""}]},{"id":"s25-117","number":117,"surah":25,"verses":[24],"references":[{"surah":25,"verses":[24]}],"verseLabel":"الفرقان: 24","question":"ما دلالة التعبير بـ﴿مَقِيلًا﴾ مادة وصيغة؟","answer":"يصور حسن الراحة وطيبها، سواء حمل على الاستراحة بعد الحساب أو شبّه نعيم الجنة براحة القائلة؛ ولا يلزم منه نوم أهل الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص660، تحت عنوان «دلالة التعبير بـ﴿مقيلا﴾ مادة وصيغة»","url":""}]},{"id":"s25-33","number":33,"surah":25,"verses":[25],"references":[{"surah":25,"verses":[25]}],"verseLabel":"الفرقان: 25","question":"ما دلالة التعبير بـ﴿تَشَقَّقُ﴾ مادة وصيغة؟","answer":"تصور المادة انصداع السماء، ويفيد التضعيف شدة التشقق وتكثره، فيجسد تغير نظامها وهول يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص666، تحت عنوان «دلالة التعبير بـ﴿تشقق﴾ مادة وصيغة»","url":""}]},{"id":"s25-118","number":118,"surah":25,"verses":[25],"references":[{"surah":25,"verses":[25]}],"verseLabel":"الفرقان: 25","question":"ما معنى الباء في قوله: ﴿تَشَقَّقُ السَّمَاءُ بِالْغَمَامِ﴾؟","answer":"تحتمل أن تتشقق السماء عن الغمام، أو بسببه، أو مع ظهوره؛ فتجمع الأوجه بين انصداع السماء ومشهد الغمام ونزول الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص667–668، تحت عنوان «معنى الباء ودلالتها في قوله: ﴿بالغمام﴾»","url":""}]},{"id":"s25-34","number":34,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما الكناية في قوله: ﴿يَعَضُّ الظَّالِمُ عَلَى يَدَيْهِ﴾؟","answer":"العض على اليدين كناية عن شدة الندم والحسرة، تنقل الانفعال النفسي إلى حركة محسوسة مؤلمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص683–684، تحت عنوان «بلاغة التعبير بالكناية»","url":""}]},{"id":"s25-119","number":119,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما بلاغة اختلاف العض على الأنامل والعض على اليدين في القرآن؟","answer":"ناسب عض الأنامل غيظ المنافقين مع بقاء أملهم في الإضرار، أما عض اليدين فمبالغة في حسرة الظالم بعد فوات التدارك؛ فاختلاف الصورة لاختلاف المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص684، تحت عنوان «بلاغة المتشابه اللفظي»","url":""}]},{"id":"s25-35","number":35,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما بلاغة التعبير عن اتباع الرسول بالمعية في قوله: ﴿مَعَ الرَّسُولِ سَبِيلًا﴾؟","answer":"صوّر الاتباع بسلوك طريق مع الرسول بوصفه دليلًا إلى النجاة، فالمعية معية هدى واقتداء لا مجرد قرب مكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص686–687، تحت عنوان «بلاغة التعبير عن الاتباع بالمعية مع الرسول»","url":""}]},{"id":"s25-120","number":120,"surah":25,"verses":[27],"references":[{"surah":25,"verses":[27]}],"verseLabel":"الفرقان: 27","question":"ما غرض تنكير ﴿سَبِيلًا﴾ في قوله: ﴿اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلًا﴾؟","answer":"يحتمل تعظيم سبيل الاتباع المنجي، أو تعميم طرق الخير، أو إفراد سبيل الهدى في مقابلة مسالك الضلال المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص687–688، تحت عنوان «الغرض من تنكير ﴿سبيلا﴾»","url":""}]},{"id":"s25-36","number":36,"surah":25,"verses":[28,29],"references":[{"surah":25,"verses":[28,29]}],"verseLabel":"الفرقان: 28-29","question":"ما نكتة التكنية عن الخليل بـ﴿فُلَانًا﴾؟","answer":"لم تعين اسمًا لتعم العبرة كل خليل يصد صاحبه عن الحق، فلا تنحصر الحسرة في واقعة أو شخص مخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص690، تحت عنوان «نكتة التكنية عن المقصود بـ﴿فلانا﴾»","url":""}]},{"id":"s25-121","number":121,"surah":25,"verses":[28,29],"references":[{"surah":25,"verses":[28,29]}],"verseLabel":"الفرقان: 28-29","question":"ما نكتة فصل قوله: ﴿لَقَدْ أَضَلَّنِي عَنِ الذِّكْرِ﴾؟","answer":"جاءت الجملة تعليلًا لحسرته على اتخاذ الخليل، فكشفت أن من قربه للنصرة صار سببًا في أعظم خسارته: الانصراف عن الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص691، تحت عنوان «نكتة فصل قوله: ﴿لقد أضلني﴾»","url":""}]},{"id":"s25-37","number":37,"surah":25,"verses":[29],"references":[{"surah":25,"verses":[29]}],"verseLabel":"الفرقان: 29","question":"ما دلالة ختم المشهد بقوله: ﴿وَكَانَ الشَّيْطَانُ لِلْإِنْسَانِ خَذُولًا﴾؟","answer":"قرر التذييل أن الخذلان شأن متكرر للشيطان: يزين الضلال ثم يترك الإنسان عند الحاجة، وصيغة خذول تبالغ في ذلك؛ ويحتمل أن تكون من كلام الظالم أو حكمًا عامًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص697، تحت عنوان «دلالة ختم الآية بقوله: ﴿وكان الشيطان للإنسان خذولا﴾»","url":""}]},{"id":"s25-38","number":38,"surah":25,"verses":[30],"references":[{"surah":25,"verses":[30]}],"verseLabel":"الفرقان: 30","question":"ما دلالة التعبير بالاتخاذ في قوله: ﴿اتَّخَذُوا هَذَا الْقُرْآنَ مَهْجُورًا﴾؟","answer":"يفيد أن الهجر صار فعلًا مقصودًا وحالة راسخة في معاملتهم للقرآن، لا إعراضًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص702–703، تحت عنوان «دلالة التعبير بالاتخاذ»","url":""}]},{"id":"s25-122","number":122,"surah":25,"verses":[30],"references":[{"surah":25,"verses":[30]}],"verseLabel":"الفرقان: 30","question":"ما غرض اسم الإشارة للقريب في قوله: ﴿هَذَا الْقُرْآنَ﴾؟","answer":"يستحضر القرآن قريبًا ظاهر الحجة ويعظمه، فتشتد المفارقة بين وضوحه وعلو شأنه وبين اتخاذهم إياه مهجورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص703–704، تحت عنوان «الغرض من التعبير باسم الإشارة للقريب»","url":""}]},{"id":"s25-39","number":39,"surah":25,"verses":[31],"references":[{"surah":25,"verses":[31]}],"verseLabel":"الفرقان: 31","question":"ما التشبيه في تقرير أن لكل نبي عدوًا من المجرمين، وما غرضه؟","answer":"شُبه حال الرسول مع أعدائه بأحوال الأنبياء قبله، تسليةً له ودعوة إلى الثبات؛ فالعداوة سنة ماضية لا علامة على ضعف الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص709–710، تحت عنوان «بلاغة التعبير بالتشبيه، وغرضه»","url":""}]},{"id":"s25-123","number":123,"surah":25,"verses":[31],"references":[{"surah":25,"verses":[31]}],"verseLabel":"الفرقان: 31","question":"ما دلالة الواو في قوله: ﴿وَكَفَى بِرَبِّكَ هَادِيًا وَنَصِيرًا﴾؟","answer":"عطفت الطمأنينة بكفاية هداية الله ونصره على ذكر عداوة المجرمين، فدفعت ما قد يورثه الكلام السابق من وحشة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص714، تحت عنوان «معنى الواو ودلالتها في ﴿وكفى بربك﴾»","url":""}]},{"id":"s25-40","number":40,"surah":25,"verses":[32],"references":[{"surah":25,"verses":[32]}],"verseLabel":"الفرقان: 32","question":"ما الحكمة من تعليل نزول القرآن مفرقًا بقوله: ﴿لِنُثَبِّتَ بِهِ فُؤَادَكَ﴾؟","answer":"التنزيل المتتابع يجدد تسلية الرسول ويقوي فؤاده أمام الأذى، وييسر الحفظ ويواكب الحوادث وتدرج الأحكام؛ فالتفريق مظهر حكمة لا نقص إحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص726–727، تحت عنوان «دلالة جملة التثبيت والحكمة منها»","url":""}]},{"id":"s25-41","number":41,"surah":25,"verses":[32],"references":[{"surah":25,"verses":[32]}],"verseLabel":"الفرقان: 32","question":"ما دلالة ﴿ورتلناه ترتيلا﴾ مع نزول القرآن مفرقا؟","answer":"الترتيل يفيد حسن التأليف ووضوح الدلالة وإحكام الترتيب، ويذكر الشرح فيه أيضا معنى تفريق التنزيل. فمع امتداد زمن نزوله بقي متناسقا متماسكا، حتى تبدو السورة كالكلمة الواحدة؛ وهذا من دلائل أنه ليس تأليفا بشريا متفرقا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص728، تحت عنوان «دلالة التعبير بـ﴿ورتلناه﴾ مادة وصيغة»","url":""}]},{"id":"s25-42","number":42,"surah":25,"verses":[33],"references":[{"surah":25,"verses":[33]}],"verseLabel":"الفرقان: 33","question":"ما دلالة الاستثناء في قوله: ﴿وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَاكَ بِالْحَقِّ﴾؟","answer":"يفيد أن كل شبهة أو اعتراض يأتون به يقابله جواب الحق الكاشف لبطلانه، فلا يتركون بلا بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص735، تحت عنوان «دلالة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s25-124","number":124,"surah":25,"verses":[33],"references":[{"surah":25,"verses":[33]}],"verseLabel":"الفرقان: 33","question":"ما دلالة التعبير بـ﴿وَأَحْسَنَ تَفْسِيرًا﴾ مادة وصيغة؟","answer":"يبين تفوق البيان القرآني في إيضاح المراد وإزالة اللبس، ولا يقتضي أفعل التفضيل أن تفسيرهم صحيح أو حسن في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص739، تحت عنوان «دلالة التعبير بـ﴿وأحسن﴾ مادة وصيغة»","url":""}]},{"id":"s25-43","number":43,"surah":25,"verses":[34],"references":[{"surah":25,"verses":[34]}],"verseLabel":"الفرقان: 34","question":"ما دلالة الوعيد بحشرهم على وجوههم؟","answer":"يجمع الوعيد بين إذلالهم وتشويه وجوههم وتعذيبهم، جزاء لإعراضهم عن الحق وقلبهم الهدى ضلالا. فصورة الحشر على الوجوه تناسب انقلاب حالهم عما ظنوه لأنفسهم من العزة وعلو المنزلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص746، تحت عنوان «بلاغة الوعيد لهم من خلال الجمع بين التشويه والتعذيب»","url":""}]},{"id":"s25-44","number":44,"surah":25,"verses":[35],"references":[{"surah":25,"verses":[35]}],"verseLabel":"الفرقان: 35","question":"ما دلالة حرف المعية في قوله: ﴿وَجَعَلْنَا مَعَهُ أَخَاهُ هَارُونَ﴾؟","answer":"تبرز المعية ملازمة هارون لموسى ومساندته له في أداء الرسالة ومواجهة أعبائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص756، تحت عنوان «دلالة التعبير بحرف المعية (مع)»","url":""}]},{"id":"s25-125","number":125,"surah":25,"verses":[35],"references":[{"surah":25,"verses":[35]}],"verseLabel":"الفرقان: 35","question":"ما دلالة التعبير بـ﴿وَزِيرًا﴾ مادة وصيغة؟","answer":"تفيد المعاونة وشد الأزر وحمل ثقل المهمة، فالأخوة هنا أخوة مؤازرة في الدعوة لا مجرد نسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص757، تحت عنوان «دلالة التعبير بـ﴿وزيرا﴾ مادة وصيغة»","url":""}]},{"id":"s25-45","number":45,"surah":25,"verses":[36],"references":[{"surah":25,"verses":[36]}],"verseLabel":"الفرقان: 36","question":"ما الإيجاز بالحذف في الانتقال إلى قوله: ﴿فَدَمَّرْنَاهُمْ تَدْمِيرًا﴾؟","answer":"حذف ما دل عليه السياق: فذهب موسى وهارون ودعوا القوم فكذبوهما، ثم وقع التدمير؛ واقتصر على إقامة الحجة ومآل المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص761–762، تحت عنوان «بلاغة الإيجاز بالحذف في فعل التدمير»","url":""}]},{"id":"s25-46","number":46,"surah":25,"verses":[37],"references":[{"surah":25,"verses":[37]}],"verseLabel":"الفرقان: 37","question":"ما سر التعبير عن قوم نوح بـ﴿كذبوا الرسل﴾ مع أن رسولهم نوح؟","answer":"تكذيب نوح يستلزم تكذيب الرسل جميعا لاتفاق دعوتهم إلى عبادة الله، ولأن إنكارهم بعثة البشر يطعن في أصل الرسالة. ومن وجوه الجمع أيضا تشنيع فعلهم وتأكيد أن تكذيب الرسول الواحد ليس أمرا هينا معزولا عن سائر الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص769، تحت عنوان «نكتة التعبير بالرسل جمعا»","url":""}]},{"id":"s25-47","number":47,"surah":25,"verses":[38],"references":[{"surah":25,"verses":[38]}],"verseLabel":"الفرقان: 38","question":"ما غرض تقديم أسماء عاد وثمود وأصحاب الرس والقرون؟","answer":"يشوق تقديم الأسماء إلى خبرهم، ثم يجمعهم الحكم اللاحق في تلقي الأمثال والإنذار ثم الهلاك بسبب التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص773–774، تحت عنوان «غرض تقديم الأسماء الأربعة»","url":""}]},{"id":"s25-126","number":126,"surah":25,"verses":[38],"references":[{"surah":25,"verses":[38]}],"verseLabel":"الفرقان: 38","question":"ما سر عطف ﴿وَقُرُونًا﴾ على الأقوام المذكورة؟","answer":"وسع العطف دائرة العبرة لتشمل أممًا كثيرة اشتركت في التكذيب والمآل، فلا يظن أن السنة مختصة بالأقوام المسماة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص774، تحت عنوان «سر عطف ﴿وقرونا﴾ على ما تقدمها من الأقوام»","url":""}]},{"id":"s25-127","number":127,"surah":25,"verses":[38],"references":[{"surah":25,"verses":[38]}],"verseLabel":"الفرقان: 38","question":"لماذا ذُكرت ﴿قُرُونًا﴾ من غير تسمية؟","answer":"يفيد الإبهام كثرة الأمم وتنوعها وأن المقصود العبرة بسنة الهلاك لا استقصاء أسمائها وقصصها.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص774، تحت عنوان «سر ذكر ﴿وقرونا﴾ من غير تسميتها»","url":""}]},{"id":"s25-128","number":128,"surah":25,"verses":[38],"references":[{"surah":25,"verses":[38]}],"verseLabel":"الفرقان: 38","question":"ما معنى ﴿أل﴾ في قوله: ﴿ضَرَبْنَا لَهُ الْأَمْثَالَ﴾؟","answer":"هي للعهد، فالمراد الأمثال والقصص العجيبة المعروفة في أخبار الأولين التي تبين عاقبة التكذيب وتقيم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص777، تحت عنوان «معنى (أل) في ﴿الأمثال﴾»","url":""}]},{"id":"s25-48","number":48,"surah":25,"verses":[39],"references":[{"surah":25,"verses":[39]}],"verseLabel":"الفرقان: 39","question":"ما سر توكيد التتبير بالمفعول المطلق؟","answer":"أكد المصدر شدة الإهلاك وتمامه، وصور تدميرًا ساحقًا يناسب الإصرار على التكذيب بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص778، تحت عنوان «سر توكيد التتبير بالمفعول المطلق»","url":""}]},{"id":"s25-49","number":49,"surah":25,"verses":[40],"references":[{"surah":25,"verses":[40]}],"verseLabel":"الفرقان: 40","question":"ما نكتة فصل قوله: ﴿أَفَلَمْ يَكُونُوا يَرَوْنَهَا﴾؟","answer":"استؤنف توبيخهم جوابًا عما يقتضيه مرورهم على قرية لوط، فأنكر عليهم ترك الاعتبار بدليل حاضر أمامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص786، تحت عنوان «نكتة فصل قوله: ﴿أفلم يكونوا يرونها﴾»","url":""}]},{"id":"s25-129","number":129,"surah":25,"verses":[40],"references":[{"surah":25,"verses":[40]}],"verseLabel":"الفرقان: 40","question":"ما فائدة التعبير بفعل الرؤية مضارعًا في قوله: ﴿يَرَوْنَهَا﴾؟","answer":"استحضر تكرر رؤيتهم آثار العذاب في أسفارهم، فزاد التوبيخ لأن الدليل لم يكن عابرًا أو خافيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص788، تحت عنوان «فائدة التعبير بفعل الرؤية مضارعا»","url":""}]},{"id":"s25-130","number":130,"surah":25,"verses":[40],"references":[{"surah":25,"verses":[40]}],"verseLabel":"الفرقان: 40","question":"ما دلالة ﴿بَلْ﴾ في قوله: ﴿بَلْ كَانُوا لَا يَرْجُونَ نُشُورًا﴾؟","answer":"انتقلت من إنكار عدم اعتبارهم بالرؤية إلى كشف سببه الأعمق: إنكارهم البعث والجزاء، وهو ما عطل انتفاعهم بالعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص788–789، تحت عنوان «معنى ﴿بل﴾ ودلالتها»","url":""}]},{"id":"s25-50","number":50,"surah":25,"verses":[41],"references":[{"surah":25,"verses":[41]}],"verseLabel":"الفرقان: 41","question":"ما بلاغة الاستفهام في قولهم: ﴿أَهَذَا الَّذِي بَعَثَ اللَّهُ رَسُولًا﴾؟","answer":"خرج للإنكار والاستهزاء؛ فبعث الرسول عندهم أمر مستبعد، وإسناد البعث إلى الله جار في تهكمهم لا إقرارًا صادقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص798، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s25-131","number":131,"surah":25,"verses":[41],"references":[{"surah":25,"verses":[41]}],"verseLabel":"الفرقان: 41","question":"ما غرض اسم الإشارة القريب ﴿أَهَذَا﴾ في كلامهم؟","answer":"استحضروا الرسول قريبًا في مقام التحقير بزعمهم، فجمعوا بين حضوره أمامهم واستبعاد أن يصطفيه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص798–799، تحت عنوان «غرض التعبير باسم الإشارة القريب ﴿أهذا﴾»","url":""}]},{"id":"s25-51","number":51,"surah":25,"verses":[42],"references":[{"surah":25,"verses":[42]}],"verseLabel":"الفرقان: 42","question":"ما نكتة دخول ﴿إِنْ﴾ على ﴿كَادَ﴾ في قولهم: ﴿إِنْ كَادَ لَيُضِلُّنَا﴾؟","answer":"إن مخففة من الثقيلة واللام فارقة، وفي التركيب توكيد اعترافهم بأن دعوة الرسول قاربت أن تصرفهم عن آلهتهم لقوة حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص801، تحت عنوان «نكتة دخول ﴿إن﴾ على ﴿كاد﴾»","url":""}]},{"id":"s25-132","number":132,"surah":25,"verses":[42],"references":[{"surah":25,"verses":[42]}],"verseLabel":"الفرقان: 42","question":"ما الاستعارة في قولهم عن دعوة الرسول: ﴿لَيُضِلُّنَا عَنْ آلِهَتِنَا﴾؟","answer":"سموا الهداية إلى التوحيد إضلالًا لأنهم اعتقدوا باطلهم طريقًا صحيحًا، فكشفت الاستعارة انقلاب ميزانهم واضطرابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص801–802، تحت عنوان «بلاغة التعبير بالاستعارة»","url":""}]},{"id":"s25-52","number":52,"surah":25,"verses":[43],"references":[{"surah":25,"verses":[43]}],"verseLabel":"الفرقان: 43","question":"ما بلاغة التقديم والتأخير في قوله: ﴿اتَّخَذَ إِلَهَهُ هَوَاهُ﴾؟","answer":"يحتمل تقديم إلهه للعناية، ويحتمل بقاء ترتيب المفعولين على الأصل، أي جعل ما تهواه نفسه معبودًا؛ وفي الوجهين ذم تحكيم الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص14–15، تحت عنوان «بلاغة التقديم والتأخير في ذكر مفعولي ﴿اتخذ﴾»","url":""}]},{"id":"s25-133","number":133,"surah":25,"verses":[43],"references":[{"surah":25,"verses":[43]}],"verseLabel":"الفرقان: 43","question":"ما التشبيه البليغ في قوله: ﴿اتَّخَذَ إِلَهَهُ هَوَاهُ﴾؟","answer":"شبه سلطان الهوى على صاحبه بسلطان الإله المتبوع، فهو يطيعه وينقاد له كطاعة العابد لمعبوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص15، تحت عنوان «بلاغة التشبيه البليغ في تشبيه الهوى بالإله»","url":""}]},{"id":"s25-53","number":53,"surah":25,"verses":[44],"references":[{"surah":25,"verses":[44]}],"verseLabel":"الفرقان: 44","question":"ما بلاغة نفي السمع والعقل عمن اتبع هواه؟","answer":"نُفي انتفاعهم بما يسمعون ويعقلون من الحق، لا مجرد امتلاك الحاسة والعقل؛ فوجود الأدوات بلا استجابة كعدمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص25–26، تحت عنوان «بلاغة نفي السمع والعقل عمن اتبع هواه»","url":""}]},{"id":"s25-134","number":134,"surah":25,"verses":[44],"references":[{"surah":25,"verses":[44]}],"verseLabel":"الفرقان: 44","question":"لماذا جُعل الكافرون أضل من الأنعام؟","answer":"الأنعام تنقاد لراعيها وتتجنب ما يضرها، أما هم فأعرضوا عن هدى ربهم مع قيام الدليل وقدرتهم على النظر، فكان ضلالهم اختياريًا أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص30، تحت عنوان «نكتة جعل الكافرين أضل من الأنعام»","url":""}]},{"id":"s25-54","number":54,"surah":25,"verses":[45],"references":[{"surah":25,"verses":[45]}],"verseLabel":"الفرقان: 45","question":"ما معنى كون الشمس دليلًا على الظل؟","answer":"يستدل بأحوال الشمس على امتداد الظل ونقصه، كما يكشف ضوؤها الظل إذ تعرف الأشياء بأضدادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص47، تحت عنوان «معنى كون الشمس دليلا على الظل»","url":""}]},{"id":"s25-135","number":135,"surah":25,"verses":[45],"references":[{"surah":25,"verses":[45]}],"verseLabel":"الفرقان: 45","question":"ما التشبيه في قوله: ﴿ثُمَّ جَعَلْنَا الشَّمْسَ عَلَيْهِ دَلِيلًا﴾؟","answer":"شُبهت الشمس بالدليل الذي يعرف غيره ويهدي إليه، لأنها تكشف الظل وتحدد أحواله بحركتها وضوئها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص47–48، تحت عنوان «بلاغة التشبيه في قوله سبحانه: ﴿ثم جعلنا الشمس عليه دليلا﴾»","url":""}]},{"id":"s25-55","number":55,"surah":25,"verses":[46],"references":[{"surah":25,"verses":[46]}],"verseLabel":"الفرقان: 46","question":"ما نكتة التعبير بلفظ القبض في قوله: ﴿ثُمَّ قَبَضْنَاهُ﴾؟","answer":"صور إزالة الظل بعد مده كمن يطوي شيئًا بسطه، فجمع المشهد بين الامتداد ثم التقلص.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص49–50، تحت عنوان «نكتة التعبير بلفظ القبض»","url":""}]},{"id":"s25-136","number":136,"surah":25,"verses":[46],"references":[{"surah":25,"verses":[46]}],"verseLabel":"الفرقان: 46","question":"ما سر التعبير بقوله: ﴿إِلَيْنَا﴾ في قبض الظل؟","answer":"اختص الله بتدبير الظل وردّه، فنفى أن يشاركه أحد في هذا التصرف وأبرز رجوع الأمر كله إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص50، تحت عنوان «سر التعبير بقوله تعالى: ﴿إلينا﴾»","url":""}]},{"id":"s25-137","number":137,"surah":25,"verses":[46],"references":[{"surah":25,"verses":[46]}],"verseLabel":"الفرقان: 46","question":"ما الكناية في وصف قبض الظل بأنه ﴿يَسِيرًا﴾؟","answer":"تحتمل قبضه تدريجيًا بما يحفظ مصالح الخلق، وتحتمل سهولته على الله عند تمامه؛ فكلا الوجهين يبرز لطف التدبير وكمال القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص51، تحت عنوان «بلاغة الكناية في قوله: ﴿يسيرا﴾»","url":""}]},{"id":"s25-56","number":56,"surah":25,"verses":[47],"references":[{"surah":25,"verses":[47]}],"verseLabel":"الفرقان: 47","question":"ما التشبيه في وصف الليل بأنه ﴿لِبَاسًا﴾؟","answer":"شُبه الليل باللباس لأنه يستر الموجودات بظلمته ويمنح السكون والطمأنينة. فجاء اسم المشبه به وحده مبالغة في إحاطة الستر.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص58، تحت عنوان «بلاغة التشبيه في قوله جل ذكره: ﴿لباسا﴾»","url":""}]},{"id":"s25-138","number":138,"surah":25,"verses":[47],"references":[{"surah":25,"verses":[47]}],"verseLabel":"الفرقان: 47","question":"ما المراد بالسبات في قوله: ﴿وَجَعَلَ النَّوْمَ سُبَاتًا﴾؟","answer":"السبات قطع الحركة والعمل للراحة، فجعل النوم زمنًا لانقطاع التعب وتجدد القوة، لا فناءً أو موتًا حقيقيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص59–60، تحت عنوان «المراد بالسبات في قوله تعالى: ﴿سباتا﴾»","url":""}]},{"id":"s25-139","number":139,"surah":25,"verses":[47],"references":[{"surah":25,"verses":[47]}],"verseLabel":"الفرقان: 47","question":"ما المراد بالنشور في قوله: ﴿وَجَعَلَ النَّهَارَ نُشُورًا﴾؟","answer":"هو انتشار الناس في النهار لطلب المعاش بعد سكون النوم، وفيه تذكير بنشور الخلق بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص61، تحت عنوان «المراد بالنشور في قوله: ﴿وجعل النهار نشورا﴾»","url":""}]},{"id":"s25-57","number":57,"surah":25,"verses":[48],"references":[{"surah":25,"verses":[48]}],"verseLabel":"الفرقان: 48","question":"ما الاستعارة في قوله عن الرياح: ﴿بَيْنَ يَدَيْ رَحْمَتِهِ﴾؟","answer":"صُورت الرياح كبشير يتقدم المطر، وصُور المطر بالرحمة؛ فالمعنى أنها تسبق نزول الغيث وتدل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص69–70، تحت عنوان «بلاغة الاستعارة في قوله: ﴿بين يدي رحمته﴾»","url":""}]},{"id":"s25-140","number":140,"surah":25,"verses":[48],"references":[{"surah":25,"verses":[48]}],"verseLabel":"الفرقان: 48","question":"ما سر إضافة الرحمة إلى الله في قوله: ﴿رَحْمَتِهِ﴾؟","answer":"تشرف المطر بإضافته إلى الله، وتقرر أنه أثر من رحمته وتدبيره لا مجرد ظاهرة مستقلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص70، تحت عنوان «سر الإضافة في قوله تعالى: ﴿رحمته﴾»","url":""}]},{"id":"s25-58","number":58,"surah":25,"verses":[49],"references":[{"surah":25,"verses":[49]}],"verseLabel":"الفرقان: 49","question":"ما سر تذكير وصف ﴿بلدة﴾ في ﴿بلدة ميتا﴾؟","answer":"من وجوهه مراعاة معنى البلدة، وهو الموضع أو المكان، فجاء الوصف مذكرا على المعنى. ويذكر الشرح أيضا أن التاء في ﴿بلدة﴾ قد تفيد المبالغة، أو أن ﴿ميتا﴾ بمنزلة المصدر الذي يوصف به المذكر والمؤنث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص77، تحت عنوان «علة تذكير وصف البلدة: ﴿ميتا﴾»","url":""}]},{"id":"s25-59","number":59,"surah":25,"verses":[50],"references":[{"surah":25,"verses":[50]}],"verseLabel":"الفرقان: 50","question":"ما سر إيثار الضمير في قوله: ﴿وَلَقَدْ صَرَّفْنَاهُ بَيْنَهُمْ﴾؟","answer":"أعاد الضمير إلى الماء أو القرآن بحسب التفسير، وإيثاره يربط الكلام بالسياق ويستوعب وجوه التصريف من توزيع المطر أو تنويع البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص84–85، تحت عنوان «سر إيثار الضمير في قوله تعالى: ﴿صرفناه﴾»","url":""}]},{"id":"s25-141","number":141,"surah":25,"verses":[50],"references":[{"surah":25,"verses":[50]}],"verseLabel":"الفرقان: 50","question":"ما دلالة اللام في قوله: ﴿لِيَذَّكَّرُوا﴾؟","answer":"هي للتعليل؛ فغاية التصريف أن يتعظوا ويعرفوا النعمة وقدرة المنعم، لا أن يمروا بالآية غافلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص85، تحت عنوان «بلاغة اللام في قوله سبحانه: ﴿ليذكروا﴾»","url":""}]},{"id":"s25-60","number":60,"surah":25,"verses":[52],"references":[{"surah":25,"verses":[52]}],"verseLabel":"الفرقان: 52","question":"ما دلالة الأمر في قوله: ﴿وَجَاهِدْهُمْ﴾، وما المراد به؟","answer":"الأمر للثبات وبذل الوسع في إقامة الحجة ومقاومة باطل الكافرين، والمراد هنا جهاد البيان بالقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص95، تحت عنوان «دلالة الأمر في قوله تعالى: ﴿وجاهدهم﴾، والمراد به»","url":""}]},{"id":"s25-142","number":142,"surah":25,"verses":[52],"references":[{"surah":25,"verses":[52]}],"verseLabel":"الفرقان: 52","question":"إلى ماذا يعود الضمير في قوله: ﴿وَجَاهِدْهُمْ بِهِ﴾؟","answer":"يعود إلى القرآن، أي جاهدهم بحججه وبيانه؛ وقيل يعود إلى ترك الطاعة المفهوم من النهي، والأول أوضح سياقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص96، تحت عنوان «مرجع الضمير في قوله جل وعز: ﴿به﴾»","url":""}]},{"id":"s25-143","number":143,"surah":25,"verses":[52],"references":[{"surah":25,"verses":[52]}],"verseLabel":"الفرقان: 52","question":"لماذا وُصف الجهاد بأنه ﴿كَبِيرًا﴾؟","answer":"لعظم أثر الحجة في إبطال الشرك، ولما يحتاجه تبليغ القرآن من صبر وثبات ومجاهدة مستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص97–98، تحت عنوان «سر وصف الجهاد بكونه كبيرا»","url":""}]},{"id":"s25-61","number":61,"surah":25,"verses":[53],"references":[{"surah":25,"verses":[53]}],"verseLabel":"الفرقان: 53","question":"ما سر فصل قوله: ﴿هَذَا عَذْبٌ فُرَاتٌ﴾؟","answer":"استؤنف البيان لتفصيل حال البحرين بعد ذكر مرجهما، فكأن سؤالًا نشأ عن صفتهما فأجيب بوصف كل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص104، تحت عنوان «سر الفصل في ﴿هذا عذب فرات﴾»","url":""}]},{"id":"s25-144","number":144,"surah":25,"verses":[53],"references":[{"surah":25,"verses":[53]}],"verseLabel":"الفرقان: 53","question":"ما دلالة اسمي الإشارة في وصف البحرين؟","answer":"استحضرا البحرين كأنهما مشاهدان، وميزا كل واحد بصفاته رغم اجتماعهما وتقاربهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص104، تحت عنوان «دلالة التعبير باسم الإشارة»","url":""}]},{"id":"s25-145","number":145,"surah":25,"verses":[53],"references":[{"surah":25,"verses":[53]}],"verseLabel":"الفرقان: 53","question":"ما بلاغة الجمع بين ﴿عَذْبٌ فُرَاتٌ﴾ و﴿مِلْحٌ أُجَاجٌ﴾؟","answer":"أبرزت المقابلة تمام التضاد بين شدة العذوبة وشدة الملوحة، مع قدرة الله على إبقاء الحاجز بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص105، تحت عنوان «بلاغة الجمع بين العذب الفرات والملح الأجاج»","url":""}]},{"id":"s25-62","number":62,"surah":25,"verses":[54],"references":[{"surah":25,"verses":[54]}],"verseLabel":"الفرقان: 54","question":"ما سر ﴿مِنْ﴾ الابتدائية في قوله: ﴿خَلَقَ مِنَ الْمَاءِ بَشَرًا﴾؟","answer":"بينت ابتداء خلق البشر من الماء وأبرزت القدرة على إنشاء الكائن العاقل من أصل بسيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص112، تحت عنوان «سر التعبير بـ﴿من﴾ الابتدائية»","url":""}]},{"id":"s25-146","number":146,"surah":25,"verses":[54],"references":[{"surah":25,"verses":[54]}],"verseLabel":"الفرقان: 54","question":"ما سر الجمع بين ﴿نَسَبًا وَصِهْرًا﴾؟","answer":"جمع القرابة بالولادة والقرابة بالمصاهرة، فاستوعب الروابط التي يتكاثر بها البشر ويتآلفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص114–115، تحت عنوان «سر التعبير بالنسب والصهر في قوله تعالى: ﴿فجعله نسبا وصهرا﴾»","url":""}]},{"id":"s25-63","number":63,"surah":25,"verses":[55],"references":[{"surah":25,"verses":[55]}],"verseLabel":"الفرقان: 55","question":"ما نكتة التعبير بعنوان الربوبية في قوله: ﴿عَلَى رَبِّهِ ظَهِيرًا﴾؟","answer":"زاد ذكر الرب قبح معاونة الكافر على معصية من خلقه ورباه وأنعم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص125، تحت عنوان «نكتة التعبير بعنوان الربوبية»","url":""}]},{"id":"s25-147","number":147,"surah":25,"verses":[55],"references":[{"surah":25,"verses":[55]}],"verseLabel":"الفرقان: 55","question":"ما المراد بقوله: ﴿ظَهِيرًا﴾؟","answer":"أي معينًا للشيطان أو لأهل الباطل على ما يسخط الله، أو هينًا متروكًا؛ والجامع ذم موقفه من حق ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص125–126، تحت عنوان «المراد بقوله تعالى: ﴿ظهيرا﴾»","url":""}]},{"id":"s25-64","number":64,"surah":25,"verses":[57],"references":[{"surah":25,"verses":[57]}],"verseLabel":"الفرقان: 57","question":"ما دلالة الاستثناء في قوله: ﴿إِلَّا مَنْ شَاءَ أَنْ يَتَّخِذَ إِلَى رَبِّهِ سَبِيلًا﴾؟","answer":"على الانقطاع لا يطلب أجرًا وإنما يدعو إلى الإيمان، وعلى الاتصال يكون الأجر المجازي هو استجابة من شاء؛ وفي الوجهين ينتفي الأجر الدنيوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص138–139، تحت عنوان «دلالة الاستثناء بين الانقطاع والاتصال»","url":""}]},{"id":"s25-148","number":148,"surah":25,"verses":[57],"references":[{"surah":25,"verses":[57]}],"verseLabel":"الفرقان: 57","question":"ما إيجاز الحذف في قوله: ﴿إِلَّا مَنْ شَاءَ﴾؟","answer":"حذف ما دل عليه السياق، أي إلا عمل أو إنفاق من شاء أن يتقرب إلى ربه، فاتسع اللفظ لسبل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص139، تحت عنوان «دلالة إيجاز الحذف في ﴿إلا من شاء﴾»","url":""}]},{"id":"s25-65","number":65,"surah":25,"verses":[58],"references":[{"surah":25,"verses":[58]}],"verseLabel":"الفرقان: 58","question":"لماذا قيل: ﴿وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ﴾ بدل «على الله»؟","answer":"استدعى الوصف علة التوكل: دوام حياة المتوكل عليه وكمال قدرته، بخلاف كل حي يفنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص148، تحت عنوان «سر العدول عن (وتوكل على الله)»","url":""}]},{"id":"s25-149","number":149,"surah":25,"verses":[58],"references":[{"surah":25,"verses":[58]}],"verseLabel":"الفرقان: 58","question":"ما نكتة وصف الحي بقوله: ﴿الَّذِي لَا يَمُوتُ﴾؟","answer":"أكد دوام حياته ونفى عنها كل انقطاع، فاطمأن القلب إلى سند لا يزول ولا يعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص148–149، تحت عنوان «نكتة وصف الحي بـ﴿الذي لا يموت﴾»","url":""}]},{"id":"s25-66","number":66,"surah":25,"verses":[59],"references":[{"surah":25,"verses":[59]}],"verseLabel":"الفرقان: 59","question":"ما سر التثنية في ﴿وما بينهما﴾ مع جمع السماوات؟","answer":"روعيت السماوات والأرض بوصفهما صنفين أو نوعين، لا عدد آحاد السماوات؛ فجاء ضمير التثنية عائدا إلى هذين الصنفين وما بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص157، تحت عنوان «نكتة التعبير بـ﴿بينهما﴾»","url":""}]},{"id":"s25-67","number":67,"surah":25,"verses":[60],"references":[{"surah":25,"verses":[60]}],"verseLabel":"الفرقان: 60","question":"لماذا اختير اسم الله ﴿الرَّحْمَنُ﴾ في الأمر بالسجود؟","answer":"ناسب ما سبق من آثار الرحمة، ودعاهم إلى عبادة من عمت رحمته مع تعريض بجحودهم نعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص165–166، تحت عنوان «سر اختيار اسم الله (الرحمن)»","url":""}]},{"id":"s25-150","number":150,"surah":25,"verses":[60],"references":[{"surah":25,"verses":[60]}],"verseLabel":"الفرقان: 60","question":"ما دلالة الاستفهام في قولهم: ﴿وَمَا الرَّحْمَنُ﴾؟","answer":"خرج للإنكار أو التجاهل والاستهزاء، فكشف نفورهم من الاسم ومن الأمر بالسجود لا طلبهم معرفة صادقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص166–167، تحت عنوان «دلالة الاستفهام في ﴿وما الرحمن﴾»","url":""}]},{"id":"s25-68","number":68,"surah":25,"verses":[61],"references":[{"surah":25,"verses":[61]}],"verseLabel":"الفرقان: 61","question":"ما علة وصل قوله: ﴿وَجَعَلَ فِيهَا سِرَاجًا﴾ بما قبله؟","answer":"عطف تفصيل منافع السماء وزينتها على خلق البروج فيها، فجمع دلائل القدرة في نسق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص173، تحت عنوان «علة وصل جملة: ﴿وجعل فيها سراجا﴾ بما قبلها»","url":""}]},{"id":"s25-151","number":151,"surah":25,"verses":[61],"references":[{"surah":25,"verses":[61]}],"verseLabel":"الفرقان: 61","question":"ما نكتة المغايرة بين وصف الشمس ﴿سِرَاجًا﴾ والقمر ﴿مُنِيرًا﴾؟","answer":"السراج مصدر الضوء والحرارة، أما المنير فيفيض نورًا لطيفًا؛ فوافق كل وصف الأثر المشاهد لجرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص175، تحت عنوان «نكتة المغايرة بين ﴿سراجا﴾ و﴿منيرا﴾»","url":""}]},{"id":"s25-69","number":69,"surah":25,"verses":[62],"references":[{"surah":25,"verses":[62]}],"verseLabel":"الفرقان: 62","question":"ما دلالة صيغة ﴿فِعْلَة﴾ في لفظ ﴿خِلْفَةً﴾؟","answer":"تفيد هيئة تعاقب الليل والنهار وقيام كل منهما مقام الآخر فيما يفوت من عمل واعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص180، تحت عنوان «دلالة اختيار صيغة (فعلة) في الخلفة»","url":""}]},{"id":"s25-152","number":152,"surah":25,"verses":[62],"references":[{"surah":25,"verses":[62]}],"verseLabel":"الفرقان: 62","question":"ما معنى اللام في قوله: ﴿لِمَنْ أَرَادَ﴾؟","answer":"هي للتعليل أو الاختصاص، فالتعاقب ينتفع به من قصد التذكر والشكر، مع أن الآية قائمة للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص181، تحت عنوان «معنى اللام في ﴿لمن﴾ ودلالتها»","url":""}]},{"id":"s25-153","number":153,"surah":25,"verses":[62],"references":[{"surah":25,"verses":[62]}],"verseLabel":"الفرقان: 62","question":"ما أثر قراءتي ﴿يَذَّكَّرَ﴾ و﴿يَذْكُرَ﴾؟","answer":"التشديد يفيد الاتعاظ والتذكر، والتخفيف يفيد الذكر باللسان أو القلب؛ فتتسع الغاية للاعتبار والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص181–182، تحت عنوان «توجيه القراءات في (يَذَّكَّرَ) و(يَذْكُرَ)»","url":""}]},{"id":"s25-70","number":70,"surah":25,"verses":[63],"references":[{"surah":25,"verses":[63]}],"verseLabel":"الفرقان: 63","question":"ما سر اختيار فعل المشي في وصف عباد الرحمن؟","answer":"المشي حال ظاهرة متكررة تكشف السمت والخلق في تعاملهم اليومي، فبدأ بها تصوير تواضعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص189، تحت عنوان «سر اختيار فعل المشي»","url":""}]},{"id":"s25-154","number":154,"surah":25,"verses":[63],"references":[{"surah":25,"verses":[63]}],"verseLabel":"الفرقان: 63","question":"ما الكناية في مشيهم على الأرض ﴿هَوْنًا﴾؟","answer":"كناية عن السكينة والتواضع وترك الخيلاء، لا عن الضعف أو التكلف في الحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص190، تحت عنوان «دلالة الكناية في مشيهم هونا»","url":""}]},{"id":"s25-71","number":71,"surah":25,"verses":[63],"references":[{"surah":25,"verses":[63]}],"verseLabel":"الفرقان: 63","question":"ما دلالة جواب عباد الرحمن للجاهلين بـ﴿سلاما﴾؟","answer":"يدل على السلامة من الإثم ومجاراة السفه: يقولون قولا سالما من العدوان، أو يفارقون مخاطبيهم بسلام. ويذكر الشرح احتمال إرادة لفظ التحية نفسه؛ فالمقصود ألا يقابلوا السفه بمثله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص191، تحت عنوان «دلالة الكناية في لفظ ﴿سلاما﴾»","url":""}]},{"id":"s25-72","number":72,"surah":25,"verses":[64],"references":[{"surah":25,"verses":[64]}],"verseLabel":"الفرقان: 64","question":"ما دلالة إعادة الموصول ﴿وَالَّذِينَ يَبِيتُونَ﴾؟","answer":"استأنف صفة مستقلة من صفاتهم ولفت إليها، مع ربطها بسلسلة خصال عباد الرحمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص195، تحت عنوان «دلالة إعادة الموصول (الذين)»","url":""}]},{"id":"s25-155","number":155,"surah":25,"verses":[64],"references":[{"surah":25,"verses":[64]}],"verseLabel":"الفرقان: 64","question":"ما دلالة تقديم ﴿لِرَبِّهِمْ﴾؟","answer":"اختص سجودهم وقيامهم بربهم وأبرز الإخلاص له، لا طلب نظر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص196–197، تحت عنوان «دلالة تقديم الجار والمجرور ﴿لربهم﴾»","url":""}]},{"id":"s25-156","number":156,"surah":25,"verses":[64],"references":[{"surah":25,"verses":[64]}],"verseLabel":"الفرقان: 64","question":"لماذا قُدم السجود على القيام؟","answer":"لأن السجود أبلغ في الخضوع والقرب، فقدم تشريفًا له مع أن القيام يسبقه في ترتيب الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص197، تحت عنوان «دلالة تقديم السجود على القيام»","url":""}]},{"id":"s25-157","number":157,"surah":25,"verses":[64],"references":[{"surah":25,"verses":[64]}],"verseLabel":"الفرقان: 64","question":"ما الكناية في قوله: ﴿سُجَّدًا وَقِيَامًا﴾؟","answer":"كناية عن إحياء الليل بالصلاة والعبادة، فذكر أبرز هيئتين وأريد دوام التهجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص197، تحت عنوان «بلاغة الكناية في لفظتي ﴿سجدا وقياما﴾»","url":""}]},{"id":"s25-73","number":73,"surah":25,"verses":[65,66],"references":[{"surah":25,"verses":[65,66]}],"verseLabel":"الفرقان: 65-66","question":"ما دلالة ﴿كَانَ﴾ في قوله: ﴿إِنَّ عَذَابَهَا كَانَ غَرَامًا﴾؟","answer":"تفيد ثبوت ملازمة عذاب جهنم واستقراره، لا أنه مضى وانقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص202، تحت عنوان «دلالة التعبير بفعل الكون ﴿كان﴾»","url":""}]},{"id":"s25-158","number":158,"surah":25,"verses":[65,66],"references":[{"surah":25,"verses":[65,66]}],"verseLabel":"الفرقان: 65-66","question":"لماذا اختير فعل ﴿اصْرِفْ﴾ في الدعاء؟","answer":"صور العذاب كشيء متوجه إليهم يطلبون من ربهم إبعاده وتحويله عنهم قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص202، تحت عنوان «سر التعبير بفعل الصرف ﴿اصرف﴾»","url":""}]},{"id":"s25-74","number":74,"surah":25,"verses":[67],"references":[{"surah":25,"verses":[67]}],"verseLabel":"الفرقان: 67","question":"ما دلالة ﴿قواما﴾ بين الإسراف والتقتير؟","answer":"القوام هو العدل والقصد في النفقة، بوضعها في مواضعها بحسب أمر الله؛ فلا إسراف يستنفد المال ولا إمساك مذموم يضيع الحقوق. فالوسط هنا اعتدال منضبط، لا مجرد مقدار حسابي بين طرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص208، تحت عنوان «دلالة لفظ ﴿قواما﴾ في سياق الآية الكريمة»","url":""}]},{"id":"s25-75","number":75,"surah":25,"verses":[68],"references":[{"surah":25,"verses":[68]}],"verseLabel":"الفرقان: 68","question":"ما دلالة العطف بالواو بين نفي الشرك والقتل والزنا؟","answer":"جمع الكبائر الثلاث مع استقلال كل منها في التحريم والوعيد، من غير اشتراط اجتماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص219–220، تحت عنوان «دلالة العطف بالواو»","url":""}]},{"id":"s25-159","number":159,"surah":25,"verses":[68],"references":[{"surah":25,"verses":[68]}],"verseLabel":"الفرقان: 68","question":"ما نكتة تكرار ﴿لَا﴾ مع الأفعال الثلاثة؟","answer":"أكد نفي كل جريمة على حدة ومنع توهم أن المنفي مجموعها فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص220، تحت عنوان «نكتة تكرار (لا) في نفي الأفعال الثلاثة»","url":""}]},{"id":"s25-160","number":160,"surah":25,"verses":[68],"references":[{"surah":25,"verses":[68]}],"verseLabel":"الفرقان: 68","question":"ما سر ترتيب الأفعال المنفية؟","answer":"بدأ بالشرك لأنه أعظم حقوق الله، ثم قتل النفس، ثم الزنا؛ فانتقل من الأشد والأعم فسادًا إلى ما دونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص220–221، تحت عنوان «سر ترتيب الأفعال المنفية»","url":""}]},{"id":"s25-76","number":76,"surah":25,"verses":[69],"references":[{"surah":25,"verses":[69]}],"verseLabel":"الفرقان: 69","question":"ما سر فصل جملة ﴿يُضَاعَفْ لَهُ الْعَذَابُ﴾؟","answer":"جاءت بيانًا لعاقبة من يلق أثامًا، كجواب عن سؤال مقدر عن حقيقة ذلك الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص228، تحت عنوان «سر فصل جملة ﴿يضاعف﴾ عما قبلها»","url":""}]},{"id":"s25-161","number":161,"surah":25,"verses":[69],"references":[{"surah":25,"verses":[69]}],"verseLabel":"الفرقان: 69","question":"ما بلاغة الفعل ﴿يُضَاعَفْ﴾؟","answer":"صور تكرر العذاب وزيادته بحسب تعدد الجرائم وعظمها، مع البناء للمجهول للتركيز على هول الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص229، تحت عنوان «بلاغة التعبير بالفعل ﴿يضاعف﴾»","url":""}]},{"id":"s25-162","number":162,"surah":25,"verses":[69],"references":[{"surah":25,"verses":[69]}],"verseLabel":"الفرقان: 69","question":"ما دلالة الحال ﴿مُهَانًا﴾ مادة وصيغة؟","answer":"أضافت إلى ألم العذاب ذلًا ثابتًا، فاسم المفعول يصور وقوع الإهانة واستمرار أثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص231، تحت عنوان «بيان التعبير بالحال ﴿مهانا﴾ دلالة وصيغة»","url":""}]},{"id":"s25-78","number":78,"surah":25,"verses":[70],"references":[{"surah":25,"verses":[70]}],"verseLabel":"الفرقان: 70","question":"ما وجها تبديل السيئات حسنات في قوله ﴿يبدل الله سيئاتهم حسنات﴾؟","answer":"يذكر الشرح وجهين: تبديل جزاء السيئات للتائبين حسنات يوم القيامة، أو توفيقهم في الدنيا إلى أضداد معاصيهم، فيحل الإيمان محل الشرك والطاعة محل المعصية. والوعد مرتبط بالتوبة والإيمان والعمل الصالح المذكورة في الآية، وهو مظهر لفضل الله ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص240–241، تحت عنوان «دلالة التعبير بفعل التبديل مادة وصيغة»","url":""}]},{"id":"s25-79","number":79,"surah":25,"verses":[72],"references":[{"surah":25,"verses":[72]}],"verseLabel":"الفرقان: 72","question":"ما المجاز في قوله: ﴿لَا يَشْهَدُونَ الزُّورَ﴾؟","answer":"يحتمل الشهود معنى الحضور أو الشهادة، فيعم اجتناب مجالس الباطل وعدم قول الزور أو إقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص255، تحت عنوان «بلاغة المجاز في ﴿لا يشهدون الزور﴾»","url":""}]},{"id":"s25-163","number":163,"surah":25,"verses":[72],"references":[{"surah":25,"verses":[72]}],"verseLabel":"الفرقان: 72","question":"ما دلالة وصف مرورهم باللغو بـ﴿كِرَامًا﴾؟","answer":"يمرون منزهين أنفسهم عن المشاركة، محافظين على وقارهم بلا دناءة ولا تشفٍ، فالكلمة تجمع العفة والسمو.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص257، تحت عنوان «وجه التعبير بلفظ ﴿كراما﴾ دلالة وصيغة»","url":""}]},{"id":"s25-80","number":80,"surah":25,"verses":[73],"references":[{"surah":25,"verses":[73]}],"verseLabel":"الفرقان: 73","question":"ما دلالة ﴿لم يخروا عليها صما وعميانا﴾ عند تذكيرهم بالآيات؟","answer":"على توجيه كثير من المفسرين لا ينفي الكلام إقبالهم على الآيات، بل ينفي أن يكون إقبالا بلا سمع واع ولا بصيرة؛ فهم يتلقونها للفهم والعمل. ويذكر الشرح وجها يتوجه فيه النفي إلى الخرور والقيد معا؛ والجامع انتفاء الإعراض وعدم الانتفاع بالذكر عن عباد الرحمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص265، تحت عنوان «بلاغة النفي والإثبات في الآية»","url":""}]},{"id":"s25-81","number":81,"surah":25,"verses":[74],"references":[{"surah":25,"verses":[74]}],"verseLabel":"الفرقان: 74","question":"ما نكتة الجمع بين الأزواج والذريات في الدعاء؟","answer":"جمع أقرب دوائر الأسرة ليكتمل سرور المؤمن بصلاح زوجه وامتداد الخير في نسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص275، تحت عنوان «نكتة الجمع بين الأزواج والذريات»","url":""}]},{"id":"s25-164","number":164,"surah":25,"verses":[74],"references":[{"surah":25,"verses":[74]}],"verseLabel":"الفرقان: 74","question":"ما الكناية في قوله: ﴿قُرَّةَ أَعْيُنٍ﴾؟","answer":"كناية عن بالغ السرور والطمأنينة بصلاح الأهل، حتى تسكن العين ولا تتطلع إلى غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص276–277، تحت عنوان «بلاغة الكناية في ﴿قرة أعين﴾»","url":""}]},{"id":"s25-82","number":82,"surah":25,"verses":[74],"references":[{"surah":25,"verses":[74]}],"verseLabel":"الفرقان: 74","question":"ما وجه إفراد ﴿إِمَامًا﴾ ودلالته؟","answer":"الإمام اسم جنس يصلح للواحد والجمع، أو أُفرد لاتحادهم في القدوة والمنهج؛ وفيه طلب بلوغ منزلة يُقتدى بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص279، تحت عنوان «وجه التعبير بلفظ ﴿إماما﴾ دلالة وصيغة»","url":""}]},{"id":"s25-165","number":165,"surah":25,"verses":[74],"references":[{"surah":25,"verses":[74]}],"verseLabel":"الفرقان: 74","question":"ما سر جمع ﴿الْمُتَّقِينَ﴾ وتقديمه مع الجار؟","answer":"عم الجمع جماعة أهل التقوى، وتقديم ﴿للمتقين﴾ أبرز أن مطلوبهم قدوة الخير خاصة لا مطلق الزعامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص279، تحت عنوان «سر جمع المتقين وتقديمه مع الجار»","url":""}]},{"id":"s25-83","number":83,"surah":25,"verses":[75],"references":[{"surah":25,"verses":[75]}],"verseLabel":"الفرقان: 75","question":"لماذا أوثر لفظ ﴿الْغُرْفَةَ﴾ على الجنة؟","answer":"خص أعلى منازل الجنة وأشرفها تصويرًا لرفعة جزائهم، مع دخولها في نعيم الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص286، تحت عنوان «إيثار لفظ الغرفة على الجنة»","url":""}]},{"id":"s25-166","number":166,"surah":25,"verses":[75],"references":[{"surah":25,"verses":[75]}],"verseLabel":"الفرقان: 75","question":"لماذا خُص الصبر من صفاتهم سببًا للجزاء؟","answer":"لأنه جامع ثباتهم على الطاعة وكفهم عن المعصية واحتمالهم الأذى، وبه استداموا سائر الخصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص288، تحت عنوان «دلالة تخصيص صفة الصبر من بين الصفات»","url":""}]},{"id":"s25-84","number":84,"surah":25,"verses":[77],"references":[{"surah":25,"verses":[77]}],"verseLabel":"الفرقان: 77","question":"ما دلالة قوله: ﴿لَوْلَا دُعَاؤُكُمْ﴾؟","answer":"يحتمل دعاء العباد لله أو دعوة الله لهم إلى الإيمان؛ وفي الوجهين لا وزن لهم لولا صلتهم بالعبادة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص301–302، تحت عنوان «دلالة التعبير بـ﴿لولا دعاؤكم﴾»","url":""}]},{"id":"s25-167","number":167,"surah":25,"verses":[77],"references":[{"surah":25,"verses":[77]}],"verseLabel":"الفرقان: 77","question":"ما معنى الفاء في قوله: ﴿فَقَدْ كَذَّبْتُمْ﴾؟","answer":"فرعت الحكم على البيان السابق: لما كانت قيمتكم بالدعاء وقد كذبتم، ثبت استحقاق العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص302، تحت عنوان «معنى حرف الفاء»","url":""}]},{"id":"s25-168","number":168,"surah":25,"verses":[77],"references":[{"surah":25,"verses":[77]}],"verseLabel":"الفرقان: 77","question":"ما دلالة لفظ ﴿لِزَامًا﴾ مادة وصيغة؟","answer":"يصور العذاب أو أثر التكذيب أمرًا ملازمًا لا يفارقهم، والمصدر يفيد الثبوت واللزوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص304، تحت عنوان «توجيه لفظ ﴿لزاما﴾ دلالة وصيغة»","url":""}]},{"id":"s26-1","number":1,"surah":26,"verses":[2],"references":[{"surah":26,"verses":[2]}],"verseLabel":"الشعراء: 2","question":"ما دلالة التعبير بـ﴿الْكِتَابِ﴾ دون «القرآن» في مطلع الشعراء؟","answer":"يبرز لفظ الكتاب أنه المنزل الجامع للحق والشرائع والحكم والهدايات، فيلفت إلى كمال مضمونه وثبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص321، تحت عنوان «دلالة التعبير بلفظ ﴿الكتاب﴾ دون (القرآن)»","url":""}]},{"id":"s26-97","number":97,"surah":26,"verses":[2],"references":[{"surah":26,"verses":[2]}],"verseLabel":"الشعراء: 2","question":"ما دلالة وصف الكتاب بأنه ﴿الْمُبِينِ﴾ في مطلع الشعراء؟","answer":"يدل على وضوح آياته في نفسها وإبانتها الحق من الباطل، فلا يكون إعراض المكذبين ناشئًا عن خفاء الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص322، تحت عنوان «دلالة وصف الكتاب بلفظ ﴿المبين﴾»","url":""}]},{"id":"s26-98","number":98,"surah":26,"verses":[2],"references":[{"surah":26,"verses":[2]}],"verseLabel":"الشعراء: 2","question":"ما نكتة عطف ﴿وَكِتَابٍ مُبِينٍ﴾ على ﴿الْقُرْآنِ﴾ في مطلع النمل؟","answer":"العطف جمع وصفين لمسمى واحد: فهو قرآن متلو وكتاب جامع مكتوب، فنوّه بكمال الوحي من جهتي التلاوة والتدوين، لا بكتابين مختلفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص589–590، تحت عنوان «نكتة عطف ﴿وكتاب مبين﴾»","url":""}]},{"id":"s26-2","number":2,"surah":26,"verses":[3],"references":[{"surah":26,"verses":[3]}],"verseLabel":"الشعراء: 3","question":"ما دلالة ﴿لَعَلَّ﴾ في قوله: ﴿لَعَلَّكَ بَاخِعٌ نَفْسَكَ﴾؟","answer":"خرج الترجي إلى الإشفاق على النبي ﷺ، وفيه حث على الرفق بنفسه وألا يستولي عليه الحزن لفوات إيمان قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص326، تحت عنوان «دلالة التعبير بحرف الترجي (لعل)»","url":""}]},{"id":"s26-3","number":3,"surah":26,"verses":[3],"references":[{"surah":26,"verses":[3]}],"verseLabel":"الشعراء: 3","question":"ما سر التعبير بـ﴿ألا يكونوا مؤمنين﴾ دون «ألا يؤمنوا»؟","answer":"نفي الكون مع وصف الإيمان يصور استمرار بقائهم غير مؤمنين ورسوخ ذلك فيهم، لا فوات فعل عارض وحده. وفيه تسلية للرسول ألا يهلك نفسه حزنا على إعراضهم المستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص327–328، تحت عنوان «سر العدول عن نفي الإيمان إلى نفي الكون»","url":""}]},{"id":"s26-4","number":4,"surah":26,"verses":[4],"references":[{"surah":26,"verses":[4]}],"verseLabel":"الشعراء: 4","question":"ما دلالة النفي الضمني عن المشيئة في قوله: ﴿إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً﴾؟","answer":"يدل على أن الله لم يشأ إلجاءهم إلى الإيمان بآية قاهرة، بل شاء أن تقوم الحجة مع بقاء الاختيار الذي يترتب عليه التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص329، تحت عنوان «دلالة النفي الضمني عن المشيئة»","url":""}]},{"id":"s26-99","number":99,"surah":26,"verses":[4],"references":[{"surah":26,"verses":[4]}],"verseLabel":"الشعراء: 4","question":"ما دلالة الجملة الشرطية في قوله: ﴿إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّمَاءِ آيَةً﴾؟","answer":"تقرر قدرته تعالى على إنزال آية تلجئهم إلى الخضوع، وتبين أن عدم وقوعها راجع إلى الحكمة لا إلى العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص330، تحت عنوان «دلالة التعبير بالجملة الشرطية»","url":""}]},{"id":"s26-100","number":100,"surah":26,"verses":[4],"references":[{"surah":26,"verses":[4]}],"verseLabel":"الشعراء: 4","question":"ما المجاز المرسل في قوله: ﴿فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ﴾؟","answer":"أطلقت الأعناق، وهي جزء من الناس، وأريد أصحابها كلهم؛ لأن أثر الخضوع يظهر فيها، فعلاقة المجاز الجزئية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص332–333، تحت عنوان «بلاغة المجاز المرسل في خضوع الأعناق»","url":""}]},{"id":"s26-101","number":101,"surah":26,"verses":[4],"references":[{"surah":26,"verses":[4]}],"verseLabel":"الشعراء: 4","question":"ما الكناية في قوله: ﴿فَظَلَّتْ أَعْنَاقُهُمْ لَهَا خَاضِعِينَ﴾؟","answer":"خضوع الأعناق كناية عن تمام الذل والانقياد، إذ انخفاض العنق من أوضح الهيئات الدالة على الخضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص333، تحت عنوان «دلالة الكناية عن الذل بخضوع الأعناق»","url":""}]},{"id":"s26-5","number":5,"surah":26,"verses":[5],"references":[{"surah":26,"verses":[5]}],"verseLabel":"الشعراء: 5","question":"لماذا قيل في الشعراء: ﴿مِنَ الرَّحْمَنِ﴾ بدل «من ربهم»؟","answer":"اختير اسم الرحمن لإبراز أن الذكر أثر من الرحمة، فيشتد تقبيح إعراضهم عما جاء لإصلاحهم، وفيه تسلية للرسول برحمة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص335–336، تحت عنوان «علة التعبير بلفظ ﴿الرحمن﴾ دون (الرب)»","url":""}]},{"id":"s26-6","number":6,"surah":26,"verses":[6],"references":[{"surah":26,"verses":[6]}],"verseLabel":"الشعراء: 6","question":"ما بلاغة ترتيب الإعراض ثم التكذيب ثم الاستهزاء في مطلع الشعراء؟","answer":"رتبها السياق تصاعديًا؛ بدأ بالإعراض عن الاستماع، ثم التصريح بالتكذيب، ثم الاستهزاء الذي يجمع التكذيب والاحتقار.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص342، تحت عنوان «بلاغة ترتيب: (الإعراض، فالتكذيب، فالاستهزاء)»","url":""}]},{"id":"s26-102","number":102,"surah":26,"verses":[6],"references":[{"surah":26,"verses":[6]}],"verseLabel":"الشعراء: 6","question":"لماذا قيل: ﴿أَنْبَاءُ﴾ دون «أخبار» في وعيد المستهزئين؟","answer":"النبأ هو الخبر العظيم الشأن، فاختياره يهوّل عواقب التكذيب التي سيعاينون تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص339، تحت عنوان «سر إيثار التعبير بالنبأ دون الخبر»","url":""}]},{"id":"s26-103","number":103,"surah":26,"verses":[6],"references":[{"surah":26,"verses":[6]}],"verseLabel":"الشعراء: 6","question":"ما دلالة جمع ﴿أَنْبَاءُ﴾ في قوله: ﴿فَسَيَأْتِيهِمْ أَنْبَاءُ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ﴾؟","answer":"يدل الجمع على تعدد ما استهزؤوا به وتنوع ما سيأتيهم من آثار الوعيد وعواقبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص339–340، تحت عنوان «دلالة جمع لفظ ﴿أنباء﴾»","url":""}]},{"id":"s26-7","number":7,"surah":26,"verses":[7],"references":[{"surah":26,"verses":[7]}],"verseLabel":"الشعراء: 7","question":"ما معنى ﴿كَمْ﴾ ودلالتها في قوله: ﴿كَمْ أَنْبَتْنَا فِيهَا﴾؟","answer":"هي خبرية تفيد التكثير، فتلفت إلى كثرة ما بثه الله في الأرض من أنواع النبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص348، تحت عنوان «معنى ﴿كم﴾ ودلالتها في البيان المحكم»","url":""}]},{"id":"s26-104","number":104,"surah":26,"verses":[7],"references":[{"surah":26,"verses":[7]}],"verseLabel":"الشعراء: 7","question":"ما بلاغة الجمع بين ﴿كَمْ﴾ و﴿كُلِّ﴾ في قوله: ﴿كَمْ أَنْبَتْنَا فِيهَا مِنْ كُلِّ زَوْجٍ﴾؟","answer":"جمعت الآية بين كثرة الأفراد التي تفيدها ﴿كم﴾ وشمول الأصناف الذي تفيده ﴿كل﴾، فاستوعبت الكثرة والتنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص348–349، تحت عنوان «بلاغة الجمع بين الكثرة والشمول»","url":""}]},{"id":"s26-105","number":105,"surah":26,"verses":[7],"references":[{"surah":26,"verses":[7]}],"verseLabel":"الشعراء: 7","question":"لماذا عبّر بـ﴿زَوْجٍ﴾ دون «نبات»؟","answer":"لفظ الزوج أوسع؛ يدل على الصنف والنوع وما في المخلوقات من تقابل وازدواج، فيبرز تنوع النبات وصفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص349، تحت عنوان «علة التعبير بـ(الزوج) دون (النبات)»","url":""}]},{"id":"s26-106","number":106,"surah":26,"verses":[7],"references":[{"surah":26,"verses":[7]}],"verseLabel":"الشعراء: 7","question":"ما دلالة وصف الزوج بأنه ﴿كَرِيمٍ﴾؟","answer":"الكريم يجمع حسن الصفة وكثرة المنفعة؛ فوصف النبات به يبرز نعمة الله مع دلالة الإنبات على القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص349، تحت عنوان «دلالة وصف الزوج بأنه ﴿كريم﴾»","url":""}]},{"id":"s26-8","number":8,"surah":26,"verses":[8,9],"references":[{"surah":26,"verses":[8,9]}],"verseLabel":"الشعراء: 8-9","question":"ما الموقع البياني لجملة: ﴿إِنَّ فِي ذَلِكَ لَآيَةً﴾؟","answer":"جاءت استئنافًا لتقرير أن مشهد إنبات الأرض دليل ظاهر كاف على القدرة والوحدانية والبعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص350، تحت عنوان «الموقع البياني لجملة ﴿إن في ذلك لآية﴾»","url":""}]},{"id":"s26-107","number":107,"surah":26,"verses":[8,9],"references":[{"surah":26,"verses":[8,9]}],"verseLabel":"الشعراء: 8-9","question":"ما دلالة الواو في قوله: ﴿وَمَا كَانَ أَكْثَرُهُمْ مُؤْمِنِينَ﴾؟","answer":"عطفت استمرار أكثرهم على الكفر على وضوح الآية، فأبرزت المفارقة بين كثرة الدليل وشدة الإصرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص352، تحت عنوان «دلالة العطف بالواو في السياق»","url":""}]},{"id":"s26-108","number":108,"surah":26,"verses":[8,9],"references":[{"surah":26,"verses":[8,9]}],"verseLabel":"الشعراء: 8-9","question":"ما بلاغة التذييل بقوله: ﴿وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ﴾؟","answer":"ذيل به تقرير الآية وتكذيب القوم لتسلية النبي وتهديد المكذبين؛ فربه قادر على النصر والعقاب، رحيم في الإمهال والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص353، تحت عنوان «بلاغة التذييل في الآية الكريمة»","url":""}]},{"id":"s26-109","number":109,"surah":26,"verses":[8,9],"references":[{"surah":26,"verses":[8,9]}],"verseLabel":"الشعراء: 8-9","question":"ما دلالة اجتماع اسمي ﴿الْعَزِيزُ الرَّحِيمُ﴾؟","answer":"جمعا كمال القدرة وكمال الرحمة؛ فلا يمنع إمهال المكذبين من القدرة عليهم، ومن رحمته إرسال الرسل والبينات.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص353–354، تحت عنوان «دلالة اجتماع (العزة) و(الرحمة)»","url":""}]},{"id":"s26-9","number":9,"surah":26,"verses":[10],"references":[{"surah":26,"verses":[10]}],"verseLabel":"الشعراء: 10","question":"لماذا قيل: ﴿نَادَى رَبُّكَ مُوسَى﴾ دون «أوحى إليه»؟","answer":"النداء يدل على أن موسى سمع خطاب الله بلا واسطة ملك، وهو تشريف يناسب مقام بدء الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص357، تحت عنوان «دلالة التعبير بلفظ ﴿نادى﴾ دون (أوحى)»","url":""}]},{"id":"s26-110","number":110,"surah":26,"verses":[10],"references":[{"surah":26,"verses":[10]}],"verseLabel":"الشعراء: 10","question":"ما سر التعبير بعنوان الربوبية في قوله: ﴿نَادَى رَبُّكَ مُوسَى﴾؟","answer":"يذكر بإحسان الله إلى رسله ورعايته لهم، وفيه تسلية للنبي بأن ربه الذي نصر موسى يتولى نصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص357، تحت عنوان «سر إيثار التعبير بلفظ الربوبية»","url":""}]},{"id":"s26-10","number":10,"surah":26,"verses":[10],"references":[{"surah":26,"verses":[10]}],"verseLabel":"الشعراء: 10","question":"لماذا وُصف قوم فرعون أولًا بأنهم ﴿الْقَوْمَ الظَّالِمِينَ﴾؟","answer":"قدم الوصف ليبين موجب إرسال موسى إليهم، ويقبح حالهم ويهيئ النفس لإنكار ظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص358، تحت عنوان «علة وصف القوم بـ﴿الظالمين﴾»","url":""}]},{"id":"s26-111","number":111,"surah":26,"verses":[10],"references":[{"surah":26,"verses":[10]}],"verseLabel":"الشعراء: 10","question":"ما دلالة جملة ﴿قَوْمَ فِرْعَوْنَ﴾ بعد ﴿الْقَوْمَ الظَّالِمِينَ﴾؟","answer":"جاءت بدلًا مفسرًا يعيّن المراد، وفي تأخير الاسم إشعار بأن الظلم صار أشهر صفاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص358، تحت عنوان «دلالة جملة: ﴿قوم فرعون﴾»","url":""}]},{"id":"s26-11","number":11,"surah":26,"verses":[12,13],"references":[{"surah":26,"verses":[12,13]}],"verseLabel":"الشعراء: 12-13","question":"ما الاستعارة في قول موسى: ﴿وَيَضِيقُ صَدْرِي﴾؟","answer":"استعير ضيق المكان للغم والكمد؛ فصُورت شدة ما يعتري النفس كأن الصدر يضيق عن احتماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص365، تحت عنوان «بلاغة الاستعارة بالتعبير بالضيق»","url":""}]},{"id":"s26-112","number":112,"surah":26,"verses":[12,13],"references":[{"surah":26,"verses":[12,13]}],"verseLabel":"الشعراء: 12-13","question":"ما الاستعارة في قوله: ﴿وَلَا يَنْطَلِقُ لِسَانِي﴾؟","answer":"صُور عسر البيان بلسان مقيد لا ينطلق، وقوبلت الفصاحة بحرية الحركة والانطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص365–366، تحت عنوان «بلاغة الاستعارة في انطلاق اللسان»","url":""}]},{"id":"s26-113","number":113,"surah":26,"verses":[12,13],"references":[{"surah":26,"verses":[12,13]}],"verseLabel":"الشعراء: 12-13","question":"ما دلالة الفاء في قول موسى: ﴿فَأَرْسِلْ إِلَى هَارُونَ﴾؟","answer":"فرعت طلب مؤازرة هارون على ما ذكره من ضيق الصدر وعسر البيان، فكشفت حرصه على إحسان تبليغ الرسالة لا التهرب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص367، تحت عنوان «دلالة الفاء في جملة: ﴿فأرسل﴾»","url":""}]},{"id":"s26-12","number":12,"surah":26,"verses":[15],"references":[{"surah":26,"verses":[15]}],"verseLabel":"الشعراء: 15","question":"ما سرّ مجيء ﴿مَعَكُمْ﴾ بضمير الجمع في قوله ﴿إِنَّا مَعَكُمْ مُسْتَمِعُونَ﴾؟","answer":"عدل عن التثنية إلى الجمع لأن معية الله محيطة بموسى وهارون وفرعون وقومه: مع أهل الحق بالنصر والحفظ، ومع أهل الباطل بالقهر والكسر؛ وهذا هو التعليل الصريح في المبحث.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص375، تحت عنوان «سر ضمير الجمع ﴿معكم﴾ دون التثنية»","url":""}]},{"id":"s26-13","number":13,"surah":26,"verses":[16],"references":[{"surah":26,"verses":[16]}],"verseLabel":"الشعراء: 16","question":"ما سرّ التعبير في قولهما ﴿إِنَّا رَسُولُ رَبِّ الْعَالَمِينَ﴾ بإفراد ﴿رَسُولُ﴾؟","answer":"لأن لفظ «رسول» يستوي فيه الواحد والاثنان والجمع في هذا الاستعمال، ولأنهما يحملان رسالة واحدة، فكأنهما رسول واحد لاتحاد مقصدهما واتفاقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص377، تحت عنوان «وجه إفراد الرسول دون تثنيته»","url":""}]},{"id":"s26-14","number":14,"surah":26,"verses":[17],"references":[{"surah":26,"verses":[17]}],"verseLabel":"الشعراء: 17","question":"ما سر إيثار الاسم الصريح ﴿بَنِي إِسْرَائِيلَ﴾؟","answer":"عيّن القوم المظلومين وشرفهم باسم أبيهم إسرائيل، بدل عبارة محتملة كـ«قومنا».","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص378–379، تحت عنوان «سر إيثار لفظ ﴿بني إسرائيل﴾»","url":""}]},{"id":"s26-114","number":114,"surah":26,"verses":[17],"references":[{"surah":26,"verses":[17]}],"verseLabel":"الشعراء: 17","question":"ما دلالة الفعل ﴿أَرْسِلْ﴾ في قوله: ﴿أَنْ أَرْسِلْ مَعَنَا بَنِي إِسْرَائِيلَ﴾؟","answer":"المراد تخليتهم وإطلاقهم من الاستعباد ليخرجوا مع موسى وهارون أحرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص378، تحت عنوان «دلالة التعبير بالفعل ﴿أرسل﴾»","url":""}]},{"id":"s26-15","number":15,"surah":26,"verses":[18],"references":[{"surah":26,"verses":[18]}],"verseLabel":"الشعراء: 18","question":"لماذا قال فرعون: ﴿وَلِيدًا﴾ دون «طفلًا»؟","answer":"يستحضر اللفظ تربية موسى منذ ولادته، فيبالغ فرعون في تعداد منته القديمة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص383، تحت عنوان «سر إيثار التعبير بـ﴿وليدا﴾ دون (طفل)»","url":""}]},{"id":"s26-115","number":115,"surah":26,"verses":[18],"references":[{"surah":26,"verses":[18]}],"verseLabel":"الشعراء: 18","question":"ما دلالة الاستفهام في قول فرعون: ﴿أَلَمْ نُرَبِّكَ فِينَا وَلِيدًا﴾؟","answer":"هو للتقرير؛ أراد إلزام موسى بالإقرار بالتربية واتخاذها حجة لصرفه عن دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص382، تحت عنوان «دلالة الاستفهام ﴿ألم نربك﴾»","url":""}]},{"id":"s26-16","number":16,"surah":26,"verses":[19],"references":[{"surah":26,"verses":[19]}],"verseLabel":"الشعراء: 19","question":"ما سرّ كناية فرعون عن القتل بقوله ﴿وَفَعَلْتَ فَعْلَتَكَ الَّتِي فَعَلْتَ﴾؟","answer":"أبهم القتل بقوله ﴿فعلتك التي فعلت﴾ تهويلًا لشأنه، كأن بشاعته تغني عن التصريح باسمه؛ فاجتمع الإبهام مع تفخيم التهمة وتعظيمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص385، تحت عنوان «دلالة وصف الفعلة بالاسم الموصول»","url":""}]},{"id":"s26-17","number":17,"surah":26,"verses":[19],"references":[{"surah":26,"verses":[19]}],"verseLabel":"الشعراء: 19","question":"ما سرّ وصف فرعون موسى بقوله ﴿وَأَنْتَ مِنَ الْكَافِرِينَ﴾؟","answer":"المراد كفران نعمة فرعون في زعمه، لا الكفر العقدي؛ فهو يعيّره بجحود ما عدّه تربيةً وإيواءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص386، تحت عنوان «دلالة التعبير بالكفر»","url":""}]},{"id":"s26-18","number":18,"surah":26,"verses":[20],"references":[{"surah":26,"verses":[20]}],"verseLabel":"الشعراء: 20","question":"ما نوع الواو في قوله: ﴿وَأَنَا مِنَ الضَّالِّينَ﴾، وما دلالتها؟","answer":"هي واو الحال، فقيدت وقوع الفعل بحال الخطأ وعدم قصد القتل، فدفعت توهم التعمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص393، تحت عنوان «نوع الواو ومعناها في الآية»","url":""}]},{"id":"s26-116","number":116,"surah":26,"verses":[20],"references":[{"surah":26,"verses":[20]}],"verseLabel":"الشعراء: 20","question":"ما المراد بلفظ ﴿الضَّالِّينَ﴾ في قول موسى؟","answer":"المراد الخطأ والجهل بعاقبة الفعل، لا الضلال العقدي أو الكفر؛ فقد وقع القتل قبل الرسالة من غير قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص394–395، تحت عنوان «بلاغة التعبير بمفردة الضلال»","url":""}]},{"id":"s26-19","number":19,"surah":26,"verses":[22],"references":[{"surah":26,"verses":[22]}],"verseLabel":"الشعراء: 22","question":"ما بلاغة الاستفهام المقدر في قوله: ﴿وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ﴾؟","answer":"التقدير: أوتلك نعمة تمنها علي؟ وهو للإنكار؛ إذ كانت تربيته في القصر نتيجة استعباد بني إسرائيل وقتل أبنائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص402–403، تحت عنوان «بلاغة الاستفهام في اسم الإشارة بغير أداته»","url":""}]},{"id":"s26-117","number":117,"surah":26,"verses":[22],"references":[{"surah":26,"verses":[22]}],"verseLabel":"الشعراء: 22","question":"ما الاستعارة التهكمية في قوله: ﴿وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ﴾؟","answer":"سميت التربية الناشئة عن ظلم قومه نعمة على طريق التهكم، وقيل هو إقرار بالنعمة مع مقابلتها بجريمة استعباد بني إسرائيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص403–404، تحت عنوان «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s26-20","number":20,"surah":26,"verses":[23],"references":[{"surah":26,"verses":[23]}],"verseLabel":"الشعراء: 23","question":"ما نكتة استفهام فرعون بـ﴿وَمَا رَبُّ الْعَالَمِينَ﴾؟","answer":"استعمل ﴿ما﴾ استعمال المستنكر المتجاهل، كأنه يسأل عن جنس الرب أو ينكر وجوده لا أنه يطلب معرفة صادقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص411–412، تحت عنوان «نكتة الاستفهام بأداة ﴿وما﴾»","url":""}]},{"id":"s26-118","number":118,"surah":26,"verses":[23],"references":[{"surah":26,"verses":[23]}],"verseLabel":"الشعراء: 23","question":"ما بلاغة عدول موسى في جواب ﴿وَمَا رَبُّ الْعَالَمِينَ﴾ عن ظاهر السؤال؟","answer":"عدل عن تعريف الذات بالجنس إلى التعريف بالصفات وآثار الخلق؛ لأن الله لا جنس له يشاركه فيه غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص412–413، تحت عنوان «بلاغة العدول في الجواب عن ظاهر اللفظ إلى معناه»","url":""}]},{"id":"s26-21","number":21,"surah":26,"verses":[24,25,26],"references":[{"surah":26,"verses":[24,25,26]}],"verseLabel":"الشعراء: 24-26","question":"ما بلاغة الاستئناف في انتقال موسى إلى قوله: ﴿رَبُّكُمْ وَرَبُّ آبَائِكُمُ الْأَوَّلِينَ﴾؟","answer":"استأنف بحجة أقرب إلى المخاطبين بعد الدليل الكوني العام، فذكّرهم بأن وجودهم نفسه أثر من ربوبية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص423–424، تحت عنوان «بلاغة الاستئناف البياني في جواب موسى»","url":""}]},{"id":"s26-119","number":119,"surah":26,"verses":[24,25,26],"references":[{"surah":26,"verses":[24,25,26]}],"verseLabel":"الشعراء: 24-26","question":"ما فائدة ذكر الآباء في قوله: ﴿وَرَبُّ آبَائِكُمُ الْأَوَّلِينَ﴾؟","answer":"أبطل دعوى فرعون؛ فالآباء وجدوا قبل عصره وسلطانه، فلا يصح أن يدعي أنه رب الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص424، تحت عنوان «فائدة ذكر الآباء»","url":""}]},{"id":"s26-22","number":22,"surah":26,"verses":[27],"references":[{"surah":26,"verses":[27]}],"verseLabel":"الشعراء: 27","question":"لماذا اختار فرعون وصف موسى بالجنون؟","answer":"أراد تشويه الداعية وصرف الملأ عن حجته بإيهامهم أن كلامه خارج عن المعقول.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص431، تحت عنوان «علة اختيار صفة الجنون»","url":""}]},{"id":"s26-120","number":120,"surah":26,"verses":[27],"references":[{"surah":26,"verses":[27]}],"verseLabel":"الشعراء: 27","question":"ما بلاغة التوكيد في قوله: ﴿إِنَّ رَسُولَكُمُ الَّذِي أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ﴾؟","answer":"جمع إن واللام لترويج التهمة وتثبيتها في نفوس السامعين، وشدة التوكيد تكشف ضعف الدعوى وحاجة قائلها إلى دعمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص428، تحت عنوان «بلاغة التوكيد في الخبر»","url":""}]},{"id":"s26-23","number":23,"surah":26,"verses":[28],"references":[{"surah":26,"verses":[28]}],"verseLabel":"الشعراء: 28","question":"لماذا خُص المشرق والمغرب بالذكر في قوله: ﴿رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ﴾؟","answer":"لأن طلوع الشمس وغروبها آية يومية ظاهرة، تتحدى مدعي الربوبية وتبين عجزه عن تدبير الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص433، تحت عنوان «توجيه تخصيص ﴿المشرق والمغرب﴾ بالذكر»","url":""}]},{"id":"s26-121","number":121,"surah":26,"verses":[28],"references":[{"surah":26,"verses":[28]}],"verseLabel":"الشعراء: 28","question":"ما التعريض في قول موسى: ﴿إِنْ كُنْتُمْ تَعْقِلُونَ﴾؟","answer":"فيه رد تهمة الجنون على من عطلوا عقولهم عن دلالة المشرق والمغرب، فالحري بالذم من أعرض عن البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص435، تحت عنوان «بلاغة التعريض بجنون قوم فرعون»","url":""}]},{"id":"s26-24","number":24,"surah":26,"verses":[29],"references":[{"surah":26,"verses":[29]}],"verseLabel":"الشعراء: 29","question":"ما بلاغة الاستئناف في تهديد فرعون: ﴿لَئِنِ اتَّخَذْتَ إِلَهًا غَيْرِي لَأَجْعَلَنَّكَ مِنَ الْمَسْجُونِينَ﴾؟","answer":"لما أعجزته حجة موسى استأنف تهديدًا يقطع الحوار بالقوة، فكشف انتقاله من المجادلة إلى البطش.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص441، تحت عنوان «بلاغة الاستئناف البياني في التهديد الفرعوني»","url":""}]},{"id":"s26-122","number":122,"surah":26,"verses":[29],"references":[{"surah":26,"verses":[29]}],"verseLabel":"الشعراء: 29","question":"لماذا قال فرعون: ﴿لَأَجْعَلَنَّكَ مِنَ الْمَسْجُونِينَ﴾ بدل «لأسجننك»؟","answer":"الإطناب يضم موسى إلى طائفة معروفة من مسجوني فرعون وما يلاقونه من عذاب، فزاد الوعيد والتخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص443، تحت عنوان «بلاغة الإطناب في السجن»","url":""}]},{"id":"s26-25","number":25,"surah":26,"verses":[30],"references":[{"surah":26,"verses":[30]}],"verseLabel":"الشعراء: 30","question":"ما بلاغة الاستفهام الداخل على واو الحال في قول موسى: ﴿أَوَلَوْ جِئْتُكَ بِشَيْءٍ مُبِينٍ﴾؟","answer":"معناه: أتسجنني ولو أتيتك بدليل ظاهر؟ وهو استدراج لفرعون إلى النظر في الحجة بعد تهديده.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص445، تحت عنوان «بلاغة الاستفهام الداخل على واو الحال»","url":""}]},{"id":"s26-123","number":123,"surah":26,"verses":[30],"references":[{"surah":26,"verses":[30]}],"verseLabel":"الشعراء: 30","question":"ما نكتة وصف الشيء بأنه ﴿مُبِينٍ﴾؟","answer":"دل على أن ما سيأتي به برهان ظاهر يبين صدقه، وفي الوصف إحراج لفرعون إن أعرض عن اختباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص448، تحت عنوان «نكتة وصف الشيء بـ﴿مبين﴾»","url":""}]},{"id":"s26-26","number":26,"surah":26,"verses":[32,33],"references":[{"surah":26,"verses":[32,33]}],"verseLabel":"الشعراء: 32-33","question":"ما نكتة وصف الثعبان بأنه ﴿مُبِينٌ﴾؟","answer":"أكد أنه ثعبان ظاهر حقيقي يشاهده الناس، لا تخييلًا من جنس السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص454، تحت عنوان «نكتة وصف ﴿ثعبان﴾ بـ﴿مبين﴾»","url":""}]},{"id":"s26-124","number":124,"surah":26,"verses":[32,33],"references":[{"surah":26,"verses":[32,33]}],"verseLabel":"الشعراء: 32-33","question":"ما بلاغة قوله في اليد: ﴿بَيْضَاءَ لِلنَّاظِرِينَ﴾؟","answer":"قيد البياض بالناظرين ليصور ظهوره الخارق وجذبه الأبصار، فكانت الآية مشاهدة لا خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص457، تحت عنوان «بلاغة استعمال مفردة النظر»","url":""}]},{"id":"s26-27","number":27,"surah":26,"verses":[34],"references":[{"surah":26,"verses":[34]}],"verseLabel":"الشعراء: 34","question":"ما نكتة الإشارة إلى موسى بـ﴿هَذَا﴾ في قول فرعون: ﴿إِنَّ هَذَا لَسَاحِرٌ عَلِيمٌ﴾؟","answer":"استعمل إشارة القرب بدل الاسم للتحقير والحط من شأن موسى أمام الملأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص464، تحت عنوان «نكتة التعبير بالإشارة»","url":""}]},{"id":"s26-125","number":125,"surah":26,"verses":[34],"references":[{"surah":26,"verses":[34]}],"verseLabel":"الشعراء: 34","question":"ما نكتة وصف الساحر بأنه ﴿عَلِيمٌ﴾ مادة وصيغة؟","answer":"صيغة فعيل توهم رسوخ الحذق في السحر، ليحول فرعون المعجزة إلى مهارة مكتسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص465، تحت عنوان «نكتة الوصف ﴿عليم﴾ مادة وصيغة»","url":""}]},{"id":"s26-28","number":28,"surah":26,"verses":[35],"references":[{"surah":26,"verses":[35]}],"verseLabel":"الشعراء: 35","question":"ما علة فصل جملة ﴿يُرِيدُ أَنْ يُخْرِجَكُمْ مِنْ أَرْضِكُمْ﴾ عما قبلها؟","answer":"استؤنفت كتعليل لتهمة السحر وإغراء للملأ بموسى، إذ صُورت دعوته خطة تهددهم في وطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص466، تحت عنوان «علة فصل جملة ﴿يريد أن يخرجكم﴾ عما قبلها»","url":""}]},{"id":"s26-126","number":126,"surah":26,"verses":[35],"references":[{"surah":26,"verses":[35]}],"verseLabel":"الشعراء: 35","question":"ما دلالة إضافة الأرض إلى ضمير الملأ في قوله: ﴿مِنْ أَرْضِكُمْ﴾؟","answer":"استثارت حرصهم على أرضهم وحرضتهم على موسى، مع تستر فرعون على استئثاره الحقيقي بملكها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص468، تحت عنوان «دلالة الإضافة إلى ضمير الملأ وبلاغتها»","url":""}]},{"id":"s26-29","number":29,"surah":26,"verses":[36],"references":[{"surah":26,"verses":[36]}],"verseLabel":"الشعراء: 36","question":"ما نكتة إيثار لفظ ﴿أَرْجِهْ﴾؟","answer":"الإرجاء هو الإمهال والتأخير، فطلبوا تأخير أمر موسى وأخيه ريثما يعدون من يعارضهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص472، تحت عنوان «نكتة إيثار مفردة الإرجاء»","url":""}]},{"id":"s26-127","number":127,"surah":26,"verses":[36],"references":[{"surah":26,"verses":[36]}],"verseLabel":"الشعراء: 36","question":"ما نكتة استعمال ﴿وَابْعَثْ﴾ في قوله: ﴿وَابْعَثْ فِي الْمَدَائِنِ حَاشِرِينَ﴾؟","answer":"يوحي البعث بسرعة إرسال الجامعين وانتشارهم في المدائن لتنفيذ المهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص473، تحت عنوان «نكتة استعمال مفردة البعث»","url":""}]},{"id":"s26-128","number":128,"surah":26,"verses":[36],"references":[{"surah":26,"verses":[36]}],"verseLabel":"الشعراء: 36","question":"ما بلاغة وصف المبعوثين بأنهم ﴿حَاشِرِينَ﴾؟","answer":"الحشر جمع مع سوق وإلزام، فناسب مهمة استقدام السحرة وحملهم على الحضور إلى الموعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص474، تحت عنوان «بلاغة استعمال لفظ ﴿حاشرين﴾»","url":""}]},{"id":"s26-30","number":30,"surah":26,"verses":[38,39],"references":[{"surah":26,"verses":[38,39]}],"verseLabel":"الشعراء: 38-39","question":"ما دلالة لفظ ﴿لِمِيقَاتِ﴾ في قوله: ﴿فَجُمِعَ السَّحَرَةُ لِمِيقَاتِ يَوْمٍ مَعْلُومٍ﴾؟","answer":"الميقات وقت محدد للحدث، فدل على تعيين موعد المواجهة وإشهارها للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص483–484، تحت عنوان «دلالة التعبير بلفظ ﴿لميقات﴾»","url":""}]},{"id":"s26-129","number":129,"surah":26,"verses":[38,39],"references":[{"surah":26,"verses":[38,39]}],"verseLabel":"الشعراء: 38-39","question":"ما غرض الاستفهام في قوله: ﴿هَلْ أَنْتُمْ مُجْتَمِعُونَ﴾؟","answer":"خرج من طلب الخبر إلى الحث والحض على الاجتماع، ليكثر المشاهدون وأنصار السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص486، تحت عنوان «غرض الاستفهام بـ﴿هل﴾»","url":""}]},{"id":"s26-31","number":31,"surah":26,"verses":[41],"references":[{"surah":26,"verses":[41]}],"verseLabel":"الشعراء: 41","question":"ما غرض استفهام السحرة عن الأجر في قولهم: ﴿أَئِنَّ لَنَا لَأَجْرًا﴾؟","answer":"هو للاستيثاق والتقرير؛ أرادوا إلزام فرعون بوعد المكافأة قبل أن يدخلوا المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص504، تحت عنوان «غرض الاستفهام في ﴿أجرا﴾»","url":""}]},{"id":"s26-130","number":130,"surah":26,"verses":[41],"references":[{"surah":26,"verses":[41]}],"verseLabel":"الشعراء: 41","question":"ما نكتة تنكير ﴿أَجْرًا﴾ في قول السحرة؟","answer":"أفاد التعظيم والتكثير، فكأنهم يطلبون أجرًا كبيرًا يليق بما ظنوه من أهمية عملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص505–506، تحت عنوان «نكتة تنكير ﴿لأجرا﴾»","url":""}]},{"id":"s26-32","number":32,"surah":26,"verses":[43],"references":[{"surah":26,"verses":[43]}],"verseLabel":"الشعراء: 43","question":"ما سرّ التعبير في قول موسى بـ﴿أَلْقُوا مَا أَنْتُمْ مُلْقُونَ﴾؟","answer":"أذن لهم بإظهار ما عندهم ليبطل حجتهم ويكشف عجزهم؛ فليس الأمر إقرارًا للسحر، بل تحدٍّ يعقبه ظهور الحق، وفي العبارة أيضًا وعيد بما سيلقونه من إبطال كيدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص523–524، تحت عنوان «غرض الأمر في قوله: ﴿ألقوا﴾»","url":""}]},{"id":"s26-33","number":33,"surah":26,"verses":[44],"references":[{"surah":26,"verses":[44]}],"verseLabel":"الشعراء: 44","question":"ما دلالة قول السحرة ﴿بعزة فرعون إنا لنحن الغالبون﴾؟","answer":"على وجه القسم، حلفوا بعزة فرعون تعظيمًا لها وثقة بغلبتهم بها. وتحتمل الباء السببية أيضًا: أي نغلب بسبب قوته ومنعته. وكلا الوجهين يكشف ركونهم إلى سلطان فرعون قبل أن تظهر لهم الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص528، تحت عنوان «معنى الباء ودلالتها في قوله: ﴿بعزة﴾»","url":""}]},{"id":"s26-34","number":34,"surah":26,"verses":[45],"references":[{"surah":26,"verses":[45]}],"verseLabel":"الشعراء: 45","question":"ما نكتة إفراد ما ألقاه موسى في مقابلة جمع ما ألقاه السحرة؟","answer":"قوبلت عصا واحدة بحبالهم وعصيهم الكثيرة ليظهر تفوق الآية الواحدة وإبطالها حشد السحر كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص537، تحت عنوان «نكتة إفراد ما ألقاه موسى في مقابلة جمع ما ألقاه السحرة»","url":""}]},{"id":"s26-131","number":131,"surah":26,"verses":[45],"references":[{"surah":26,"verses":[45]}],"verseLabel":"الشعراء: 45","question":"ما دلالة الفعل ﴿تَلْقَفُ﴾؟","answer":"يدل على الأخذ والابتلاع بسرعة، فصور زوال سحرهم عاجلًا أمام العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص549، تحت عنوان «التلقف والأخذ»","url":""}]},{"id":"s26-132","number":132,"surah":26,"verses":[45],"references":[{"surah":26,"verses":[45]}],"verseLabel":"الشعراء: 45","question":"ما دلالة التعبير بـ﴿يَأْفِكُونَ﴾ مادة وصيغة؟","answer":"الإفك صرف الشيء عن وجهه، فوصفت صناعتهم بأنها تمويه يقلب الحقيقة إلى باطل وكذب متجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص538، تحت عنوان «دلالة التعبير بقوله تعالى: ﴿يأفكون﴾ مادة وصيغة»","url":""}]},{"id":"s26-35","number":35,"surah":26,"verses":[46],"references":[{"surah":26,"verses":[46]}],"verseLabel":"الشعراء: 46","question":"ما غرض بناء ﴿فَأُلْقِيَ السَّحَرَةُ﴾ للمجهول؟","answer":"حذف الفاعل ليوجه النظر إلى انقلاب حال السحرة وسرعة خرورهم، كأن قوة البرهان ألقتهم من غير تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص540، تحت عنوان «غرض بناء الفعل ﴿فألقي﴾ لما لم يسم فاعله»","url":""}]},{"id":"s26-133","number":133,"surah":26,"verses":[46],"references":[{"surah":26,"verses":[46]}],"verseLabel":"الشعراء: 46","question":"ما المشاكلة في قوله: ﴿فَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ﴾؟","answer":"أطلق الإلقاء على خرورهم مشاكلة لإلقاء العصا والحبال، فانتظم مشهد الإلقاء ثم غلبة الحق ثم السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص540، تحت عنوان «بلاغة المشاكلة في إطلاق الإلقاء على الخرور»","url":""}]},{"id":"s26-134","number":134,"surah":26,"verses":[46],"references":[{"surah":26,"verses":[46]}],"verseLabel":"الشعراء: 46","question":"ما الاستعارة في قوله: ﴿فَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ﴾؟","answer":"صور انقيادهم الفوري للحق بمن ألقته قوة قاهرة على الأرض، مبالغة في سرعة التأثر بالمعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص541، تحت عنوان «بلاغة الاستعارة في قوله تعالى: ﴿فألقي السحرة﴾»","url":""}]},{"id":"s26-36","number":36,"surah":26,"verses":[47,48],"references":[{"surah":26,"verses":[47,48]}],"verseLabel":"الشعراء: 47-48","question":"ما سرّ قول السحرة ﴿آمَنَّا بِرَبِّ الْعَالَمِينَ * رَبِّ مُوسَى وَهَارُونَ﴾؟","answer":"أزال البدل أي التباس بفرعون الذي ادعى الربوبية، وحددوا الرب الذي جاء موسى وهارون بآياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص543، تحت عنوان «فائدة البدلية في ﴿رب موسى وهارون﴾»","url":""}]},{"id":"s26-37","number":37,"surah":26,"verses":[49],"references":[{"surah":26,"verses":[49]}],"verseLabel":"الشعراء: 49","question":"ما سرّ التعبير في قول فرعون بـ﴿آمَنْتُمْ لَهُ﴾ باللام؟","answer":"عُدّي الإيمان باللام لتضمينه معنى الاستسلام والانقياد؛ أي صدقتم موسى وأذعنتم لما جاء به. وفي تعبير فرعون محاولة لتصوير إيمانهم بالله كأنه خضوع لموسى الذي كان في زعمه تابعًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص556–557، تحت عنوان «نكتة تعدية فعل الإيمان باللام دون الباء»","url":""}]},{"id":"s26-38","number":38,"surah":26,"verses":[49],"references":[{"surah":26,"verses":[49]}],"verseLabel":"الشعراء: 49","question":"ما بلاغة التفصيل في تهديد فرعون: ﴿لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُمْ﴾؟","answer":"فصل صورة العقوبة بعد إجمال الوعيد ليضاعف التخويف، ويصور ما ينتظرهم عضوًا عضوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص565، تحت عنوان «بلاغة الإطناب بالتفصيل بعد الإجمال في ﴿لأقطعن﴾»","url":""}]},{"id":"s26-135","number":135,"surah":26,"verses":[49],"references":[{"surah":26,"verses":[49]}],"verseLabel":"الشعراء: 49","question":"ما سر جمع الأيدي والأرجل وإضافتها إلى ضمير المخاطبين؟","answer":"عمّ التهديد جميع السحرة وجعل أعضاءهم حاضرة في الخطاب، فاشتد وقع الوعيد وشموله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص566، تحت عنوان «سر جمع الأيدي والأرجل وإضافتها لضمير المخاطبين»","url":""}]},{"id":"s26-136","number":136,"surah":26,"verses":[49],"references":[{"surah":26,"verses":[49]}],"verseLabel":"الشعراء: 49","question":"ما نكتة تنكير ﴿خِلَافٍ﴾ في قوله: ﴿مِنْ خِلَافٍ﴾؟","answer":"يفيد نوعًا فظيعًا من المخالفة في القطع، يد من جهة ورجل من الجهة الأخرى، بما يفضي إلى أشد العجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص567، تحت عنوان «نكتة تنكير ﴿خلاف﴾»","url":""}]},{"id":"s26-137","number":137,"surah":26,"verses":[49],"references":[{"surah":26,"verses":[49]}],"verseLabel":"الشعراء: 49","question":"ما دلالة الواو في قوله: ﴿وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ﴾؟","answer":"عطفت الصلب على التقطيع للدلالة على جمع العقوبتين، لا التخيير بينهما، فزاد التهديد تنكيلًا وتشهيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص567–568، تحت عنوان «معنى الواو ودلالتها في ﴿ولأصلبنكم﴾»","url":""}]},{"id":"s26-39","number":39,"surah":26,"verses":[50],"references":[{"surah":26,"verses":[50]}],"verseLabel":"الشعراء: 50","question":"ما معنى ﴿لَا﴾ ودلالتها في جواب السحرة: ﴿لَا ضَيْرَ﴾؟","answer":"هي لنفي الضرر المؤثر؛ أي لا ضرر يصدنا عن الإيمان، لأن أذى الدنيا يهون أمام ثواب الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص580–581، تحت عنوان «معنى ﴿لا﴾ ودلالتها في الآية»","url":""}]},{"id":"s26-138","number":138,"surah":26,"verses":[50],"references":[{"surah":26,"verses":[50]}],"verseLabel":"الشعراء: 50","question":"ما علة فصل قوله: ﴿إِنَّا إِلَى رَبِّنَا مُنْقَلِبُونَ﴾ عما قبله؟","answer":"استؤنف تعليلًا لقولهم ﴿لا ضير﴾؛ فرجوعهم إلى ربهم وثقتهم بجزائه هو سبب استهانتهم بالتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص582–583، تحت عنوان «علة فصل قوله: ﴿إنا إلى ربنا منقلبون﴾ عن سابقه»","url":""}]},{"id":"s26-40","number":40,"surah":26,"verses":[52],"references":[{"surah":26,"verses":[52]}],"verseLabel":"الشعراء: 52","question":"ما دلالة عطف ﴿وأوحينا إلى موسى أن أسر بعبادي﴾ بالواو على قصة السحرة؟","answer":"الواو تعطف قصة الإسراء على ما سبقها، ولا تدل على وقوعها بعد إيمان السحرة مباشرة؛ فقد لبث موسى يدعو فرعون إلى إطلاق بني إسرائيل، ثم جاء الأمر بالخروج حين أذن الله بالنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص601، تحت عنوان «معنى الواو ودلالتها في قوله: ﴿وأوحينا﴾»","url":""}]},{"id":"s26-41","number":41,"surah":26,"verses":[53],"references":[{"surah":26,"verses":[53]}],"verseLabel":"الشعراء: 53","question":"ما الإيجاز في حذف متعلق ﴿حَاشِرِينَ﴾ في حشد جنود فرعون؟","answer":"حذف المتعلق اعتمادًا على السياق؛ أي حاشرين الجنود، كما دل السياق السابق في موضع آخر على حشر السحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص608، تحت عنوان «بلاغة الإيجاز بحذف متعلق المشتق ﴿حاشرين﴾»","url":""}]},{"id":"s26-42","number":42,"surah":26,"verses":[54],"references":[{"surah":26,"verses":[54]}],"verseLabel":"الشعراء: 54","question":"لماذا وصف فرعون الشرذمة بأنها ﴿قَلِيلُونَ﴾ مع أن الشرذمة قليلة؟","answer":"زاد الوصف للمبالغة في تقليل بني إسرائيل وتحقير شأنهم، وتهوين أمر قتالهم على قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص610–611، تحت عنوان «نكتة وصف الشرذمة بالقلة»","url":""}]},{"id":"s26-139","number":139,"surah":26,"verses":[54],"references":[{"surah":26,"verses":[54]}],"verseLabel":"الشعراء: 54","question":"ما وجه إيثار صيغة جمع السلامة ﴿قَلِيلُونَ﴾؟","answer":"صوّرهم جماعات معدودة، ومع ذلك حكم على مجموعهم بالقلة، فزاد في التهوين والتحقير.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص611، تحت عنوان «وجه إيثار التعبير بصيغة جمع السلامة ﴿قليلون﴾»","url":""}]},{"id":"s26-43","number":43,"surah":26,"verses":[57,58],"references":[{"surah":26,"verses":[57,58]}],"verseLabel":"الشعراء: 57-58","question":"ما علة وصل ﴿وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ﴾ بما قبله؟","answer":"عطف بقية مظاهر النعيم على الجنات والعيون لاستكمال صورة ما أخرج منه قوم فرعون من خيرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص625، تحت عنوان «علة وصل قوله تعالى: ﴿وكنوز ومقام كريم﴾ بسابقه»","url":""}]},{"id":"s26-140","number":140,"surah":26,"verses":[57,58],"references":[{"surah":26,"verses":[57,58]}],"verseLabel":"الشعراء: 57-58","question":"ما سر ترتيب ما أُخرج منه قوم فرعون من الجنات إلى المقام الكريم؟","answer":"بدأ بالجنات ثم العيون التي تقوم بها، ثم الأموال المدخرة، وختم بالمساكن والمجالس الرفيعة؛ فصعد في تعداد أسباب نعيمهم واستقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص626، تحت عنوان «سر تخصيص المخرج منه وترتيبه بدءا بالجنات، وانتهاء بالمقام الكريم»","url":""}]},{"id":"s26-44","number":44,"surah":26,"verses":[61],"references":[{"surah":26,"verses":[61]}],"verseLabel":"الشعراء: 61","question":"ما غرض التوكيد في قول أصحاب موسى: ﴿إِنَّا لَمُدْرَكُونَ﴾؟","answer":"أكدوا بإن واللام شدة يقينهم بأن جيش فرعون سيدركهم، لما رأوا البحر أمامهم والعدو خلفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص641، تحت عنوان «غرض التوكيد»","url":""}]},{"id":"s26-141","number":141,"surah":26,"verses":[61],"references":[{"surah":26,"verses":[61]}],"verseLabel":"الشعراء: 61","question":"ما نكتة التعبير بالجملة الاسمية في قوله: ﴿إِنَّا لَمُدْرَكُونَ﴾؟","answer":"صورت الإدراك عندهم أمرًا ثابتًا متحققًا لا مهرب منه، لا مجرد حدث محتمل الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص641، تحت عنوان «نكتة التعبير بالاسمية»","url":""}]},{"id":"s26-45","number":45,"surah":26,"verses":[62],"references":[{"surah":26,"verses":[62]}],"verseLabel":"الشعراء: 62","question":"ما معنى ﴿كَلَّا﴾ ودلالتها في جواب موسى؟","answer":"ردعت ظنهم أن فرعون سيدركهم، فنفت الخوف بحسم وثقة قبل بيان سبب النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص645، تحت عنوان «معنى ﴿كلا﴾ ودلالتها»","url":""}]},{"id":"s26-142","number":142,"surah":26,"verses":[62],"references":[{"surah":26,"verses":[62]}],"verseLabel":"الشعراء: 62","question":"ما نكتة إسناد المعية إلى الرب في قوله: ﴿إِنَّ مَعِيَ رَبِّي﴾؟","answer":"استحضر معية الرب الخاصة بالحفظ والنصر والهداية، وفي عنوان الربوبية معنى الرعاية والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص647، تحت عنوان «نكتة إسناد المعية إلى الرب»","url":""}]},{"id":"s26-143","number":143,"surah":26,"verses":[62],"references":[{"surah":26,"verses":[62]}],"verseLabel":"الشعراء: 62","question":"ما دلالة السين في قوله: ﴿سَيَهْدِينِ﴾؟","answer":"تفيد قرب تحقق الهداية إلى طريق النجاة، وتعبر عن يقين موسى بوعد ربه قبل أن يرى وسيلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص647، تحت عنوان «دلالة استعمال حرف السين»","url":""}]},{"id":"s26-46","number":46,"surah":26,"verses":[63],"references":[{"surah":26,"verses":[63]}],"verseLabel":"الشعراء: 63","question":"ما سر إظهار اسم موسى في ﴿فأوحينا إلى موسى﴾ مع إمكان الاكتفاء بالضمير؟","answer":"أظهر اسم موسى بدل الضمير تشريفًا له وتنويهًا بمقامه، ولا سيما أن المقام مقام وحي وهداية، جزاء ثقته بالله وحسن ظنه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص651، تحت عنوان «بلاغة إظهار ما حقه الإضمار»","url":""}]},{"id":"s26-47","number":47,"surah":26,"verses":[63],"references":[{"surah":26,"verses":[63]}],"verseLabel":"الشعراء: 63","question":"ما بلاغة تشبيه فرق الماء بـ﴿الطَّوْدِ﴾؟","answer":"شُبهت كتلة الماء بعد انشقاق البحر بالجبل الشامخ الثابت، فقرّب إلى الحس هيئة ماء سائل وقف مرتفعًا راسخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص655–656، تحت عنوان «بلاغة تشبيه فرق الماء بالطود العظيم»","url":""}]},{"id":"s26-144","number":144,"surah":26,"verses":[63],"references":[{"surah":26,"verses":[63]}],"verseLabel":"الشعراء: 63","question":"ما سر وصف الطود بأنه ﴿الْعَظِيمِ﴾؟","answer":"زاد الوصف تصوير ضخامة كل فرق من الماء وهول المشهد، فأبرز عظمة القدرة التي أمسكت البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص657، تحت عنوان «سر تقييد المشبه به ﴿كالطود﴾ بالوصف ﴿العظيم﴾»","url":""}]},{"id":"s26-48","number":48,"surah":26,"verses":[65],"references":[{"surah":26,"verses":[65]}],"verseLabel":"الشعراء: 65","question":"ما بلاغة الاحتراس في قوله: ﴿وَمَنْ مَعَهُ﴾؟","answer":"قطع ذكر من معه توهم اختصاص النجاة بموسى، فأثبتها لكل المؤمنين المصاحبين له.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص662، تحت عنوان «بلاغة الاحتراس في قوله: ﴿ومن معه﴾»","url":""}]},{"id":"s26-145","number":145,"surah":26,"verses":[65],"references":[{"surah":26,"verses":[65]}],"verseLabel":"الشعراء: 65","question":"ما فائدة التوكيد بـ﴿أَجْمَعِينَ﴾؟","answer":"أكد شمول النجاة لكل فرد من الجماعة، ونفى احتمال تخلف أحد أو ضياعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص663، تحت عنوان «فائدة التقييد بالتوكيد المعنوي ﴿أجمعين﴾»","url":""}]},{"id":"s26-49","number":49,"surah":26,"verses":[69],"references":[{"surah":26,"verses":[69]}],"verseLabel":"الشعراء: 69","question":"ما بلاغة عطف قصة إبراهيم على قصة موسى؟","answer":"جمع القصتين في سياق الاعتبار بمقاومة الكفر، وانتقل من طغيان فرعون إلى بطلان عبادة الأصنام التي عرفها المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص674، تحت عنوان «بلاغة عطف القصة على القصة»","url":""}]},{"id":"s26-146","number":146,"surah":26,"verses":[69],"references":[{"surah":26,"verses":[69]}],"verseLabel":"الشعراء: 69","question":"ما بلاغة تغيير أسلوب بدء قصة إبراهيم إلى الأمر: ﴿وَاتْلُ عَلَيْهِمْ﴾؟","answer":"زاد الأمر بالتلاوة عناية بالقصة وتنبيهًا للمشركين؛ لأنهم ينتسبون إلى إبراهيم مع مخالفته لهم في نبذ الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص675، تحت عنوان «بلاغة تغيير أسلوب بدء القصة»","url":""}]},{"id":"s26-50","number":50,"surah":26,"verses":[71],"references":[{"surah":26,"verses":[71]}],"verseLabel":"الشعراء: 71","question":"ما الإطناب في قول قوم إبراهيم: ﴿فَنَظَلُّ لَهَا عَاكِفِينَ﴾؟","answer":"زادوا الجملة على مجرد جواب سؤال ما يعبدون، افتخارًا بملازمة عبادتها وإظهارًا لرسوخهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص679، تحت عنوان «بلاغة الإطناب»","url":""}]},{"id":"s26-147","number":147,"surah":26,"verses":[71],"references":[{"surah":26,"verses":[71]}],"verseLabel":"الشعراء: 71","question":"ما دلالة الفعل ﴿فَنَظَلُّ﴾؟","answer":"يفيد دوام العبادة واستمرارها، ويحتمل تخصيص الملازمة بالنهار بحسب أصل استعمال ظل.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص679–680، تحت عنوان «دلالة التعبير بالفعل ﴿فنظل﴾»","url":""}]},{"id":"s26-148","number":148,"surah":26,"verses":[71],"references":[{"surah":26,"verses":[71]}],"verseLabel":"الشعراء: 71","question":"ما دلالة اسم الفاعل ﴿عَاكِفِينَ﴾؟","answer":"صور ملازمتهم الأصنام وثباتهم عندها وتعظيمهم لها كصفة راسخة متجددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص680، تحت عنوان «دلالة التعبير باسم الفاعل»","url":""}]},{"id":"s26-51","number":51,"surah":26,"verses":[72,73],"references":[{"surah":26,"verses":[72,73]}],"verseLabel":"الشعراء: 72-73","question":"ما غرض استفهام إبراهيم عن سماع الأصنام ونفعها وضرها؟","answer":"هو إنكاري استدراجي؛ ألزمهم اختبار معبوداتهم حتى يقروا بعجزها، فتقوم الحجة من جوابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص684، تحت عنوان «غرض الاستفهام ودلالته»","url":""}]},{"id":"s26-149","number":149,"surah":26,"verses":[72,73],"references":[{"surah":26,"verses":[72,73]}],"verseLabel":"الشعراء: 72-73","question":"ما نكتة تقديم النفع على الضر في سؤال إبراهيم؟","answer":"بدأ بالنفع لأنه المقصود الأول من العبادة والرجاء، ثم أتبعه بالضر لاستيعاب ما يطلب من المعبود أو يخاف منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص685، تحت عنوان «نكتة تقديم ذكر النفع على الضر»","url":""}]},{"id":"s26-52","number":52,"surah":26,"verses":[74],"references":[{"surah":26,"verses":[74]}],"verseLabel":"الشعراء: 74","question":"لماذا لم يجيبوا عن الحجة وقالوا ﴿بَلْ وَجَدْنَا آبَاءَنَا كَذَلِكَ يَفْعَلُونَ﴾؟","answer":"عدلوا بـ«بل» عن الإجابة لأنهم لا يستطيعون إثبات السماع أو النفع والضر للأصنام؛ فتركوا موضع الحجة وتعلقوا بتقليد آبائهم، وهو إقرار ضمني بعجزهم عن الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص688، تحت عنوان «غرض الإضراب عن الجواب»","url":""}]},{"id":"s26-53","number":53,"surah":26,"verses":[77],"references":[{"surah":26,"verses":[77]}],"verseLabel":"الشعراء: 77","question":"ما سرّ إفراد ﴿عَدُوٌّ﴾ في قول إبراهيم عن الأصنام ﴿فَإِنَّهُمْ عَدُوٌّ لِي﴾؟","answer":"أُفرد «عدو» مع عود الضمير إلى الأصنام لأن عداوتها واحدة في حقيقتها: الشرك بالله وما يفضي إليه من الهلاك؛ فتعدد المعبودات لا يغير هذه الجهة الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص698–699، تحت عنوان «سر إفراد لفظ ﴿عدو﴾»","url":""}]},{"id":"s26-54","number":54,"surah":26,"verses":[78,79,80,81,82],"references":[{"surah":26,"verses":[78,79,80,81,82]}],"verseLabel":"الشعراء: 78-82","question":"ما بلاغة استعمال الضمير ﴿هُوَ﴾ في صفات الله التي عددها إبراهيم؟","answer":"أكد الضمير اختصاص الله بالهداية والإطعام والسقي والشفاء، ورد توهم استقلال الأسباب الظاهرة بهذه النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص705–706، تحت عنوان «بلاغة استعمال الضمير (هو) في الآيات»","url":""}]},{"id":"s26-150","number":150,"surah":26,"verses":[78,79,80,81,82],"references":[{"surah":26,"verses":[78,79,80,81,82]}],"verseLabel":"الشعراء: 78-82","question":"ما دلالة تكرار ضمير الفصل في قوله: ﴿فَهُوَ يَهْدِينِ﴾ و﴿هُوَ يُطْعِمُنِي﴾ و﴿فَهُوَ يَشْفِينِ﴾؟","answer":"جدد القصر مع كل نعمة قد تنسب إلى سبب ظاهر، فثبت أن الله وحده موجد أثرها الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص711، تحت عنوان «دلالة تكرار ضمير الفصل»","url":""}]},{"id":"s26-151","number":151,"surah":26,"verses":[78,79,80,81,82],"references":[{"surah":26,"verses":[78,79,80,81,82]}],"verseLabel":"الشعراء: 78-82","question":"ما دلالة حذف ضمير الفصل مع الخلق والإماتة؟","answer":"لم يحتج الخلق والإماتة إلى التوكيد نفسه لإقرار القوم بأنهما لله وعدم ظهور سبب يوهم الاستقلال بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص711، تحت عنوان «دلالة حذف ضمير الفصل»","url":""}]},{"id":"s26-55","number":55,"surah":26,"verses":[80],"references":[{"surah":26,"verses":[80]}],"verseLabel":"الشعراء: 80","question":"ما سرّ التعبير بـ﴿وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ﴾ فنسب إبراهيم المرض إلى نفسه؟","answer":"هذا من أدب النبوة في العبارة؛ صرّح بنسبة الخلق والهداية والإطعام والشفاء إلى الله، وأسند المرض إلى نفسه مع أن الجميع بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص709–710، تحت عنوان «نكتة اختلاف إسناد المرض إلى المتكلم والشفاء إلى الرب»","url":""}]},{"id":"s26-56","number":56,"surah":26,"verses":[83],"references":[{"surah":26,"verses":[83]}],"verseLabel":"الشعراء: 83","question":"ما بلاغة اختيار ﴿هَبْ﴾ في دعاء إبراهيم: ﴿رَبِّ هَبْ لِي حُكْمًا﴾؟","answer":"أظهر أن العلم والحكمة عطية محضة من الله وفضل، لا أمر يستقل العبد بتحصيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص719–720، تحت عنوان «بلاغة استعمال مفردة الهبة»","url":""}]},{"id":"s26-152","number":152,"surah":26,"verses":[83],"references":[{"surah":26,"verses":[83]}],"verseLabel":"الشعراء: 83","question":"ما نكتة سؤال إبراهيم ﴿حُكْمًا﴾؟","answer":"الحكم يجمع صواب المعرفة وصواب العمل والقضاء بها، فلا تكتمل الحكمة بمعرفة الحق دون امتثاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص720، تحت عنوان «نكتة ذكر الحكم»","url":""}]},{"id":"s26-57","number":57,"surah":26,"verses":[84],"references":[{"surah":26,"verses":[84]}],"verseLabel":"الشعراء: 84","question":"ما المجاز في قوله: ﴿لِسَانَ صِدْقٍ﴾، وما غرضه؟","answer":"أطلق اللسان، وهو آلة الثناء، وأريد به الذكر الحسن الصادق؛ ليبقى لإبراهيم ثناء يقتدي به اللاحقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص727–728، تحت عنوان «نوع المجاز وغرضه في قوله: ﴿لسان صدق﴾»","url":""}]},{"id":"s26-153","number":153,"surah":26,"verses":[84],"references":[{"surah":26,"verses":[84]}],"verseLabel":"الشعراء: 84","question":"ما نوع الإضافة في ﴿لِسَانَ صِدْقٍ﴾ وما دلالتها؟","answer":"إضافة الموصوف إلى صفته، أي لسانًا صادقًا أو ثناء صدق، وفيها توكيد مطابقة الذكر للحق ونفي المبالغة الكاذبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص728، تحت عنوان «نوع الإضافة وعلة التعبير في الآية»","url":""}]},{"id":"s26-58","number":58,"surah":26,"verses":[85],"references":[{"surah":26,"verses":[85]}],"verseLabel":"الشعراء: 85","question":"ما الاستعارة في قوله: ﴿مِنْ وَرَثَةِ جَنَّةِ النَّعِيمِ﴾؟","answer":"شُبه نيل الجنة بالإرث لرسوخ الملك وكونه عطية من الله لا معاوضة محضة، فصرح بلفظ الورثة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص735–736، تحت عنوان «بلاغة الاستعارة التصريحية في: ﴿ورثة﴾»","url":""}]},{"id":"s26-154","number":154,"surah":26,"verses":[85],"references":[{"surah":26,"verses":[85]}],"verseLabel":"الشعراء: 85","question":"ما نوع الإضافة وبراعتها في قوله: ﴿جَنَّةِ النَّعِيمِ﴾؟","answer":"أضيف المكان إلى ما يملؤه من النعيم، فصارت الجنة كأنها عين النعيم ومحله الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص737، تحت عنوان «نوع الإضافة وبراعتها في: ﴿جنة النعيم﴾»","url":""}]},{"id":"s26-155","number":155,"surah":26,"verses":[85],"references":[{"surah":26,"verses":[85]}],"verseLabel":"الشعراء: 85","question":"ما دلالة تعريف ﴿النَّعِيمِ﴾؟","answer":"يفيد كمال النعيم المعهود في الآخرة واستغراق أنواعه، فهو دائم لا يكدره نقص أو زوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص738، تحت عنوان «دلالة التعريف في قوله: ﴿النعيم﴾»","url":""}]},{"id":"s26-59","number":59,"surah":26,"verses":[86],"references":[{"surah":26,"verses":[86]}],"verseLabel":"الشعراء: 86","question":"ما غرض الأمر في دعاء إبراهيم: ﴿وَاغْفِرْ لِأَبِي﴾؟","answer":"خرج الأمر إلى الدعاء والرجاء، ومن لازم مغفرة الكافر أن يهديه الله إلى الإيمان أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص742، تحت عنوان «غرض الأمر في قوله: ﴿واغفر﴾»","url":""}]},{"id":"s26-156","number":156,"surah":26,"verses":[86],"references":[{"surah":26,"verses":[86]}],"verseLabel":"الشعراء: 86","question":"لماذا خص إبراهيم أباه بالدعاء؟","answer":"وفى بوعده لأبيه ورجا هدايته قبل أن يتبين له أنه عدو لله؛ فلما تبين له ذلك تبرأ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص743، تحت عنوان «علة تخصيص الدعاء لأبيه»","url":""}]},{"id":"s26-60","number":60,"surah":26,"verses":[88,89],"references":[{"surah":26,"verses":[88,89]}],"verseLabel":"الشعراء: 88-89","question":"ما سر الاقتصار على المال والبنين في قوله: ﴿يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ﴾؟","answer":"خُصا لأنهما أبرز ما يستعين به الإنسان في الدنيا ويفاخر به، ومع ذلك لا يدفعان عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص758، تحت عنوان «سر الاقتصار على ذكر المال والبنين»","url":""}]},{"id":"s26-157","number":157,"surah":26,"verses":[88,89],"references":[{"surah":26,"verses":[88,89]}],"verseLabel":"الشعراء: 88-89","question":"ما نوع الاستثناء في قوله: ﴿إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ﴾؟","answer":"يجوز الانقطاع: لكن الناجي صاحب القلب السليم، ويجوز الاتصال بتقدير أن المال والولد ينفعان المؤمن بما قدم فيهما من خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص759–760، تحت عنوان «نوع الاستثناء في الآية»","url":""}]},{"id":"s26-61","number":61,"surah":26,"verses":[90,91],"references":[{"surah":26,"verses":[90,91]}],"verseLabel":"الشعراء: 90-91","question":"ما علة التعبير بـ﴿وَأُزْلِفَتِ الْجَنَّةُ﴾؟","answer":"الإزلاف التقريب، فصور تقريب الجنة للمتقين إكرامًا لهم وتشويقًا إلى دخولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص771، تحت عنوان «علة التعبير بقوله: ﴿وأزلفت﴾»","url":""}]},{"id":"s26-158","number":158,"surah":26,"verses":[90,91],"references":[{"surah":26,"verses":[90,91]}],"verseLabel":"الشعراء: 90-91","question":"ما نكتة اختلاف فعلي ﴿أُزْلِفَتْ﴾ و﴿بُرِّزَتْ﴾؟","answer":"ناسب التقريب مقام الوعد والبشارة لأهل الجنة، وناسب الإظهار والطرح للعيان مقام تهويل الجحيم للغاوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص779، تحت عنوان «نكتة اختلاف فعلي ﴿وأزلفت﴾ ﴿وبرزت﴾»","url":""}]},{"id":"s26-62","number":62,"surah":26,"verses":[94,95],"references":[{"surah":26,"verses":[94,95]}],"verseLabel":"الشعراء: 94-95","question":"ما سر التعبير بـ﴿فَكُبْكِبُوا﴾؟","answer":"صيغة الكبكبة تصور تكرار قلبهم وطرحهم على الوجوه مرة بعد مرة، فتضاعف مشهد الإهانة والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص796–797، تحت عنوان «سر التعبير بلفظ الكبكبة»","url":""}]},{"id":"s26-159","number":159,"surah":26,"verses":[94,95],"references":[{"surah":26,"verses":[94,95]}],"verseLabel":"الشعراء: 94-95","question":"ما فائدة كب الأصنام في الجحيم وهي لا تعقل؟","answer":"يزيد ذلك عابديها حسرة وتوبيخًا حين يرون عجز ما عبدوه ومشاركته لهم في المصير الذي لم يدفعه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص798، تحت عنوان «فائدة كب الأصنام، وهي لا تعقل»","url":""}]},{"id":"s26-160","number":160,"surah":26,"verses":[94,95],"references":[{"surah":26,"verses":[94,95]}],"verseLabel":"الشعراء: 94-95","question":"ما معنى الواو في قوله: ﴿وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ﴾؟","answer":"عطفت جنود إبليس على الغاوين والمعبودات، فجمعت في الجحيم قادة الضلال وأتباعهم وأسباب غوايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص800، تحت عنوان «معنى الواو في قوله: ﴿وجنود﴾»","url":""}]},{"id":"s26-63","number":63,"surah":26,"verses":[97],"references":[{"surah":26,"verses":[97]}],"verseLabel":"الشعراء: 97","question":"ما سرّ القسم بالتاء في قول أهل النار ﴿تَاللَّهِ إِنْ كُنَّا لَفِي ضَلَالٍ مُبِينٍ﴾؟","answer":"تاء القسم تستعمل في مقام التعجب، فناسبت دهشتهم المتأخرة من تسويتهم الأصنام برب العالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص14، تحت عنوان «نكتة مجيء القسم بصيغة ﴿تالله﴾»","url":""}]},{"id":"s26-64","number":64,"surah":26,"verses":[105],"references":[{"surah":26,"verses":[105]}],"verseLabel":"الشعراء: 105","question":"ما علة التعبير بـ﴿قَوْمُ﴾ وتأنيث الفعل في قوله: ﴿كَذَّبَتْ قَوْمُ نُوحٍ﴾؟","answer":"أُنث الفعل على معنى الجماعة أو القبيلة الكامن في لفظ قوم، فروعيت دلالته لا صورته المذكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص64–65، تحت عنوان «علة التعبير بـ﴿قوم﴾ وسر التأنيث»","url":""}]},{"id":"s26-161","number":161,"surah":26,"verses":[105],"references":[{"surah":26,"verses":[105]}],"verseLabel":"الشعراء: 105","question":"لماذا جُمع ﴿الْمُرْسَلِينَ﴾ مع أن قوم نوح كذبوا رسولًا واحدًا؟","answer":"لأن تكذيب رسول واحد تكذيب لأصل الرسالة الذي اتفق عليه جميع الرسل، فكأنهم كذبوا المرسلين كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص66–67، تحت عنوان «سر وضع الجمع ﴿المرسلين﴾ موضع المفرد»","url":""}]},{"id":"s26-65","number":65,"surah":26,"verses":[106],"references":[{"surah":26,"verses":[106]}],"verseLabel":"الشعراء: 106","question":"ما سرّ وصف نوح بأنه ﴿أَخُوهُمْ﴾؟","answer":"الأخوة هنا أخوة النسب؛ فهو واحد منهم يعرفون حاله وصدقه، وفي ذكرها تقريب وتلطف يدعوان إلى قبول نصحه، ويقطعان اعتذارهم بالجهل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص69، تحت عنوان «علة ذكر الأخوة في قوله: ﴿أخوهم﴾»","url":""}]},{"id":"s26-66","number":66,"surah":26,"verses":[109],"references":[{"surah":26,"verses":[109]}],"verseLabel":"الشعراء: 109","question":"لماذا صدرت قصص الرسل بقولهم: ﴿وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ﴾؟","answer":"لإعلان إخلاص الدعوة لله ورفع تهمة طلب المال أو الجاه، فدعوتهم نفع لأقوامهم لا مصلحة دنيوية للرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص150، تحت عنوان «تصدير القصص بـ: ﴿وما أسألكم عليه من أجر﴾»","url":""}]},{"id":"s26-162","number":162,"surah":26,"verses":[109],"references":[{"surah":26,"verses":[109]}],"verseLabel":"الشعراء: 109","question":"ما بلاغة القصر في قوله: ﴿إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ﴾؟","answer":"قصر رجاء الجزاء على الله وحده، فأكد استقلال الرسول عن الناس وإخلاصه في تبليغهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص82، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s26-67","number":67,"surah":26,"verses":[111],"references":[{"surah":26,"verses":[111]}],"verseLabel":"الشعراء: 111","question":"ما غرض الاستفهام في قول قوم نوح: ﴿أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْأَرْذَلُونَ﴾؟","answer":"خرج الاستفهام للإنكار الناشئ عن الاستكبار؛ فقد استبعدوا أن يجتمعوا مع الفقراء والضعفاء في اتباع نوح، وجعلوا حال أتباعه الاجتماعية حجة لرد الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص91، تحت عنوان «غرض الاستفهام في قوله: ﴿أنؤمن﴾»","url":""}]},{"id":"s26-163","number":163,"surah":26,"verses":[111],"references":[{"surah":26,"verses":[111]}],"verseLabel":"الشعراء: 111","question":"لماذا عبّر قوم نوح عن أتباعه بلفظ ﴿الْأَرْذَلُونَ﴾؟","answer":"حكى اللفظ احتقارهم للفقراء والضعفاء وتسميتهم إياهم بما ينفر منهم، فهو وصف صادر عن ميزان المتكبرين لا تقرير لحقيقة قدر المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص96–97، تحت عنوان «علة التعبير بالرذل في قوله: ﴿الأرذلون﴾»","url":""}]},{"id":"s26-68","number":68,"surah":26,"verses":[112],"references":[{"surah":26,"verses":[112]}],"verseLabel":"الشعراء: 112","question":"ما المراد بالعلم في قول نوح: ﴿وَمَا عِلْمِي بِمَا كَانُوا يَعْمَلُونَ﴾؟","answer":"المراد علم الحكم على الناس؛ ومهمة الرسول أن يقبل ظاهر إيمانهم، لا أن يفتش سرائرهم أو يكشف نياتهم الخفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص104، تحت عنوان «المراد بالعلم في قوله: ﴿علمي﴾ ودلالته»","url":""}]},{"id":"s26-164","number":164,"surah":26,"verses":[112],"references":[{"surah":26,"verses":[112]}],"verseLabel":"الشعراء: 112","question":"كيف جاء قول نوح ﴿وَمَا عِلْمِي بِمَا كَانُوا يَعْمَلُونَ﴾ جوابًا عن اعتراض قومه؟","answer":"ردّ اعتراضهم بأن مهن أتباعه وأحوالهم الماضية لا تضر صدق إيمانهم، وأن حساب بواطنهم على الله؛ فليس من شأنه رد المؤمنين إرضاء للمتكبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص106–107، تحت عنوان «التوجيه البلاغي في الآية»","url":""}]},{"id":"s26-69","number":69,"surah":26,"verses":[114],"references":[{"surah":26,"verses":[114]}],"verseLabel":"الشعراء: 114","question":"ما دلالة الباء في قول نوح: ﴿وَمَا أَنَا بِطَارِدِ الْمُؤْمِنِينَ﴾؟","answer":"زادت الباء توكيد نفي الطرد، فأثبتت تمسك نوح بالمؤمنين ورفضه الاستجابة لمقترح المستكبرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص112، تحت عنوان «دلالة الباء في ﴿بطارد﴾»","url":""}]},{"id":"s26-165","number":165,"surah":26,"verses":[114],"references":[{"surah":26,"verses":[114]}],"verseLabel":"الشعراء: 114","question":"لماذا عبّر نوح باسم الفاعل ﴿بِطَارِدِ﴾ دون الفعل؟","answer":"صوّر اسم الفاعل الطرد وصفًا منفيًا عنه في الحال والاستقبال، فنفى أن يكون طرد المؤمنين شأنًا ثابتًا له لا مجرد واقعة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص112، تحت عنوان «دلالة التعبير باسم الفاعل في ﴿بطارد﴾ دون الفعل»","url":""}]},{"id":"s26-70","number":70,"surah":26,"verses":[119],"references":[{"surah":26,"verses":[119]}],"verseLabel":"الشعراء: 119","question":"لماذا قال نوح لربه: ﴿إِنَّ قَوْمِي كَذَّبُونِ﴾ مع علم الله بحالهم؟","answer":"خرج الخبر عن مجرد الإخبار إلى الشكوى المؤكدة والتوجه إلى الله بطلب النصرة بعد إصرار القوم وتهديدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص124–125، تحت عنوان «خروج الخبر ﴿إن قومي كذبون﴾ عن الغرض الأصلي»","url":""}]},{"id":"s26-166","number":166,"surah":26,"verses":[119],"references":[{"surah":26,"verses":[119]}],"verseLabel":"الشعراء: 119","question":"ما دلالة اختيار لفظ الفتح في دعاء نوح: ﴿فَافْتَحْ بَيْنِي وَبَيْنَهُمْ﴾؟","answer":"الفتح هنا الحكم والفصل الحاسم بين الفريقين، وصيغة الأمر دعاء يطلب به نوح نصر الحق وإنزال الحكم العادل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص126، تحت عنوان «اختيار لفظ (الفتح) مادة وصيغة»","url":""}]},{"id":"s26-167","number":167,"surah":26,"verses":[119],"references":[{"surah":26,"verses":[119]}],"verseLabel":"الشعراء: 119","question":"ما فائدة إعادة مادة الفتح في قوله: ﴿فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا﴾؟","answer":"جاء ﴿فتحًا﴾ مفعولًا مطلقًا من مادة الفعل، فأكد طلب الفصل وجعله حكمًا حاسمًا لا تردد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص126، تحت عنوان «جناس اشتقاق حاصل من إعادة لفظ ﴿فتحا﴾ وإعرابه»","url":""}]},{"id":"s26-168","number":168,"surah":26,"verses":[119],"references":[{"surah":26,"verses":[119]}],"verseLabel":"الشعراء: 119","question":"ما دلالة فعل الأمر في دعاء نوح: ﴿وَنَجِّنِي وَمَنْ مَعِيَ مِنَ الْمُؤْمِنِينَ﴾؟","answer":"خرج الأمر إلى الدعاء، فطلب نوح من ربه النجاة له وللمؤمنين معه عند نزول الحكم بقومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص127، تحت عنوان «دلالة فعل الأمر في ﴿ونجني﴾»","url":""}]},{"id":"s26-71","number":71,"surah":26,"verses":[128,129],"references":[{"surah":26,"verses":[128,129]}],"verseLabel":"الشعراء: 128-129","question":"ما سر تقييد بناء قوم هود بقوله: ﴿تَعْبَثُونَ﴾؟","answer":"بيّن قيد الحال أن موضع الإنكار هو البناء للعبث والتفاخر بلا منفعة، لا أصل البناء النافع في نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص159، تحت عنوان «سر التقييد بجملة الحال في: ﴿تعبثون﴾»","url":""}]},{"id":"s26-169","number":169,"surah":26,"verses":[128,129],"references":[{"surah":26,"verses":[128,129]}],"verseLabel":"الشعراء: 128-129","question":"ما سر اختيار لفظ ﴿مَصَانِعَ﴾ في وصف أبنية قوم هود؟","answer":"يتسع اللفظ للقصور والحصون ومنشآت جمع الماء، فيصور براعتهم في التشييد وتسخير الوسائل التي توهمهم دوام القوة والحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص160، تحت عنوان «سر اختيار لفظ ﴿مصانع﴾»","url":""}]},{"id":"s26-170","number":170,"surah":26,"verses":[128,129],"references":[{"surah":26,"verses":[128,129]}],"verseLabel":"الشعراء: 128-129","question":"ما معنى ﴿لَعَلَّكُمْ﴾ في قوله: ﴿لَعَلَّكُمْ تَخْلُدُونَ﴾ وما دلالتها؟","answer":"صوّرت حالهم كحال من يرجو الخلود ويتعلق به؛ ففضحت اغترارهم بطول البقاء مع أن الخلود في الدنيا ممتنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص161، تحت عنوان «معنى (لعل) ودلالتها في ﴿لعلكم تخلدون﴾»","url":""}]},{"id":"s26-72","number":72,"surah":26,"verses":[130],"references":[{"surah":26,"verses":[130]}],"verseLabel":"الشعراء: 130","question":"لماذا قيل ﴿وَإِذَا بَطَشْتُمْ﴾ بـ﴿إذا﴾ دون ﴿إن﴾؟","answer":"دلّت ﴿إذا﴾ على أن البطش متحقق الوقوع ومتكرر منهم، حتى صار عادة معلومة لا أمرًا محتملًا نادرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص163، تحت عنوان «معنى (إذا) هنا دون (إن)»","url":""}]},{"id":"s26-171","number":171,"surah":26,"verses":[130],"references":[{"surah":26,"verses":[130]}],"verseLabel":"الشعراء: 130","question":"ما دلالة تكرار فعل البطش في قوله: ﴿وَإِذَا بَطَشْتُمْ بَطَشْتُمْ﴾؟","answer":"حُمل البطش الأول على إرادته، والثاني على إيقاعه؛ أي إن أردتم العقوبة نفذتموها على الصورة التي اعتادوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص164، تحت عنوان «تكرار البطش مع اختلاف معناه»","url":""}]},{"id":"s26-172","number":172,"surah":26,"verses":[130],"references":[{"surah":26,"verses":[130]}],"verseLabel":"الشعراء: 130","question":"ما دلالة وصفهم بـ﴿جَبَّارِينَ﴾ عند البطش؟","answer":"صوّر تجاوزهم حد العدل وإفراطهم في العقوبة؛ فهم يبطشون تسلطًا وقهرًا لا تأديبًا بحق ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص164، تحت عنوان «سر التعبير بلفظ ﴿جبارين﴾ مادة وصيغة»","url":""}]},{"id":"s26-73","number":73,"surah":26,"verses":[146,147,148],"references":[{"surah":26,"verses":[146,147,148]}],"verseLabel":"الشعراء: 146-148","question":"ما غرض الاستفهام في قول صالح: ﴿أَتُتْرَكُونَ فِي مَا هَاهُنَا آمِنِينَ﴾؟","answer":"أنكر عليهم توهم دوام الأمن والنعيم مع الكفر، ونبههم إلى أن تركهم فيه ليس خلودًا ولا إعفاء من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص229–230، تحت عنوان «معنى الهمزة وغرض الاستفهام في قوله: ﴿أتتركون﴾»","url":""}]},{"id":"s26-173","number":173,"surah":26,"verses":[146,147,148],"references":[{"surah":26,"verses":[146,147,148]}],"verseLabel":"الشعراء: 146-148","question":"ما موقع قوله ﴿فِي جَنَّاتٍ﴾ بعد ﴿فِي مَا هَاهُنَا﴾؟","answer":"جاء تفصيلًا بعد إجمال، ففسر النعيم المحيط بهم بذكر الجنات والعيون والزروع والنخل، فكان أوقع في تذكيرهم بالنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص233، تحت عنوان «موقع الجار والمجرور في قوله: ﴿في جنات﴾»","url":""}]},{"id":"s26-74","number":74,"surah":26,"verses":[149],"references":[{"surah":26,"verses":[149]}],"verseLabel":"الشعراء: 149","question":"ما دلالة مجيء ﴿فَارِهِينَ﴾ حالًا في قوله: ﴿وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا فَارِهِينَ﴾؟","answer":"قيّدت الحال فعل النحت، فصوّرت هيئة القوم وهم يباشرونه حاذقين أقوياء معجبين بصنعتهم ومتحصنين ببيوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص242، تحت عنوان «دلالة الحال في قوله تعالى: ﴿فارهين﴾»","url":""}]},{"id":"s26-174","number":174,"surah":26,"verses":[149],"references":[{"surah":26,"verses":[149]}],"verseLabel":"الشعراء: 149","question":"ما دلالة لفظ ﴿فَارِهِينَ﴾ في وصف نحت ثمود؟","answer":"يدل اللفظ على النشاط والقوة والحذق، ويأتي كذلك للبطر والأشر؛ فجمع وصف قدرتهم بما يلازم اغترارهم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص243، تحت عنوان «دلالة التعبير بلفظ ﴿فارهين﴾»","url":""}]},{"id":"s26-175","number":175,"surah":26,"verses":[149],"references":[{"surah":26,"verses":[149]}],"verseLabel":"الشعراء: 149","question":"كيف وُجّهت القراءتان ﴿فَارِهِينَ﴾ و﴿فَرِهِينَ﴾؟","answer":"القراءتان متقاربتان؛ فتدوران بين الحذق والنشاط وبين الأشر والبطر، وكلتاهما تلائم مقام تعداد النعمة والتحذير من الاغترار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص244، تحت عنوان «توجيه القراءات في ﴿فارهين﴾»","url":""}]},{"id":"s26-75","number":75,"surah":26,"verses":[152],"references":[{"surah":26,"verses":[152]}],"verseLabel":"الشعراء: 152","question":"ما دلالة النفي بـ﴿لا﴾ في قوله: ﴿وَلَا يُصْلِحُونَ﴾؟","answer":"نفى المضارع وقوع الإصلاح منهم في الحال والاستقبال، فدل على دوام فسادهم وإصرارهم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص259، تحت عنوان «دلالة النفي بـ (لا) في قوله: ﴿ولا يصلحون﴾»","url":""}]},{"id":"s26-76","number":76,"surah":26,"verses":[154],"references":[{"surah":26,"verses":[154]}],"verseLabel":"الشعراء: 154","question":"ما علة الفصل في قولهم لصالح: ﴿مَا أَنْتَ إِلَّا بَشَرٌ مِثْلُنَا﴾؟","answer":"فُصلت الجملة عما قبلها لأنها تؤكد اتهامهم السابق وتعلله؛ فكأن نفي رسالته عندهم نتيجة مترتبة على زعمهم أنه من المسحرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص267، تحت عنوان «علة الفصل في قوله: ﴿ما أنت إلا بشر﴾»","url":""}]},{"id":"s26-77","number":77,"surah":26,"verses":[160],"references":[{"surah":26,"verses":[160]}],"verseLabel":"الشعراء: 160","question":"ما سر جمع ﴿المرسلين﴾ في قوله ﴿كذبت قوم لوط المرسلين﴾ مع أن المرسل إليهم لوط؟","answer":"لأن تكذيب لوط يتضمن تكذيب سائر الرسل؛ فقد جاءوا بأصل واحد، وتكذيب الرسول تكذيب لمن أرسله، فلا يصح الإيمان ببعض الرسالة ورد بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص311، تحت عنوان «دلالة جمع ﴿المرسلين﴾»","url":""}]},{"id":"s26-78","number":78,"surah":26,"verses":[165],"references":[{"surah":26,"verses":[165]}],"verseLabel":"الشعراء: 165","question":"ما غرض الاستفهام في قوله: ﴿أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَمِينَ﴾؟","answer":"خرج الاستفهام للتوبيخ والإنكار والتعجيب من فاحشتهم، فواجههم بقبح فعلهم وخروجه عن الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص328، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s26-176","number":176,"surah":26,"verses":[165],"references":[{"surah":26,"verses":[165]}],"verseLabel":"الشعراء: 165","question":"ما بلاغة الكناية في فعل ﴿تَأْتُونَ﴾؟","answer":"كنّى بالإتيان عن الفاحشة تهذيبًا للعبارة مع إبقاء شدة الإنكار، فدل على الفعل القبيح من غير تصريح مبتذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص329، تحت عنوان «بلاغة الكناية في قوله: ﴿أتأتون﴾»","url":""}]},{"id":"s26-177","number":177,"surah":26,"verses":[165],"references":[{"surah":26,"verses":[165]}],"verseLabel":"الشعراء: 165","question":"ما دلالة جمع ﴿الذُّكْرَانَ﴾؟","answer":"ناسب الجمع شيوع الفاحشة بينهم وتناولهم جنس الذكور، فزاد التعبير تقبيحًا لفعل صار ظاهرة جماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص329، تحت عنوان «معنى التعبير بالجمع في قوله: ﴿أتأتون الذكران﴾»","url":""}]},{"id":"s26-178","number":178,"surah":26,"verses":[165],"references":[{"surah":26,"verses":[165]}],"verseLabel":"الشعراء: 165","question":"ما دلالة ﴿مِنَ﴾ في قوله: ﴿الذُّكْرَانَ مِنَ الْعَالَمِينَ﴾؟","answer":"تفيد فصل الذكران من جملة العالمين؛ أي تخصون بهذا الفعل الذكور من سائر الخلق، أو تنفردون به عن العالمين، وفي الوجهين مزيد تقبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص330، تحت عنوان «معنى ﴿من﴾ ودلالتها»","url":""}]},{"id":"s26-79","number":79,"surah":26,"verses":[168],"references":[{"surah":26,"verses":[168]}],"verseLabel":"الشعراء: 168","question":"ما سرّ اختيار ﴿الْقَالِينَ﴾ في قول لوط ﴿إِنِّي لِعَمَلِكُمْ مِنَ الْقَالِينَ﴾؟","answer":"القِلى شدة البغض، ولم يقل «قالٍ» بل ﴿من القالين﴾، ليدل على أنه راسخ في بغض هذا العمل ومنضم إلى كل من ينكره، لا منفرد بموقف عارض منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص348، تحت عنوان «سر العدول عن الإفراد إلى الجمع في ﴿القالين﴾، وتعريفه»","url":""}]},{"id":"s26-80","number":80,"surah":26,"verses":[169],"references":[{"surah":26,"verses":[169]}],"verseLabel":"الشعراء: 169","question":"ما دلالة اختيار ﴿نَجِّنِي﴾ في دعاء لوط؟","answer":"طلب الخلاص التام من شر قومه وعاقبة فعلهم، فجاء لفظ النجاة أبلغ من مجرد الحفظ لأنه يفيد الإبعاد عن المكروه والخروج سالمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص349، تحت عنوان «دلالة التعبير بلفظ ﴿نجني﴾»","url":""}]},{"id":"s26-179","number":179,"surah":26,"verses":[169],"references":[{"surah":26,"verses":[169]}],"verseLabel":"الشعراء: 169","question":"ما دلالة ﴿مِنْ﴾ في قول لوط: ﴿مِمَّا يَعْمَلُونَ﴾؟","answer":"بيّنت ما يطلب النجاة منه، فشمل الدعاء شر أعمالهم وما يترتب عليها من أذى وعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص350، تحت عنوان «معنى (من) ودلالتها»","url":""}]},{"id":"s26-180","number":180,"surah":26,"verses":[169],"references":[{"surah":26,"verses":[169]}],"verseLabel":"الشعراء: 169","question":"ما بلاغة التعبير بـ﴿يَعْمَلُونَ﴾ في دعاء لوط؟","answer":"كنّى عن الفاحشة دون تسميتها، وجاء بالمضارع ليصور اعتيادهم لها وإصرارهم المتجدد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص350، تحت عنوان «بلاغة التعبير بلفظ ﴿يعملون﴾»","url":""}]},{"id":"s26-81","number":81,"surah":26,"verses":[171],"references":[{"surah":26,"verses":[171]}],"verseLabel":"الشعراء: 171","question":"ما دلالة ﴿فِي﴾ في قوله عن امرأة لوط: ﴿فِي الْغَابِرِينَ﴾؟","answer":"صوّرت الظرفية اندراجها واستقرارها في جماعة الهالكين، بما يلائم موافقتها لهم وبقاءها معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص358، تحت عنوان «معنى حرف الظرفية ودلالته»","url":""}]},{"id":"s26-82","number":82,"surah":26,"verses":[176],"references":[{"surah":26,"verses":[176]}],"verseLabel":"الشعراء: 176","question":"ما سرّ نسبة شعيب إلى أصحاب الأيكة دون وصفه بـ﴿أَخُوهُمْ﴾؟","answer":"تورد الموسوعة وجهين: أن القوم نُسبوا هنا إلى الأيكة التي عظموها وعبدوها، فحُذفت أخوة شعيب لهذه النسبة؛ وقيل إن شعيبًا كان أخًا لمدين نسبًا، ولم يكن من أصحاب الأيكة. فالحذف يراعي الجهة التي عُرّف بها القوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص379، تحت عنوان «توجيه المتشابه اللفظي في حذف لفظ (أخوهم)»","url":""}]},{"id":"s26-83","number":83,"surah":26,"verses":[181,182,183],"references":[{"surah":26,"verses":[181,182,183]}],"verseLabel":"الشعراء: 181-183","question":"ما بلاغة عطف النهي ﴿وَلَا تَكُونُوا مِنَ الْمُخْسِرِينَ﴾ على الأمر بإيفاء الكيل؟","answer":"جمع الأسلوب بين الأمر بالوفاء والنهي عن ضده، فارتقى من طلب الحق إلى التحذير من الخسران وأكد وجوب العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص392، تحت عنوان «بلاغة العطف في النهي»","url":""}]},{"id":"s26-181","number":181,"surah":26,"verses":[181,182,183],"references":[{"surah":26,"verses":[181,182,183]}],"verseLabel":"الشعراء: 181-183","question":"ما دلالة وصف القسطاس بأنه ﴿الْمُسْتَقِيمِ﴾؟","answer":"صوّر الميزان ثابتًا على العدل لا يميل إلى زيادة أو نقص، فزاد الوصف توكيدًا للاستقامة والإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص395، تحت عنوان «دلالة الوصف بـ﴿المستقيم﴾»","url":""}]},{"id":"s26-182","number":182,"surah":26,"verses":[181,182,183],"references":[{"surah":26,"verses":[181,182,183]}],"verseLabel":"الشعراء: 181-183","question":"ما بلاغة اختيار لفظ ﴿تَبْخَسُوا﴾؟","answer":"البخس نقص الحق ظلمًا، وهو أعم من التطفيف؛ فيشمل الغش والتعييب والتنقص من حقوق الناس في صورها المختلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص396، تحت عنوان «بلاغة استعمال مفردة البخس»","url":""}]},{"id":"s26-84","number":84,"surah":26,"verses":[187],"references":[{"surah":26,"verses":[187]}],"verseLabel":"الشعراء: 187","question":"ما بلاغة قولهم لشعيب: ﴿فَأَسْقِطْ عَلَيْنَا﴾؟","answer":"خرج الأمر إلى التعجيز والاستهزاء واستعجال العذاب، فكشف إصرارهم على التكذيب لا رغبتهم في الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص422، تحت عنوان «بلاغة الكناية في فعل الأمر ﴿فأسقط﴾»","url":""}]},{"id":"s26-183","number":183,"surah":26,"verses":[187],"references":[{"surah":26,"verses":[187]}],"verseLabel":"الشعراء: 187","question":"ما دلالة لفظ ﴿كِسَفًا﴾ في قولهم: ﴿كِسَفًا مِنَ السَّمَاءِ﴾؟","answer":"دل اللفظ على قطع أو كتل من السماء، فصوّروا العذاب المطلوب شيئًا يهوى عليهم، مبالغة في التحدي والسخرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص422، تحت عنوان «دلالة استعمال مفردة ﴿كسفا﴾»","url":""}]},{"id":"s26-85","number":85,"surah":26,"verses":[197],"references":[{"surah":26,"verses":[197]}],"verseLabel":"الشعراء: 197","question":"ما غرض الاستفهام في قوله: ﴿أَوَلَمْ يَكُنْ لَهُمْ آيَةً﴾؟","answer":"جاء للتقرير والإنكار؛ فمعرفة علماء بني إسرائيل بالقرآن دليل قائم كان ينبغي أن يحمل قريشًا على التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص465، تحت عنوان «غرض الاستفهام وبلاغته في: ﴿أولم﴾»","url":""}]},{"id":"s26-184","number":184,"surah":26,"verses":[197],"references":[{"surah":26,"verses":[197]}],"verseLabel":"الشعراء: 197","question":"ما فائدة إضافة ﴿عُلَمَاءُ﴾ إلى ﴿بَنِي إِسْرَائِيلَ﴾؟","answer":"عينت الإضافة أهل العلم بالكتب السابقة الذين تعرف قريش مكانتهم وتثق بخبرهم، فجعلت شهادتهم على صدق القرآن أبلغ في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص468، تحت عنوان «فائدة إضافة ﴿علماء﴾ إلى ﴿بني إسرائيل﴾»","url":""}]},{"id":"s26-86","number":86,"surah":26,"verses":[198,199],"references":[{"surah":26,"verses":[198,199]}],"verseLabel":"الشعراء: 198-199","question":"ما بلاغة مجيء الشرط بـ﴿لَوْ﴾ في قوله: ﴿وَلَوْ نَزَّلْنَاهُ عَلَى بَعْضِ الْأَعْجَمِينَ﴾؟","answer":"صوّرت ﴿لو﴾ فرضًا ممتنعًا يكشف شدة عنادهم: فحتى لو وقع هذا الدليل الخارق لبقوا على امتناعهم من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص470–471، تحت عنوان «بلاغة مجيء الشرط بأداة (لو)»","url":""}]},{"id":"s26-185","number":185,"surah":26,"verses":[198,199],"references":[{"surah":26,"verses":[198,199]}],"verseLabel":"الشعراء: 198-199","question":"ما دلالة التعبير بفعل القراءة في قوله: ﴿فَقَرَأَهُ عَلَيْهِمْ﴾؟","answer":"أبرز أن أعجميًا يتلو القرآن العربي المبين كما أُنزل، وهي آية ظاهرة في البيان والبرهان؛ ومع ذلك لا تستجيب لها مكابرتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص472، تحت عنوان «دلالة استعمال فعل القراءة»","url":""}]},{"id":"s26-87","number":87,"surah":26,"verses":[200],"references":[{"surah":26,"verses":[200]}],"verseLabel":"الشعراء: 200","question":"ما أوجه معنى الضمير في قوله ﴿كَذَلِكَ سَلَكْنَاهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾؟","answer":"يحتمل الضمير القرآن: أُدخل إلى قلوبهم وفهموه، لكنهم جحدوه فلم ينتفعوا به. ويحتمل التكذيب: تمكّن في قلوبهم حتى صار كالأمر الثابت فيها؛ وهما وجهان تذكرهما الموسوعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص476–477، تحت عنوان «تعيين مرجع ضمير مفعول ﴿سلكناه﴾»","url":""}]},{"id":"s26-88","number":88,"surah":26,"verses":[205,206,207],"references":[{"surah":26,"verses":[205,206,207]}],"verseLabel":"الشعراء: 205-207","question":"ما بلاغة الاستفهام في قوله: ﴿أَفَرَأَيْتَ إِنْ مَتَّعْنَاهُمْ سِنِينَ﴾؟","answer":"جاء للتقرير والتنبيه إلى أن طول المتاع لا يغير النهاية، ودعا المخاطب إلى تصور ما سيؤول إليه حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص490، تحت عنوان «بلاغة الاستفهام بالهمزة ﴿أفرأيت﴾»","url":""}]},{"id":"s26-186","number":186,"surah":26,"verses":[205,206,207],"references":[{"surah":26,"verses":[205,206,207]}],"verseLabel":"الشعراء: 205-207","question":"ما فائدة تقييد المتاع بلفظ ﴿سِنِينَ﴾؟","answer":"نكّر الجمع ليفرض أطول مدة يتوهمونها؛ فمهما امتد المتاع سنين كثيرة انتهى ولم يدفع العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص492، تحت عنوان «فائدة تقييد الفعل بالظرف ﴿سنين﴾»","url":""}]},{"id":"s26-187","number":187,"surah":26,"verses":[205,206,207],"references":[{"surah":26,"verses":[205,206,207]}],"verseLabel":"الشعراء: 205-207","question":"ما دلالة الموصول ﴿مَا﴾ في قوله: ﴿ثُمَّ جَاءَهُمْ مَا كَانُوا يُوعَدُونَ﴾؟","answer":"جاء الموصول عامًا مبهمًا تهويلًا للعذاب الموعود وتفخيمًا لشأنه، مع ربط مجيئه بما تكرر إنذارهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص493، تحت عنوان «نوع ﴿ما﴾ ودلالتها»","url":""}]},{"id":"s26-89","number":89,"surah":26,"verses":[208,209],"references":[{"surah":26,"verses":[208,209]}],"verseLabel":"الشعراء: 208-209","question":"ما بلاغة القصر في قوله: ﴿وَمَا أَهْلَكْنَا مِنْ قَرْيَةٍ إِلَّا لَهَا مُنْذِرُونَ﴾؟","answer":"قصر الهلاك على القرى التي سبقه إنذار، فأثبت أن إقامة الحجة سنة لازمة قبل العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص502، تحت عنوان «بلاغة أسلوب القصر»","url":""}]},{"id":"s26-188","number":188,"surah":26,"verses":[208,209],"references":[{"surah":26,"verses":[208,209]}],"verseLabel":"الشعراء: 208-209","question":"ما نكتة التعبير عن عدل الله بقوله: ﴿وَمَا كُنَّا ظَالِمِينَ﴾؟","answer":"نفى الظلم نفيًا ثابتًا شاملًا، فبين أن العقوبة لا تقع إلا بعد الإنذار واستحقاقها، وبرأ الحكم الإلهي من كل جور.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص508، تحت عنوان «نكتة التعبير عن العدل بنفي الظلم»","url":""}]},{"id":"s26-90","number":90,"surah":26,"verses":[210,211,212],"references":[{"surah":26,"verses":[210,211,212]}],"verseLabel":"الشعراء: 210-212","question":"ما بلاغة ترتيب الأفعال المنفية في قوله عن الشياطين: ﴿وَمَا تَنَزَّلَتْ بِهِ... وَمَا يَنْبَغِي لَهُمْ وَمَا يَسْتَطِيعُونَ﴾؟","answer":"رتب النفي من عدم الوقوع، إلى عدم الملاءمة لشأنهم، ثم إلى انتفاء القدرة؛ فأبطل دعوى تنزيلهم القرآن من وجوه متصاعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص518، تحت عنوان «بلاغة ترتيب الأفعال المنفية»","url":""}]},{"id":"s26-189","number":189,"surah":26,"verses":[210,211,212],"references":[{"surah":26,"verses":[210,211,212]}],"verseLabel":"الشعراء: 210-212","question":"ما بلاغة الاستئناف بقوله: ﴿إِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَ﴾؟","answer":"جاء جوابًا عن سؤال مقدر: لِمَ لا يستطيعون؟ فبيّن أنهم محجوبون عن السمع، وعلل استحالة تلقيهم القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص519، تحت عنوان «بلاغة الاستئناف البياني بـ﴿إنهم﴾»","url":""}]},{"id":"s26-91","number":91,"surah":26,"verses":[214],"references":[{"surah":26,"verses":[214]}],"verseLabel":"الشعراء: 214","question":"ما غرض اختيار لفظ ﴿عَشِيرَتَكَ﴾ في بدء الإنذار؟","answer":"العشيرة أهل الرجل الذين يكثر بهم ويستنصر، فكانوا أولى الناس أن يبدأ بدعوتهم وأن يعرفوا صدقه ويؤازروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص527، تحت عنوان «غرض اختيار لفظ العشيرة»","url":""}]},{"id":"s26-190","number":190,"surah":26,"verses":[214],"references":[{"surah":26,"verses":[214]}],"verseLabel":"الشعراء: 214","question":"ما غرض وصف العشيرة بـ﴿الْأَقْرَبِينَ﴾؟","answer":"خصص أقرب الأقارب زيادة في العناية والنصح، وبين أن شدة القرب لا تعفي من الإنذار ولا تمنح امتيازًا في التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص528، تحت عنوان «غرض الوصف بلفظ ﴿الأقربين﴾»","url":""}]},{"id":"s26-191","number":191,"surah":26,"verses":[214],"references":[{"surah":26,"verses":[214]}],"verseLabel":"الشعراء: 214","question":"ما بلاغة التعريض في قوله: ﴿وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾؟","answer":"عرّض بالأقارب الذين لم يبادروا إلى اتباعه بأنهم أحوج إلى الإنذار، وكشف أن القرابة وحدها لا تنجي من تبعة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص528، تحت عنوان «بلاغة التعريض في الآية»","url":""}]},{"id":"s26-92","number":92,"surah":26,"verses":[215],"references":[{"surah":26,"verses":[215]}],"verseLabel":"الشعراء: 215","question":"ما سرّ التعبير بـ﴿وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ﴾؟","answer":"جسّد التواضع واللين في صورة طائر يخفض جناحه لفرخه ويحوطه به؛ فالمطلوب أن يعامل المؤمنين بالرحمة والرعاية، وأن يضمهم إليه بلطف وأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص529، تحت عنوان «براعة المجاز في تجسيد الأخلاق»","url":""}]},{"id":"s26-93","number":93,"surah":26,"verses":[218,219],"references":[{"surah":26,"verses":[218,219]}],"verseLabel":"الشعراء: 218-219","question":"ما دلالة الواو في قوله: ﴿وَتَقَلُّبَكَ فِي السَّاجِدِينَ﴾؟","answer":"جمعت الواو بين رؤية الله له حين يقوم منفردًا ورؤيته له مع المصلين، فأحاطت بحالي عبادته في الانفراد والاجتماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص542، تحت عنوان «نوع واو ﴿وتقلبك﴾ ودلالتها»","url":""}]},{"id":"s26-192","number":192,"surah":26,"verses":[218,219],"references":[{"surah":26,"verses":[218,219]}],"verseLabel":"الشعراء: 218-219","question":"ما بلاغة الاستعارة في فعل ﴿تَقَلُّبَكَ﴾؟","answer":"استعار التقلب لانتقاله المتكرر بين هيئات الصلاة من قيام وركوع وسجود، فصوّر تنوع الحركة ودوام العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص542–543، تحت عنوان «بلاغة الاستعارة في فعل التقلب»","url":""}]},{"id":"s26-193","number":193,"surah":26,"verses":[218,219],"references":[{"surah":26,"verses":[218,219]}],"verseLabel":"الشعراء: 218-219","question":"ما بلاغة التعبير عن المصلين بـ﴿السَّاجِدِينَ﴾؟","answer":"أطلق السجود وأريد به الصلاة وأهلها، فذكر أشرف أحوالها وأقربها من الله للدلالة على المصلين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص543، تحت عنوان «بلاغة المجاز المرسل في الوصف بالسجود»","url":""}]},{"id":"s26-94","number":94,"surah":26,"verses":[221,222,223],"references":[{"surah":26,"verses":[221,222,223]}],"verseLabel":"الشعراء: 221-223","question":"ما بلاغة الانتقال من نفي تنزل الشياطين بالقرآن إلى قوله: ﴿هَلْ أُنَبِّئُكُمْ عَلَى مَنْ تَنَزَّلُ الشَّيَاطِينُ﴾؟","answer":"انتقل من إبطال التهمة إلى بيان من تناسبهم الشياطين حقيقة، فكشف بالمقابلة بُعد الرسول عن صفاتهم وألزم المفترين بالجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص550، تحت عنوان «بلاغة الانتقال من النفي إلى الإخبار»","url":""}]},{"id":"s26-194","number":194,"surah":26,"verses":[221,222,223],"references":[{"surah":26,"verses":[221,222,223]}],"verseLabel":"الشعراء: 221-223","question":"ما بلاغة التعبير بالمصدر ﴿السَّمْعَ﴾ في قوله: ﴿يُلْقُونَ السَّمْعَ﴾؟","answer":"صوّر المصدر إلقاء حاسة السمع كلها إلى المتلقي، فبالغ في شدة الإصغاء والتلقي والتأثر بما يسمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص554، تحت عنوان «بلاغة التعبير بالمصدر ﴿السمع﴾»","url":""}]},{"id":"s26-195","number":195,"surah":26,"verses":[221,222,223],"references":[{"surah":26,"verses":[221,222,223]}],"verseLabel":"الشعراء: 221-223","question":"ما دلالة الواو في قوله: ﴿وَأَكْثَرُهُمْ كَاذِبُونَ﴾؟","answer":"تحتمل الحال أو العطف، وفي الحالتين تكشف أن الكذب هو الغالب على أخبارهم، مع إبقاء احتمال موافقة القليل للواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص555، تحت عنوان «نوع واو ﴿وأكثرهم﴾ ودلالتها»","url":""}]},{"id":"s26-95","number":95,"surah":26,"verses":[224,225,226],"references":[{"surah":26,"verses":[224,225,226]}],"verseLabel":"الشعراء: 224-226","question":"ما بلاغة الاستعارة في قوله عن الشعراء: ﴿فِي كُلِّ وَادٍ يَهِيمُونَ﴾؟","answer":"استعار الأودية لفنون القول وأغراضه، وصوّر تنقلهم فيها بلا هدى كهائم يتيه في كل طريق، فدل على اضطراب المقاصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص564، تحت عنوان «بلاغة الاستعارة في ﴿واد﴾»","url":""}]},{"id":"s26-196","number":196,"surah":26,"verses":[224,225,226],"references":[{"surah":26,"verses":[224,225,226]}],"verseLabel":"الشعراء: 224-226","question":"ما فائدة قوله عن الشعراء: ﴿وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ﴾؟","answer":"كشف التناقض بين القول والعمل، وأن كثيرًا من دعاواهم لا يقصد به التزام ولا حقيقة، فزاد أسباب الذم بيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص567، تحت عنوان «فائدة استعمال مفردة ﴿يفعلون﴾»","url":""}]},{"id":"s26-197","number":197,"surah":26,"verses":[224,225,226],"references":[{"surah":26,"verses":[224,225,226]}],"verseLabel":"الشعراء: 224-226","question":"ما دلالة الاستثناء في قوله: ﴿إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ﴾؟","answer":"أخرج شعراء الإيمان والعمل الصالح من الذم، فدل على أن المذموم هو الشعر الباطل وسلوك صاحبه لا جنس الشعر كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص568، تحت عنوان «نوع الاستثناء بـ﴿إلا﴾ ودلالته»","url":""}]},{"id":"s26-96","number":96,"surah":26,"verses":[227],"references":[{"surah":26,"verses":[227]}],"verseLabel":"الشعراء: 227","question":"ما دلالة الواو في قوله: ﴿وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا﴾؟","answer":"ربطت الواو الوعيد بما قبله وجعلته خاتمة عامة تشمل كل ظالم، بعد بيان نجاة المؤمنين وانتصارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص573، تحت عنوان «نوع واو ﴿وسيعلم﴾ ودلالتها»","url":""}]},{"id":"s26-198","number":198,"surah":26,"verses":[227],"references":[{"surah":26,"verses":[227]}],"verseLabel":"الشعراء: 227","question":"ما دلالة السين في قوله: ﴿وَسَيَعْلَمُ الَّذِينَ ظَلَمُوا﴾؟","answer":"أنذرت بقرب تحقق الوعيد وأكدت وقوعه في المستقبل، فهددت الظالمين بعاقبة لا يفلتون منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص573–574، تحت عنوان «دلالة استعمال حرف السين مع الفعل ﴿وسيعلم﴾»","url":""}]},{"id":"s26-199","number":199,"surah":26,"verses":[227],"references":[{"surah":26,"verses":[227]}],"verseLabel":"الشعراء: 227","question":"ما بلاغة الإبهام في قوله: ﴿أَيَّ مُنْقَلَبٍ﴾؟","answer":"أبهم نوع المنقلب تهويلًا للمصير، فترك النفس تتصور من سوء العاقبة ما لا يحيط به البيان المفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص574، تحت عنوان «بلاغة الإبهام في استعمال ﴿أي﴾»","url":""}]},{"id":"s26-200","number":200,"surah":26,"verses":[227],"references":[{"surah":26,"verses":[227]}],"verseLabel":"الشعراء: 227","question":"ما فائدة الجناس في قوله: ﴿مُنْقَلَبٍ يَنْقَلِبُونَ﴾؟","answer":"جمع اللفظين من مادة واحدة في جناس اشتقاقي، فحرك الذهن إلى معنى التحول ورسّخ وعيد المصير في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص576، تحت عنوان «فائدة الجناس في ﴿منقلب ينقلبون﴾»","url":""}]},{"id":"s27-1","number":1,"surah":27,"verses":[1],"references":[{"surah":27,"verses":[1]}],"verseLabel":"النمل: 1","question":"لماذا قُدِّم لفظ ﴿الْقُرْآنِ﴾ على ﴿وَكِتَابٍ مُبِينٍ﴾؟","answer":"قُدِّم وصف التلاوة لأنه الأنسب بمقام تلقي الوحي وقراءته على الناس، ثم جاء وصف الكتاب جامعًا لما في القرآن من كمال وضبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص590–591، تحت عنوان «نكتة تقديم ﴿القرآن﴾ على ﴿وكتاب﴾»","url":""}]},{"id":"s27-86","number":86,"surah":27,"verses":[1],"references":[{"surah":27,"verses":[1]}],"verseLabel":"النمل: 1","question":"ما سر وصف الكتاب بأنه ﴿مُبِينٍ﴾؟","answer":"دل الوصف على وضوح القرآن في نفسه وإظهاره الحق والشرائع، وعلى ظهور إعجازه وحجته للناظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص591، تحت عنوان «سر وصف (الكتاب) بـ(المبين)»","url":""}]},{"id":"s27-2","number":2,"surah":27,"verses":[2],"references":[{"surah":27,"verses":[2]}],"verseLabel":"النمل: 2","question":"ما معنى اللام في قوله: ﴿لِلْمُؤْمِنِينَ﴾؟","answer":"اللام للتعليل أو للاختصاص؛ فالمؤمنون هم الذين ينتفعون بهداية القرآن ويفوزون ببشارته، مع بقاء أصل هدايته معروضًا للناس جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص594، تحت عنوان «معنى اللام في قوله: ﴿للمؤمنين﴾»","url":""}]},{"id":"s27-3","number":3,"surah":27,"verses":[3],"references":[{"surah":27,"verses":[3]}],"verseLabel":"النمل: 3","question":"لماذا وُصف المؤمنون باليقين بالآخرة بعد إقامة الصلاة وإيتاء الزكاة؟","answer":"لأن اليقين بالآخرة باعث جامع على الطاعات ومراقبة الجزاء، فذكره بعد العملين يبين الأصل الإيماني الذي يثبتهم عليهما وعلى سائر الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص598، تحت عنوان «فائدة الوصف بالإيمان بالآخرة بعد الوصف بإقامة الصلاة وإيتاء الزكاة»","url":""}]},{"id":"s27-87","number":87,"surah":27,"verses":[3],"references":[{"surah":27,"verses":[3]}],"verseLabel":"النمل: 3","question":"ما نكتة العدول من الفعل في ﴿يُقِيمُونَ﴾ و﴿يُؤْتُونَ﴾ إلى الجملة الاسمية في ﴿وَهُمْ بِالْآخِرَةِ هُمْ يُوقِنُونَ﴾؟","answer":"أكدت الجملة الاسمية وضمير الفصل رسوخ يقينهم بالآخرة وثباته، بخلاف الأفعال التي صورت تجدد أعمالهم من صلاة وزكاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص598، تحت عنوان «نكتة العدول في النظم من الجمل الفعلية إلى الاسمية»","url":""}]},{"id":"s27-4","number":4,"surah":27,"verses":[4],"references":[{"surah":27,"verses":[4]}],"verseLabel":"النمل: 4","question":"ما سر إسناد تزيين أعمال الكافرين إلى ضمير العظمة في قوله: ﴿زَيَّنَّا لَهُمْ أَعْمَالَهُمْ﴾؟","answer":"أبرز الإسناد عظم أثر التزيين وخطورة عاقبته، وأن ما وقع بهم جارٍ تحت سلطان الله وحكمه بعد إصرارهم على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص605، تحت عنوان «سر إسناد الزينة إلى ضمير العظمة»","url":""}]},{"id":"s27-88","number":88,"surah":27,"verses":[4],"references":[{"surah":27,"verses":[4]}],"verseLabel":"النمل: 4","question":"كيف يُفهم إسناد تزيين أعمال الكافرين إلى الله مع إسناده إلى الشيطان في مواضع أخرى؟","answer":"يُحمل على الحقيقة من جهة أن الله خالق القوى والأسباب التي يقع بها التزيين، والشيطان سبب مباشر؛ ويُحمل على المجاز من جهة أن الإمهال والنعم صارا عندهم سببًا لاستحسان باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص606، تحت عنوان «إسناد الزينة إلى الله بين الحقيقة والمجاز»","url":""}]},{"id":"s27-5","number":5,"surah":27,"verses":[6],"references":[{"surah":27,"verses":[6]}],"verseLabel":"النمل: 6","question":"ما نكتة بناء الفعل ﴿لَتُلَقَّى﴾ للمفعول؟","answer":"حُذف الفاعل للعلم به؛ فهو جبريل الذي يبلّغ الوحي أو الله مصدر القرآن، فتركه يعظم التلقي ويصرف النظر إلى القرآن الملقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص615، تحت عنوان «نكتة بناء الفعل ﴿لتلقى﴾ للمفعول»","url":""}]},{"id":"s27-89","number":89,"surah":27,"verses":[6],"references":[{"surah":27,"verses":[6]}],"verseLabel":"النمل: 6","question":"ما نكتة تذييل قوله: ﴿وَإِنَّكَ لَتُلَقَّى الْقُرْآنَ﴾ بوصفي ﴿حَكِيمٍ عَلِيمٍ﴾؟","answer":"ربط الوصفان القرآن بمصدره الكامل: الحكيم يضع الوحي في موضعه ويختار رسوله، والعليم يحيط بأحوال الخلق؛ فيطمئن المتلقي إلى إحكامه وعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص617، تحت عنوان «نكتة تذييل الآية الكريمة بهذين الوصفين»","url":""}]},{"id":"s27-6","number":6,"surah":27,"verses":[7],"references":[{"surah":27,"verses":[7]}],"verseLabel":"النمل: 7","question":"ما سرّ اختلاف قول موسى عند النار بين النمل وطه والقصص؟","answer":"في النمل جاء الوعد جازمًا ﴿سآتيكم﴾، مع تقديم الخبر وتكرار فعل الإتيان؛ وفي طه ﴿لعلي آتيكم منها بقبس أو أجد على النار هدى﴾، وفي القصص ﴿لعلي آتيكم منها بخبر﴾. ويربط المبحث قوة التعبير في النمل بتثبيت تلقي الوحي، والترجي في طه والقصص بما يلابس رحلة موسى من حاجة وخوف وتعب، فكل صياغة تلائم سياقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص627–628، تحت عنوان «توجيه المتشابه اللفظي بين ما جاء في سورتي (طه) و(القصص)»","url":""}]},{"id":"s27-7","number":7,"surah":27,"verses":[7],"references":[{"surah":27,"verses":[7]}],"verseLabel":"النمل: 7","question":"ما سرّ الجزم بـ﴿سَآتِيكُمْ﴾ في النمل، والترجي بـ﴿لَعَلِّي آتِيكُمْ﴾ في القصص؟","answer":"﴿سآتيكم﴾ أقوى في تثبيت الخبر مستقبلًا، وناسب في النمل ما سبق من تثبيت الرسول بقوة تلقي القرآن؛ أما ﴿لعلي آتيكم﴾ في القصص فترجٍّ ناسبه ما سبق من السفر والتعب والخوف، فلا يجزم بما لم يستيقنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص627–628، تحت عنوان «توجيه المتشابه اللفظي بين ما جاء في سورتي (طه) و(القصص)»","url":""}]},{"id":"s27-8","number":8,"surah":27,"verses":[8],"references":[{"surah":27,"verses":[8]}],"verseLabel":"النمل: 8","question":"من المراد بالاسم الموصول ﴿مَنْ﴾ في قوله: ﴿بُورِكَ مَنْ فِي النَّارِ وَمَنْ حَوْلَهَا﴾؟","answer":"من أوجه التفسير أن المراد موسى لقربه من موضع النار، ومن حولها الملائكة الذين وكل إليهم أمر ذلك المكان؛ فالبركة شملت من أحاط بالمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص632، تحت عنوان «المراد بالاسم الموصول ﴿من﴾»","url":""}]},{"id":"s27-90","number":90,"surah":27,"verses":[8],"references":[{"surah":27,"verses":[8]}],"verseLabel":"النمل: 8","question":"ما نكتة التعبير بالاسم الموصول وصلته في قوله: ﴿مَنْ فِي النَّارِ وَمَنْ حَوْلَهَا﴾؟","answer":"عدل إلى الموصول للتعظيم والتلطف، وربط البركة بوصف الحضور حول الموضع المبارك، من غير تصريح يوقع في توهم غير مراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص632، تحت عنوان «نكتة التعبير بالاسم الموصول وصلته»","url":""}]},{"id":"s27-91","number":91,"surah":27,"verses":[8],"references":[{"surah":27,"verses":[8]}],"verseLabel":"النمل: 8","question":"ما معنى الواو في قوله: ﴿وَسُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ﴾ بعد ذكر النار؟","answer":"تحتمل العطف أو الاعتراض، وفي الوجهين جاء التنزيه ليمنع توهم مشابهة الله للمخلوقات أو حلوله في مكان، ويثبت كماله المطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص633، تحت عنوان «معنى الواو في جملة الفاصلة ﴿وسبحان﴾»","url":""}]},{"id":"s27-9","number":9,"surah":27,"verses":[9],"references":[{"surah":27,"verses":[9]}],"verseLabel":"النمل: 9","question":"ما نكتة فصل النداء ﴿يَا مُوسَى﴾ عما قبله؟","answer":"استقل النداء لأنه إنشاء بعد خبر، وجاء تمهيدًا للخطاب الإلهي وتنبيهًا لموسى وطمأنة له قبل التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص634–635، تحت عنوان «نكتة فصل قوله تعالى: ﴿يا موسى﴾»","url":""}]},{"id":"s27-92","number":92,"surah":27,"verses":[9],"references":[{"surah":27,"verses":[9]}],"verseLabel":"النمل: 9","question":"ما نكتة تذييل تعريف الله نفسه لموسى باسمي ﴿الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"العزيز لا يُغالب ويؤيد رسله، والحكيم يضع الاختيار والتكليف في موضعهما؛ فناسب الاسمان مهمة موسى ومواجهة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص635، تحت عنوان «نكتة تذييل الآية بهذين الاسمين الجليلين»","url":""}]},{"id":"s27-10","number":10,"surah":27,"verses":[10],"references":[{"surah":27,"verses":[10]}],"verseLabel":"النمل: 10","question":"ما سر تشبيه العصا بـ﴿جَانٌّ﴾ في النمل، ووصفها بـ﴿ثُعْبَانٌ مُبِينٌ﴾ في الشعراء؟","answer":"التشبيه بالجان يبرز خفة الحركة وسرعتها واضطرابها حين فوجئ موسى بالعصا، أما ﴿ثعبان مبين﴾ في عرض الآية أمام فرعون فيبرز ضخامة الحية ووضوح حقيقتها؛ فكل تعبير يصف الجهة التي يقتضيها المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص644، تحت عنوان «بلاغة المتشابه اللفظي في وصف العصا»","url":""}]},{"id":"s27-11","number":11,"surah":27,"verses":[10],"references":[{"surah":27,"verses":[10]}],"verseLabel":"النمل: 10","question":"ما دلالة قوله: ﴿وَلَّى مُدْبِرًا﴾ وإعراب ﴿مُدْبِرًا﴾؟","answer":"صوّر التولي فراره السريع، وجاء ﴿مدبرًا﴾ حالًا تؤكد هيئة الهرب والانصراف عقب رؤية العصا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص645، تحت عنوان «دلالة الإدبار وإعرابه»","url":""}]},{"id":"s27-93","number":93,"surah":27,"verses":[10],"references":[{"surah":27,"verses":[10]}],"verseLabel":"النمل: 10","question":"ما معنى الواو في قوله: ﴿وَلَمْ يُعَقِّبْ﴾؟","answer":"تحتمل العطف أو الحال، وفي الوجهين أكدت أنه لم يرجع ولم يلتفت بعد توليه، فاستكملت صورة شدة المفاجأة والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص645–646، تحت عنوان «معنى الواو في: ﴿ولم يعقب﴾»","url":""}]},{"id":"s27-94","number":94,"surah":27,"verses":[10],"references":[{"surah":27,"verses":[10]}],"verseLabel":"النمل: 10","question":"ما دلالة النهي في قوله لموسى: ﴿لَا تَخَفْ﴾؟","answer":"لم يرد به تكليف تشريعي مجرد، بل تسكين الخوف وطمأنة موسى بعد حصوله، مع قطع سببه وإشعاره بالأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص646، تحت عنوان «دلالة النهي في قوله: ﴿لا تخف﴾»","url":""}]},{"id":"s27-12","number":12,"surah":27,"verses":[11],"references":[{"surah":27,"verses":[11]}],"verseLabel":"النمل: 11","question":"ما أوجه الاستثناء في ﴿إِلَّا مَنْ ظَلَمَ ثُمَّ بَدَّلَ حُسْنًا بَعْدَ سُوءٍ﴾ بعد أمان المرسلين؟","answer":"من الأوجه أن الاستثناء منقطع: لكن من ظلم ثم تاب وبدّل حسنًا بعد سوء فالله غفور رحيم؛ وفيه طمأنة لموسى مما وقع منه قبل الرسالة. وقيل متصل بالنظر إلى ما يقع من النبي من زلة أو ترك للأولى، فالتوبة تبدل الخوف أمنًا. وتورد الموسوعة الوجهين دون حصر المعنى في أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص648–649، تحت عنوان «نوع الاستثناء في: ﴿إلا من ظلم﴾»","url":""}]},{"id":"s27-13","number":13,"surah":27,"verses":[12],"references":[{"surah":27,"verses":[12]}],"verseLabel":"النمل: 12","question":"ما سرّ التعبير بـ﴿فِي تِسْعِ آيَاتٍ إِلَى فِرْعَوْنَ وَقَوْمِهِ﴾؟","answer":"«في» على أحد الأوجه تجعل العصا واليد آيتين داخل جملة التسع التي أرسل بها موسى إلى فرعون وقومه. وذُكر وجه آخر بمعنى «مع»، أي مع آيات أخرى؛ فالتعبير يربط الآيتين بسائر دلائل الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص655–656، تحت عنوان «معنى ﴿في﴾ في قوله: ﴿في تسع آيات﴾»","url":""}]},{"id":"s27-14","number":14,"surah":27,"verses":[13],"references":[{"surah":27,"verses":[13]}],"verseLabel":"النمل: 13","question":"ما دلالة وصفهم السحر بلفظ ﴿مُبِينٌ﴾؟","answer":"زعموا أن السحر الذي جاء به موسى ظاهر شديد الوضوح، فقلبوا وضوح المعجزة إلى وضوح السحر تلبيسًا على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص660، تحت عنوان «دلالة التعبير بـ﴿مبين﴾ مادة وصيغة»","url":""}]},{"id":"s27-15","number":15,"surah":27,"verses":[14],"references":[{"surah":27,"verses":[14]}],"verseLabel":"النمل: 14","question":"لماذا عُبّر عن إنكارهم بلفظ ﴿وَجَحَدُوا﴾؟","answer":"الجحود إنكار مع معرفة الحق في القلب، فناسب قوم فرعون الذين ظهرت لهم الآيات وثبتت حقيقتها ثم أنكروها بألسنتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص667، تحت عنوان «سر التعبير بالجحود دون الإنكار»","url":""}]},{"id":"s27-95","number":95,"surah":27,"verses":[14],"references":[{"surah":27,"verses":[14]}],"verseLabel":"النمل: 14","question":"ما سر التعبير بـ﴿وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ﴾ بعد الجحود؟","answer":"كشف أن يقينهم بالآيات بلغ نفوسهم واستقر فيها، فظهر التناقض بين العلم الباطن والتكذيب المعلن.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص669، تحت عنوان «سر التعبير بالاستيقان بعد الجحود»","url":""}]},{"id":"s27-96","number":96,"surah":27,"verses":[14],"references":[{"surah":27,"verses":[14]}],"verseLabel":"النمل: 14","question":"ما أثر إعراب ﴿ظُلْمًا وَعُلُوًّا﴾ على معنى جحودهم؟","answer":"يفيد نصبهما التعليل أو الحال، وفي الوجهين يبين أن الظلم والاستكبار هما اللذان حملاهم على الجحود، لا خفاء الدليل أو نقص اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص670، تحت عنوان «أثر إعراب ﴿ظلما وعلوا﴾ على المعنى»","url":""}]},{"id":"s27-16","number":16,"surah":27,"verses":[15],"references":[{"surah":27,"verses":[15]}],"verseLabel":"النمل: 15","question":"ما سرّ اختيار داود وسليمان ﴿الْحَمْدُ لِلَّهِ﴾ دون «الشكر لله»؟","answer":"الحمد ثناء على كمال المحمود وصفاته ونعمه، وهو أعم متعلقًا من الشكر الذي يكون في مقابلة النعمة؛ فناسب مقام العلم والاصطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص684، تحت عنوان «علة اختيار ﴿الحمد﴾ دون (الشكر)»","url":""}]},{"id":"s27-17","number":17,"surah":27,"verses":[15],"references":[{"surah":27,"verses":[15]}],"verseLabel":"النمل: 15","question":"ما سرّ عطف حمد داود وسليمان بالواو بعد إيتائهما العلم؟","answer":"عُطف الحمد بالواو لا بالفاء؛ للإشعار بأن بين إيتاء العلم وحمدهما أحداثًا وممارسةً للعلم أظهرت لهما قدر النعمة، ثم حمدا الله عليها، فلا تفيد الواو التعقيب الفوري.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص681–682، تحت عنوان «سر العطف بالواو دون الفاء في: ﴿وقالا﴾»","url":""}]},{"id":"s27-18","number":18,"surah":27,"verses":[16],"references":[{"surah":27,"verses":[16]}],"verseLabel":"النمل: 16","question":"ما بلاغة المجاز في قوله: ﴿وَوَرِثَ سُلَيْمَانُ دَاوُودَ﴾؟","answer":"استعير الإرث لانتقال ما اختص به داود من الملك والعلم والنبوة إلى سليمان، فالمقصود الخلافة في المنزلة لا قسمة المال بين الأبناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص693–694، تحت عنوان «بلاغة المجاز في جملة: ﴿وورث﴾»","url":""}]},{"id":"s27-97","number":97,"surah":27,"verses":[16],"references":[{"surah":27,"verses":[16]}],"verseLabel":"النمل: 16","question":"ما سر اختيار لفظ الوراثة في قوله: ﴿وَوَرِثَ سُلَيْمَانُ دَاوُودَ﴾؟","answer":"الوراثة أقوى ألفاظ الانتقال في التمليك والاستحقاق، فصورت ثبوت ما آتاه الله سليمان واستقراره له بعد أبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص694، تحت عنوان «سر التعبير بالوراثة في ﴿وورث﴾»","url":""}]},{"id":"s27-19","number":19,"surah":27,"verses":[16],"references":[{"surah":27,"verses":[16]}],"verseLabel":"النمل: 16","question":"ما سرّ التعبير بـ﴿عُلِّمْنَا مَنْطِقَ الطَّيْرِ﴾؟","answer":"أطلق «المنطق» على أصوات الطير لأنها تعبر عن معانٍ يفهمها سليمان بتعليم الله؛ فهو تصوير لما في أصواتها من دلالة على حاجاتها وأحوالها، وليس وصفًا لها بالكلام البشري المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص696، تحت عنوان «بلاغة الاستعارة في ﴿منطق الطير﴾»","url":""}]},{"id":"s27-20","number":20,"surah":27,"verses":[17],"references":[{"surah":27,"verses":[17]}],"verseLabel":"النمل: 17","question":"لماذا قيل ﴿وَحُشِرَ لِسُلَيْمَانَ جُنُودُهُ﴾ ولم يقل «جُمعت»؟","answer":"الحشر جمع من جهات مختلفة مع سوق وضبط، فناسب كثرة الجنود وتنوع أجناسهم واتساع سلطان سليمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص703، تحت عنوان «نكتة التعبير بالحشر دون الجمع»","url":""}]},{"id":"s27-21","number":21,"surah":27,"verses":[17],"references":[{"surah":27,"verses":[17]}],"verseLabel":"النمل: 17","question":"ما سرّ التعبير بـ﴿فَهُمْ يُوزَعُونَ﴾؟","answer":"يوزعون أي يُكف أولهم حتى يلحق آخرهم؛ صورة لانضباط جيش عظيم لا يطغى بعضه على بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص708، تحت عنوان «دلالة التعبير بقوله: ﴿يوزعون﴾ دون غيره»","url":""}]},{"id":"s27-22","number":22,"surah":27,"verses":[18],"references":[{"surah":27,"verses":[18]}],"verseLabel":"النمل: 18","question":"ما سر التعبير بالحطم في قول النملة: ﴿لَا يَحْطِمَنَّكُمْ﴾؟","answer":"الحطم كسر الشيء الهش، فناسب أجسام النمل الدقيقة وصوّر الخطر الواقع عليها تحت الأقدام تصويرًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص719، تحت عنوان «سر التعبير بالحطم دون غيره»","url":""}]},{"id":"s27-98","number":98,"surah":27,"verses":[18],"references":[{"surah":27,"verses":[18]}],"verseLabel":"النمل: 18","question":"ما دلالة الواو في قول النملة: ﴿وَهُمْ لَا يَشْعُرُونَ﴾؟","answer":"هي للحال غالبًا، فاعتذرت لسليمان وجنوده بأن الحطم إن وقع فبغير قصد ولا شعور، وأظهرت حسن ظنها بعدلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص720، تحت عنوان «دلالة الواو في قوله: ﴿وهم لا يشعرون﴾»","url":""}]},{"id":"s27-23","number":23,"surah":27,"verses":[19],"references":[{"surah":27,"verses":[19]}],"verseLabel":"النمل: 19","question":"ما سر تقييد تبسم سليمان بلفظ ﴿ضَاحِكًا﴾؟","answer":"دل القيد على أن أثر قول النملة تجاوز ابتداء التبسم إلى سرور وضحك لطيف، مع نفي أن يكون تبسمه مجرد تصنع أو استهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص725–726، تحت عنوان «سر التقييد بلفظ: ﴿ضاحكا﴾»","url":""}]},{"id":"s27-99","number":99,"surah":27,"verses":[19],"references":[{"surah":27,"verses":[19]}],"verseLabel":"النمل: 19","question":"ما دلالة الجمع بين التبسم والضحك في قوله: ﴿فَتَبَسَّمَ ضَاحِكًا﴾؟","answer":"التبسم مبدأ الضحك وألطفه، والضحك أظهر منه؛ فجمعهما لتصوير تدرج السرور واجتماع لطف الابتسام مع قوة التأثر بقول النملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص726، تحت عنوان «دلالة الجمع بين (الضحك) و(التبسم)»","url":""}]},{"id":"s27-24","number":24,"surah":27,"verses":[19],"references":[{"surah":27,"verses":[19]}],"verseLabel":"النمل: 19","question":"ما غرض النداء في دعاء سليمان: ﴿رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ﴾؟","answer":"أظهر النداء تضرع سليمان وابتهاله، ونبّه إلى قربه من ربه قبل عرض حاجته، مع الإيجاز بحذف أداة النداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص728، تحت عنوان «غرض الإتيان بالنداء»","url":""}]},{"id":"s27-100","number":100,"surah":27,"verses":[19],"references":[{"surah":27,"verses":[19]}],"verseLabel":"النمل: 19","question":"ما سر عطف العمل الصالح على الشكر في دعاء سليمان؟","answer":"لأن شكر اللسان يستديم النعمة، والعمل الصالح ثمرة عملية له وسبب للفوز بالجنة؛ فجمع الدعاء بين دوام النعمة وحسن العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص733، تحت عنوان «سر عطف العمل الصالح على الشكر»","url":""}]},{"id":"s27-25","number":25,"surah":27,"verses":[20],"references":[{"surah":27,"verses":[20]}],"verseLabel":"النمل: 20","question":"ما نكتة صيغة التفعّل في قوله: ﴿وَتَفَقَّدَ الطَّيْرَ﴾؟","answer":"دلّت صيغة التفعّل على تكلف البحث والتحري وبذل الجهد لمعرفة حال الطير؛ فالتفقد طلب ما غاب عن الإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص742، تحت عنوان «نكتة ﴿وتفقد﴾ بصيغة (تفعل)»","url":""}]},{"id":"s27-101","number":101,"surah":27,"verses":[20],"references":[{"surah":27,"verses":[20]}],"verseLabel":"النمل: 20","question":"ما دلالة إسناد تفقد الطير إلى سليمان نفسه؟","answer":"دل على مباشرته شؤون جنده ورعيته بنفسه، وتعليمه الولاة أن يتابعوا أحوال من تحت أيديهم؛ لأن المسؤول أدرى برعيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص742، تحت عنوان «دلالة إسناد التفقد لسليمان»","url":""}]},{"id":"s27-102","number":102,"surah":27,"verses":[20],"references":[{"surah":27,"verses":[20]}],"verseLabel":"النمل: 20","question":"ما دلالة ياء المتكلم في قول سليمان: ﴿مَا لِيَ لَا أَرَى الْهُدْهُدَ﴾؟","answer":"بدأ سليمان بالنظر في حال نفسه، كأنه يسأل: أفي بصري مانع؟ وفي ذلك إنصاف وتحرٍّ قبل الحكم على الهدهد بالغياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص743–744، تحت عنوان «دلالة ياء المتكلم في قوله: ﴿مالي﴾»","url":""}]},{"id":"s27-103","number":103,"surah":27,"verses":[20],"references":[{"surah":27,"verses":[20]}],"verseLabel":"النمل: 20","question":"ما سر نفي الرؤية في قوله: ﴿لَا أَرَى الْهُدْهُدَ﴾ بدل نفي وجوده؟","answer":"لأن الرؤية أصدق في التحقق من الحضور والغياب؛ فقد يكون الهدهد حاضرًا خفيًا عن الناظر، فلم يجزم سليمان بغيابه قبل التثبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص744، تحت عنوان «سر نفي الرؤية في قوله: ﴿لا أرى﴾»","url":""}]},{"id":"s27-26","number":26,"surah":27,"verses":[21],"references":[{"surah":27,"verses":[21]}],"verseLabel":"النمل: 21","question":"ما سر التعبير بـ﴿أَوْ﴾ في وعيد سليمان للهدهد؟","answer":"جاءت ﴿أو﴾ الأولى للتخيير بين التعذيب والذبح بحسب ما تقتضيه المخالفة، والثانية للتقسيم بين العقوبة والإتيان بحجة تعفيه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص751–752، تحت عنوان «سر التعبير بـ﴿أو﴾ دون غيرها»","url":""}]},{"id":"s27-104","number":104,"surah":27,"verses":[21],"references":[{"surah":27,"verses":[21]}],"verseLabel":"النمل: 21","question":"ما دلالة وصف السلطان بلفظ ﴿مُبِينٍ﴾ في عذر الهدهد؟","answer":"دل الوصف على أن المطلوب حجة ظاهرة واضحة تقطع العذر وتدفع العقوبة، لا دعوى محتملة أو تبرير غامض.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص754، تحت عنوان «دلالة وصف ﴿بسلطان﴾ بلفظ (مبين)»","url":""}]},{"id":"s27-27","number":27,"surah":27,"verses":[22],"references":[{"surah":27,"verses":[22]}],"verseLabel":"النمل: 22","question":"ما سرّ التعبير في قول الهدهد بـ﴿أَحَطْتُ بِمَا لَمْ تُحِطْ بِهِ﴾ لنبي ملك؟","answer":"بدأ بما يشوق سليمان إلى الإصغاء ويصرفه عن المبادرة إلى العقوبة، فقد حمل علمًا غاب عنه. وفيه تنبيه إلى أن علم المخلوق، مهما عظم، لا يحيط بكل شيء، وقد يعلم الأدنى ما لم يعلمه الأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص758–759، تحت عنوان «سر ابتداء الهدهد بالإحاطة»","url":""}]},{"id":"s27-28","number":28,"surah":27,"verses":[22],"references":[{"surah":27,"verses":[22]}],"verseLabel":"النمل: 22","question":"ما نكتة وصف النبأ بلفظ ﴿يَقِينٍ﴾؟","answer":"أكد أن الخبر متحقق لا شبهة فيه؛ لأن الهدهد علمه بالعيان والمشاهدة، فدفع احتمال الظن والكذب وطمأن سليمان إلى صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص762–763، تحت عنوان «نكتة وصف النبأ باليقين»","url":""}]},{"id":"s27-29","number":29,"surah":27,"verses":[23],"references":[{"surah":27,"verses":[23]}],"verseLabel":"النمل: 23","question":"ما معنى الملك في قوله عن امرأة سبأ: ﴿تَمْلِكُهُمْ﴾؟","answer":"الملك هنا القهر والحكم؛ فهي صاحبة السلطان عليهم، وهم خاضعون لأمرها وتدبيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص768، تحت عنوان «معنى الملك في قوله تعالى: ﴿تملكهم﴾»","url":""}]},{"id":"s27-105","number":105,"surah":27,"verses":[23],"references":[{"surah":27,"verses":[23]}],"verseLabel":"النمل: 23","question":"ما سر التعبير بالمضارع في قوله: ﴿تَمْلِكُهُمْ﴾؟","answer":"صوّر المضارع توليها الحكم حال رواية الهدهد، ودل على استمرار سلطانها وتجدد تدبيرها لقومها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص769، تحت عنوان «سر التعبير بالمضارع: ﴿تملكهم﴾»","url":""}]},{"id":"s27-30","number":30,"surah":27,"verses":[24],"references":[{"surah":27,"verses":[24]}],"verseLabel":"النمل: 24","question":"ما دلالة فصل قوله: ﴿وَجَدْتُهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ﴾ عما قبله؟","answer":"استؤنفت الجملة للتعجيب من حالهم والانتقال من وصف دنياهم وملكهم إلى فساد دينهم، فكأن السامع سأل عن حالهم الدينية فجاء الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص778، تحت عنوان «دلالة الفصل في الآية»","url":""}]},{"id":"s27-106","number":106,"surah":27,"verses":[24],"references":[{"surah":27,"verses":[24]}],"verseLabel":"النمل: 24","question":"ما سر تكرار فعل الوجدان ماضيًا في خبر الهدهد عن سبأ؟","answer":"كرر ﴿وجدت﴾ ليؤكد أن خبره قائم على المشاهدة الحسية، وليلفت إلى رسوخ عبادتهم للشمس كما ثبت ملك المرأة وقومها.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص778–779، تحت عنوان «سر تكرار فعل الوجدان ماضيا»","url":""}]},{"id":"s27-31","number":31,"surah":27,"verses":[25],"references":[{"surah":27,"verses":[25]}],"verseLabel":"النمل: 25","question":"لماذا خُص إخراج الخبء بالذكر في الدعوة إلى السجود لله؟","answer":"لأنه دليل ظاهر على القدرة والإنعام بإخراج المطر والنبات والأرزاق، وهو أنسب بقول الهدهد لما أودعه الله فيه من معرفة الماء المخبوء تحت الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص792، تحت عنوان «فائدة تخصيص إخراج الخبء بالذكر»","url":""}]},{"id":"s27-107","number":107,"surah":27,"verses":[25],"references":[{"surah":27,"verses":[25]}],"verseLabel":"النمل: 25","question":"ما نكتة الجمع بين إخراج الخبء والعلم في قوله: ﴿وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ﴾؟","answer":"خُص الوصفان لأن كلًّا منهما يدل على اختصاص الله باستحقاق العبادة: فهو يخرج ما خفي ويعلم السر والعلن، وذلك لا يكون للشمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص797، تحت عنوان «نكتة تخصيص إخراج الخبء والعلم بالذكر»","url":""}]},{"id":"s27-32","number":32,"surah":27,"verses":[25],"references":[{"surah":27,"verses":[25]}],"verseLabel":"النمل: 25","question":"ما سرّ اختلاف القراءة بين الخطاب في ﴿مَا تُخْفُونَ وَمَا تُعْلِنُونَ﴾ والغيبة؟","answer":"قرأ الكسائي وحفص بالخطاب، وقرأ الباقون بالغيبة. فالغيبة تحكي علم الله بما يخفيه القوم ويعلنونه، والخطاب قد يتجه إلى حاضري مجلس سليمان أو يكون خطابًا عامًا. وعلى الظاهر هو من كلام الهدهد، وقيل إن الآية اعتراض من كلام الله؛ فتتجه قراءة الخطاب حينئذ إلى الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج39، ص796، تحت عنوان «توجيه القراءات في ﴿تخفون﴾ و﴿تعلنون﴾»","url":""}]},{"id":"s27-33","number":33,"surah":27,"verses":[27],"references":[{"surah":27,"verses":[27]}],"verseLabel":"النمل: 27","question":"ما دلالة السين في قول سليمان: ﴿سَنَنْظُرُ﴾؟","answer":"دلّت على الاستقبال والتريث؛ أي سنستغرق في التجربة التي يتبين بها صدق الخبر، فلا يعجل بالحكم قبل الاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص15، تحت عنوان «دلالة السين في ﴿سننظر﴾»","url":""}]},{"id":"s27-108","number":108,"surah":27,"verses":[27],"references":[{"surah":27,"verses":[27]}],"verseLabel":"النمل: 27","question":"ما دلالة جملة الاستفهام في قوله: ﴿أَصَدَقْتَ أَمْ كُنْتَ مِنَ الْكَاذِبِينَ﴾؟","answer":"أظهرت تردد الحكم بين الصدق والكذب بعد الخبر العجيب، وشوقت إلى نتيجة الاختبار مع فتح باب النجاة للهدهد إن ثبت صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص16، تحت عنوان «دلالة جملة الاستفهام»","url":""}]},{"id":"s27-34","number":34,"surah":27,"verses":[28],"references":[{"surah":27,"verses":[28]}],"verseLabel":"النمل: 28","question":"ما المراد بقول سليمان للهدهد: ﴿ثُمَّ تَوَلَّ عَنْهُمْ﴾؟","answer":"أمره أن يتنحى إلى مكان قريب متواريًا عنهم، ليسمع ما يقولون من غير أن يشعروا به، لا أن ينصرف انصرافًا تامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص25، تحت عنوان «المراد بقوله تعالى: ﴿ثم تول عنهم﴾»","url":""}]},{"id":"s27-109","number":109,"surah":27,"verses":[28],"references":[{"surah":27,"verses":[28]}],"verseLabel":"النمل: 28","question":"ما معنى الفاء في قوله: ﴿فَانْظُرْ مَاذَا يَرْجِعُونَ﴾؟","answer":"الفاء للتعقيب؛ أي أعقب توليك بالمراقبة، فتمت المهمة بإيصال الكتاب ثم ترقب جوابهم واستحضاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص25، تحت عنوان «معنى الفاء في ﴿فانظر﴾»","url":""}]},{"id":"s27-35","number":35,"surah":27,"verses":[29],"references":[{"surah":27,"verses":[29]}],"verseLabel":"النمل: 29","question":"ما سرّ وصف ملكة سبأ الكتاب بأنه ﴿كِتَابٌ كَرِيمٌ﴾؟","answer":"ذكرت الموسوعة وجوهًا لوصفه بالكريم: كونه مختومًا، أو صدوره من ملك، أو حسن مضمونه ولين موعظته ودعوته إلى الله وحسن الاستعطاف، أو غرابة طريق وصوله وتسخير الطير لحمله؛ فالوصف لا ينحصر في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص31–32، تحت عنوان «سر وصف الكتاب بالكريم»","url":""}]},{"id":"s27-36","number":36,"surah":27,"verses":[30],"references":[{"surah":27,"verses":[30]}],"verseLabel":"النمل: 30","question":"ما سر افتتاح سليمان كتابه بالبسملة؟","answer":"افتتح بالبسملة لإثبات أن للكتاب صانعًا وربًا حكيمًا رحيمًا، ولتعريف المخاطبين بالإله الذي يدعوهم سليمان إلى عبادته والاستعانة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص35–36، تحت عنوان «سر افتتاح سليمان عليه السلام كتابه بالبسملة»","url":""}]},{"id":"s27-37","number":37,"surah":27,"verses":[31],"references":[{"surah":27,"verses":[31]}],"verseLabel":"النمل: 31","question":"ما بلاغة الطرد والعكس بين ﴿أَلَّا تَعْلُوا عَلَيَّ﴾ و﴿وَأْتُونِي مُسْلِمِينَ﴾؟","answer":"جعل مفهوم كل من الجملتين مؤكدًا لمنطوق الأخرى: فترك العلو يقتضي الانقياد، والإتيان مسلمين ينفي الاستكبار؛ فاشتد ترابط الأمر والنهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص38، تحت عنوان «بلاغة الطرد والعكس»","url":""}]},{"id":"s27-110","number":110,"surah":27,"verses":[31],"references":[{"surah":27,"verses":[31]}],"verseLabel":"النمل: 31","question":"لماذا قُدِّم النهي عن العلو على طلب الإسلام؟","answer":"لأن الاستكبار أصل الطغيان والكفر وحاجز عن قبول الحق، فقدم إزالة المانع قبل طلب فعل الإسلام والانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص38، تحت عنوان «سر تقديم النهي عن العلو على طلب الإسلام»","url":""}]},{"id":"s27-38","number":38,"surah":27,"verses":[32],"references":[{"surah":27,"verses":[32]}],"verseLabel":"النمل: 32","question":"ما دلالة التعبير بفعل الكون ماضيًا في قول ملكة سبأ: ﴿مَا كُنْتُ قَاطِعَةً أَمْرًا﴾؟","answer":"دل على أن المشاورة عادة مستقرة لها في تدبير الملك، لا جوابًا عارضًا لهذه الحادثة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص45، تحت عنوان «دلالة التعبير بفعل الكون ماضيا»","url":""}]},{"id":"s27-111","number":111,"surah":27,"verses":[32],"references":[{"surah":27,"verses":[32]}],"verseLabel":"النمل: 32","question":"ما نكتة التعبير باسم الفاعل ﴿قَاطِعَةً﴾؟","answer":"أفاد الثبوت والاستمرار؛ فهي لا تتصف بحسم أمر ذي شأن دون مشورة أهل الرأي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص46، تحت عنوان «نكتة التعبير باسم الفاعل في ﴿قاطعة﴾»","url":""}]},{"id":"s27-112","number":112,"surah":27,"verses":[32],"references":[{"surah":27,"verses":[32]}],"verseLabel":"النمل: 32","question":"ما غرض إخبار ملكة سبأ قومها بقولها: ﴿مَا كُنْتُ قَاطِعَةً أَمْرًا حَتَّى تَشْهَدُونِ﴾؟","answer":"أرادت استرضاءهم واستطلاع آرائهم، واستمالة قلوبهم ليشاركوها الرأي والتدبير ويؤازروها فيما يستقر عليه القرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص47، تحت عنوان «غرض الإخبار بقولها: ﴿ما كنت قاطعة أمرا حتى تشهدون﴾»","url":""}]},{"id":"s27-39","number":39,"surah":27,"verses":[34],"references":[{"surah":27,"verses":[34]}],"verseLabel":"النمل: 34","question":"ما علة فصل قولها: ﴿إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا﴾ عما قبله؟","answer":"استؤنف جوابًا عن سؤال مقدر بشأن رأيها في القتال، وتعليلًا لعدولها عن الحرب إلى المسالمة بما تعرفه من عواقب دخول الملوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص56، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s27-113","number":113,"surah":27,"verses":[34],"references":[{"surah":27,"verses":[34]}],"verseLabel":"النمل: 34","question":"ما غرض توكيد قولها: ﴿إِنَّ الْمُلُوكَ إِذَا دَخَلُوا قَرْيَةً أَفْسَدُوهَا﴾ بـ﴿إِنَّ﴾؟","answer":"أكدت الخبر لأن قومها كانوا ميالين إلى الحرب، فواجهت ترددهم بما تقرر من طباع الملوك واستدلت بشواهد التاريخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص56–57، تحت عنوان «غرض التوكيد بـ﴿إن﴾»","url":""}]},{"id":"s27-114","number":114,"surah":27,"verses":[34],"references":[{"surah":27,"verses":[34]}],"verseLabel":"النمل: 34","question":"ما علة تعريف ﴿الْمُلُوكَ﴾ وجمعه؟","answer":"أفاد الجمع المعرف استغراق جنس الملوك، وأن الإفساد والإذلال شأن عام في دخولهم القهري، وفي ذلك تقوية لتحذيرها من مواجهة سليمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص57، تحت عنوان «علة تعريف ﴿الملوك﴾ وجمعه»","url":""}]},{"id":"s27-40","number":40,"surah":27,"verses":[35],"references":[{"surah":27,"verses":[35]}],"verseLabel":"النمل: 35","question":"ما فائدة العطف في قول ملكة سبأ: ﴿وَإِنِّي مُرْسِلَةٌ إِلَيْهِمْ بِهَدِيَّةٍ﴾؟","answer":"عطف إرسال الهدية على ما قررته من خطر الحرب، فدل على أنها بنت المصانعة والمسالمة على تقديرها لعواقب دخول الملوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص63، تحت عنوان «فائدة العطف في جملة ﴿وإني مرسلة﴾»","url":""}]},{"id":"s27-115","number":115,"surah":27,"verses":[35],"references":[{"surah":27,"verses":[35]}],"verseLabel":"النمل: 35","question":"لماذا لم تستشر ملكة سبأ قومها في إرسال الهدية؟","answer":"لأنهم أبدوا ميلهم إلى الحرب وفوضوا إليها الرأي، فاختارت بنفسها طريق الملاينة لتختبر سليمان من غير أن تعيد سؤالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص65، تحت عنوان «علة عدم استشارة بلقيس قومها في إرسال الهدية»","url":""}]},{"id":"s27-116","number":116,"surah":27,"verses":[35],"references":[{"surah":27,"verses":[35]}],"verseLabel":"النمل: 35","question":"ما دلالة الفاء في قولها: ﴿فَنَاظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ﴾؟","answer":"رتبت انتظار جواب الرسل على إرسال الهدية، وصورت ترقبها لما يكشفه الرد عن موقف سليمان وحقيقة دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص65، تحت عنوان «دلالة العطف بالفاء في ﴿فناظرة﴾»","url":""}]},{"id":"s27-41","number":41,"surah":27,"verses":[36],"references":[{"surah":27,"verses":[36]}],"verseLabel":"النمل: 36","question":"ما سرّ إظهار اسم ﴿سُلَيْمَانَ﴾ في قوله ﴿فَلَمَّا جَاءَ سُلَيْمَانَ﴾؟","answer":"أُظهر اسم سليمان ليحدد من جاءه الرسول ويبرز مقامه بما عرف عنه من الملك والنبوة؛ فيزداد استنكار أن يعرض عليه مال ليستمال به، وهو من آتاه الله ما يفوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص71، تحت عنوان «نكتة إظهار ﴿سليمان﴾ دون إضماره»","url":""}]},{"id":"s27-42","number":42,"surah":27,"verses":[36],"references":[{"surah":27,"verses":[36]}],"verseLabel":"النمل: 36","question":"ما بلاغة اختيار لفظ ﴿مَالٍ﴾ دون «هدية» في قول سليمان؟","answer":"سمّى الهدية مالًا ليكشف حقيقتها المادية ويحقّر شأنها في مقام الدعوة، وليبين أن المال لا يستميله ولا يصرفه عن رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص72–73، تحت عنوان «بلاغة اختيار مفردة (مال) دون (هدية)»","url":""}]},{"id":"s27-117","number":117,"surah":27,"verses":[36],"references":[{"surah":27,"verses":[36]}],"verseLabel":"النمل: 36","question":"ما دلالة الفاء في قوله: ﴿فَمَا آتَانِيَ اللَّهُ خَيْرٌ مِمَّا آتَاكُمْ﴾؟","answer":"جاءت الفاء معللة لإنكار إمداده بالمال؛ فما آتاه الله من النبوة والملك والفضل خير من هديتهم، ولذلك لا يقبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص73، تحت عنوان «دلالة الفاء في قوله: ﴿فما آتاني الله﴾»","url":""}]},{"id":"s27-43","number":43,"surah":27,"verses":[36],"references":[{"surah":27,"verses":[36]}],"verseLabel":"النمل: 36","question":"ما سر الإضراب بـ﴿بَلْ﴾ في قوله: ﴿بَلْ أَنْتُمْ بِهَدِيَّتِكُمْ تَفْرَحُونَ﴾؟","answer":"انتقل من إنكار إمداده بالمال إلى توبيخهم واحتقار ما يملكون، وبيّن أن سبب حملهم الهدية هو فرحهم بالدنيا التي لا يعلمون غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص75، تحت عنوان «سر الإضراب بالأداة ﴿بل﴾»","url":""}]},{"id":"s27-118","number":118,"surah":27,"verses":[36],"references":[{"surah":27,"verses":[36]}],"verseLabel":"النمل: 36","question":"ما غرض تقديم ﴿بِهَدِيَّتِكُمْ﴾ على ﴿تَفْرَحُونَ﴾؟","answer":"أفاد القصر والسخرية: أنتم الذين يختص فرحكم بالهدايا والأموال الفانية، أما سليمان فغناه وفضله من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص77، تحت عنوان «غرض تقديم ﴿بهديتكم﴾ على المسند الفعلي»","url":""}]},{"id":"s27-44","number":44,"surah":27,"verses":[37],"references":[{"surah":27,"verses":[37]}],"verseLabel":"النمل: 37","question":"ما سرّ تعدية ﴿ارْجِعْ﴾ بـ﴿إِلَيْهِمْ﴾؟","answer":"تفيد «إلى» انتهاء غاية الرجوع، أي عُد إلى بلقيس وقومها. ولم يُعدل إلى اللام، لأنها تفيد التعليل، وليس المقصود الرجوع لأجلهم بل الرجوع إلى جهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص78، تحت عنوان «فائدة استعمال (إلى) دون اللام»","url":""}]},{"id":"s27-45","number":45,"surah":27,"verses":[37],"references":[{"surah":27,"verses":[37]}],"verseLabel":"النمل: 37","question":"لماذا عبّر سليمان بالإخراج دون الهزيمة؟","answer":"لأن الإخراج أبلغ؛ فالهزيمة قد تبقي القوم في بلادهم، أما الإخراج فيقتضي زوال سلطانهم ومفارقة أوطانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص81، تحت عنوان «نكتة استعمال (الإخراج) دون (الهزيمة)»","url":""}]},{"id":"s27-119","number":119,"surah":27,"verses":[37],"references":[{"surah":27,"verses":[37]}],"verseLabel":"النمل: 37","question":"ما بلاغة مجيء ﴿وَهُمْ صَاغِرُونَ﴾ حالًا جملة بعد ﴿أَذِلَّةً﴾ حالًا مفردة؟","answer":"دل الترتيب على أن ذلهم ليس عارضًا عند الإخراج فقط، بل يصاحبه صغار وقهر وانهيار دائم لأسباب القوة والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص82، تحت عنوان «بلاغة الحال جملة بعد الحال مفردة»","url":""}]},{"id":"s27-120","number":120,"surah":27,"verses":[37],"references":[{"surah":27,"verses":[37]}],"verseLabel":"النمل: 37","question":"ما دلالة استعمال اسم الفاعل ﴿صَاغِرُونَ﴾؟","answer":"صوّر الصغار صفة ثابتة متمكنة منهم، توكيدًا أن هزيمتهم ليست حالًا عابرة لا تلبث أن تزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص83، تحت عنوان «دلالة استعمال اسم الفاعل ﴿صاغرون﴾»","url":""}]},{"id":"s27-46","number":46,"surah":27,"verses":[38],"references":[{"surah":27,"verses":[38]}],"verseLabel":"النمل: 38","question":"لماذا طلب سليمان عرشها قبل أن يأتوه مسلمين؟","answer":"أراد إحضار العرش قبل وصولها ليعاين القوم ما أقدره الله عليه، فتكون الآية أوقع في نفوسهم وأدعى إلى الإيمان. وذُكر أيضًا أنه اختبار لصدق خبر الهدهد ولعقل الملكة حين ترى عرشها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص90، تحت عنوان «نكتة ذكر الظرف ﴿قبل﴾»","url":""}]},{"id":"s27-47","number":47,"surah":27,"verses":[39],"references":[{"surah":27,"verses":[39]}],"verseLabel":"النمل: 39","question":"ما بلاغة استعمال ﴿تَقُومَ﴾ دون «تغادر» في قول العفريت؟","answer":"صوّر سرعة الإتيان بالعرش؛ فالقيام يسبق مغادرة مجلس الحكم، فكأنه يحضره قبل أول حركة للانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص93، تحت عنوان «بلاغة استعمال ﴿تقوم﴾ دون (تغادر)»","url":""}]},{"id":"s27-121","number":121,"surah":27,"verses":[39],"references":[{"surah":27,"verses":[39]}],"verseLabel":"النمل: 39","question":"ما نكتة التعبير بـ﴿مَقَامِكَ﴾ دون العرش أو الكرسي؟","answer":"المقام هو مجلس الحكم المعتاد، فقيّد الوعد بزمن معلوم ينتهي بانقضاء المجلس، لا بمجرد مفارقة مقعد قد يقوم عنه أثناءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص94، تحت عنوان «نكتة التعبير بالمقام دون العرش أو الكرسي»","url":""}]},{"id":"s27-48","number":48,"surah":27,"verses":[40],"references":[{"surah":27,"verses":[40]}],"verseLabel":"النمل: 40","question":"ما نكتة التعبير بـ﴿يَرْتَدَّ﴾ دون «يرجع» في قوله: ﴿قَبْلَ أَنْ يَرْتَدَّ إِلَيْكَ طَرْفُكَ﴾؟","answer":"الارتداد رجوع سريع إلى الجهة الأولى، فصوّر قصر الزمن بين إرسال البصر وعودته تصويرًا أدق من مطلق الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص97، تحت عنوان «نكتة التعبير بلفظ ﴿يرتد﴾ دون (يرجع)»","url":""}]},{"id":"s27-122","number":122,"surah":27,"verses":[40],"references":[{"surah":27,"verses":[40]}],"verseLabel":"النمل: 40","question":"ما بلاغة الكناية في ارتداد الطرف؟","answer":"كُني بزمن ارتداد البصر عن سرعة خارقة في إحضار العرش؛ فالشيء يحضر قبل أن يعود طرف سليمان إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص98، تحت عنوان «بلاغة الكناية في ارتداد الطرف»","url":""}]},{"id":"s27-123","number":123,"surah":27,"verses":[40],"references":[{"surah":27,"verses":[40]}],"verseLabel":"النمل: 40","question":"ما بلاغة المقابلة بين عرض العفريت وعرض الذي عنده علم؟","answer":"قابل قوة العفريت بعلم صاحب الكتاب؛ فكان عرض العفريت سريعًا، لكن العلم حقق ما هو أسرع، إظهارًا لفضل العلم ونعمة الله على سليمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص97، تحت عنوان «بلاغة المقابلة بين (العفريت) و(ذي العلم)»","url":""}]},{"id":"s27-49","number":49,"surah":27,"verses":[40],"references":[{"surah":27,"verses":[40]}],"verseLabel":"النمل: 40","question":"ما دلالة التعبير بفعل القول في قوله: ﴿قَالَ هَذَا مِنْ فَضْلِ رَبِّي﴾؟","answer":"حكى القول ليظهر أن سليمان بادر إلى إعلان الشكر عند رؤية العرش، ولم ينسب الخارق إلى نفسه أو قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص100، تحت عنوان «دلالة التعبير بفعل القول ﴿قال﴾»","url":""}]},{"id":"s27-124","number":124,"surah":27,"verses":[40],"references":[{"surah":27,"verses":[40]}],"verseLabel":"النمل: 40","question":"ما بلاغة اختيار لفظ ﴿فَضْلِ﴾ دون «نعمة»؟","answer":"الفضل إحسان زائد غير مستحق، فاعترف سليمان أن إحضار العرش منحة محضة من ربه لا عمل له يوجبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص101، تحت عنوان «بلاغة اختيار لفظ ﴿فضل﴾ دون (نعمة)»","url":""}]},{"id":"s27-125","number":125,"surah":27,"verses":[40],"references":[{"surah":27,"verses":[40]}],"verseLabel":"النمل: 40","question":"ما دلالة اللام في قوله: ﴿لِيَبْلُوَنِي﴾؟","answer":"هي لام التعليل؛ فبيّن أن الفضل ابتلاء وتمحيص ليظهر شكره أو كفره، لا مجرد تمكين بلا مسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص101–102، تحت عنوان «دلالة (اللام) في قوله ﴿ليبلوني﴾»","url":""}]},{"id":"s27-50","number":50,"surah":27,"verses":[41],"references":[{"surah":27,"verses":[41]}],"verseLabel":"النمل: 41","question":"ما دلالة التعبير بالتنكير في قوله: ﴿نَكِّرُوا لَهَا عَرْشَهَا﴾؟","answer":"أمر بتغيير بعض هيئة العرش مع بقاء معالمه، ليختبر ذكاء الملكة ودقة معرفتها به دون أن يصير مجهولًا تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص112، تحت عنوان «دلالة التعبير بالتنكير»","url":""}]},{"id":"s27-126","number":126,"surah":27,"verses":[41],"references":[{"surah":27,"verses":[41]}],"verseLabel":"النمل: 41","question":"ما غرض الاستفهام في قوله: ﴿أَتَهْتَدِي﴾؟","answer":"الاستفهام للاختبار: أيُظهر تغيير العرش قدرتها على معرفته وحسن اهتدائها، أم تكون ممن لا يهتدون؟","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص113، تحت عنوان «غرض الاستفهام في قوله تعالى: ﴿أتهتدي﴾»","url":""}]},{"id":"s27-51","number":51,"surah":27,"verses":[42],"references":[{"surah":27,"verses":[42]}],"verseLabel":"النمل: 42","question":"ما سرّ قول ملكة سبأ ﴿كَأَنَّهُ هُوَ﴾ دون جزم؟","answer":"جمعت قوة الشبه واستبعاد انتقاله، فكان جوابها احترازًا ذكيًا لا إنكارًا ولا تهورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص116، تحت عنوان «بلاغة الرد في استعمال كاف التشبيه: ﴿كأنه﴾»","url":""}]},{"id":"s27-52","number":52,"surah":27,"verses":[44],"references":[{"surah":27,"verses":[44]}],"verseLabel":"النمل: 44","question":"ما وجه عطف كشف الساقين على حسبان الصرح لجة؟","answer":"جعله نتيجة مباشرة للحسبان؛ فلما ظنت الصرح ماءً عميقًا كشفت عن ساقيها لتخوضه ولا يبتل ثوبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص123، تحت عنوان «وجه عطف الكشف عن الساقين على الحسبان»","url":""}]},{"id":"s27-127","number":127,"surah":27,"verses":[44],"references":[{"surah":27,"verses":[44]}],"verseLabel":"النمل: 44","question":"ما بلاغة وصف الصرح بقوله: ﴿مُمَرَّدٌ﴾؟","answer":"دل الوصف على شدة ملاسته وصفائه بسبب إحكام بنائه، حتى خُيّل للناظر أنه ماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص125، تحت عنوان «بلاغة الوصف بقوله: ﴿ممرد﴾»","url":""}]},{"id":"s27-128","number":128,"surah":27,"verses":[44],"references":[{"surah":27,"verses":[44]}],"verseLabel":"النمل: 44","question":"ما بلاغة اختيار مفردة ﴿قَوَارِيرَ﴾؟","answer":"دل الجمع على أن الصرح مؤلف من قطع زجاج كثيرة شديدة الصفاء، متناسقة حتى تبدو كأنها ماء ممتد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص126، تحت عنوان «بلاغة اختيار مفردة ﴿قوارير﴾»","url":""}]},{"id":"s27-53","number":53,"surah":27,"verses":[44],"references":[{"surah":27,"verses":[44]}],"verseLabel":"النمل: 44","question":"ما براعة عطف ﴿وَأَسْلَمْتُ﴾ على اعتراف ملكة سبأ بالظلم؟","answer":"رتب إعلان الإسلام على الاعتراف بظلم النفس، فجمع التخلي عن الشرك والتحلي بالإيمان واتباع الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص127–128، تحت عنوان «براعة عطف ﴿وأسلمت﴾، على الاعتراف بالظلم»","url":""}]},{"id":"s27-129","number":129,"surah":27,"verses":[44],"references":[{"surah":27,"verses":[44]}],"verseLabel":"النمل: 44","question":"ما نكتة ذكر المعية في قولها: ﴿مَعَ سُلَيْمَانَ﴾؟","answer":"أقرت بفضل سليمان واعترفت بأنها اقتدت بدعوته ومنهجه، لا أنها أسلمت مستقلة عن البلاغ الذي وصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص128، تحت عنوان «نكتة ذكر المعية في قولها: ﴿مع سليمان﴾»","url":""}]},{"id":"s27-130","number":130,"surah":27,"verses":[44],"references":[{"surah":27,"verses":[44]}],"verseLabel":"النمل: 44","question":"ما نكتة تقديم ﴿مَعَ سُلَيْمَانَ﴾ على ﴿لِلَّهِ﴾ في السياق؟","answer":"قدّم ذكر المتبوع لبيان الدين الذي اتبعته، ثم صرحت بأن مقصد الإسلام لله رب العالمين وحده، فجمع الاتباع والإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص128، تحت عنوان «نكتة تقديم ﴿مع سليمان﴾ في السياق»","url":""}]},{"id":"s27-54","number":54,"surah":27,"verses":[45],"references":[{"surah":27,"verses":[45]}],"verseLabel":"النمل: 45","question":"ما سر تخصيص ثمود بالذكر بعد قصة سليمان وملكة سبأ في سورة النمل؟","answer":"ناسب ذكر ثمود سياقَ الآيات التي آتى الله بها رسله واختلاف مواقف الناس منها: فملكة سبأ رأت ما أُوتي سليمان فآمنت، وثمود جاءتهم الناقة فكانوا بين مؤمن وكافر. كما أن ديار ثمود على طريق تجارة قريش إلى الشام، فكان في قصتهم عبرة قريبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص133–134، تحت عنوان «سر تخصيص ذكر ثمود دون عاد في قوله: ﴿إلى ثمود﴾»","url":""}]},{"id":"s27-55","number":55,"surah":27,"verses":[46],"references":[{"surah":27,"verses":[46]}],"verseLabel":"النمل: 46","question":"ما بلاغة الاستفهام في قوله: ﴿لِمَ تَسْتَعْجِلُونَ بِالسَّيِّئَةِ﴾؟","answer":"أنكر عليهم استعجال العذاب ووبخهم على رفض الآيات، مع إظهار حرص النبي عليهم ودعوتهم إلى النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص148، تحت عنوان «بلاغة الاستفهام في قوله: ﴿لم﴾»","url":""}]},{"id":"s27-131","number":131,"surah":27,"verses":[46],"references":[{"surah":27,"verses":[46]}],"verseLabel":"النمل: 46","question":"ما نكتة التعبير بالسيئة عن العذاب وبالحسنة عن التوبة؟","answer":"سمى العذاب سيئة باعتبار ما يسوءهم، وسمى التوبة حسنة لما تجلبه من مغفرة ورحمة؛ فبرز قبح اختيارهم وجمال الطريق المعروض عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص151، تحت عنوان «نكتة التعبير بالسيئة عن العذاب وبالحسنة عن التوبة»","url":""}]},{"id":"s27-132","number":132,"surah":27,"verses":[46],"references":[{"surah":27,"verses":[46]}],"verseLabel":"النمل: 46","question":"لماذا خُص الاستغفار بالذكر في قوله: ﴿لَوْلَا تَسْتَغْفِرُونَ﴾؟","answer":"لأنه أصل طلب المغفرة وعلامة صدق التوبة والإيمان، فيجمع رجوع القلب وطلب محو الذنب قبل نزول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص154، تحت عنوان «سر تخصيص الاستغفار بالذكر في قوله: ﴿لولا تستغفرون﴾»","url":""}]},{"id":"s27-56","number":56,"surah":27,"verses":[47],"references":[{"surah":27,"verses":[47]}],"verseLabel":"النمل: 47","question":"ما دلالة نسبة قوم ثمود الطيرة إلى صالح ومن معه؟","answer":"حمّلوهم سبب ما نزل من شدة تشاؤمًا بدعوتهم، بدل أن يردوا البلاء إلى كفرهم وابتلائهم؛ ففضح التعبير خرافتهم ووهمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص161–162، تحت عنوان «دلالة نسبة قوم ثمود الطيرة إلى نبيهم»","url":""}]},{"id":"s27-57","number":57,"surah":27,"verses":[48],"references":[{"surah":27,"verses":[48]}],"verseLabel":"النمل: 48","question":"ما بلاغة التتميم في قوله: ﴿وَلَا يُصْلِحُونَ﴾ بعد وصفهم بالإفساد؟","answer":"قطع احتمال أن يخلطوا فسادهم بشيء من الإصلاح؛ فنفى عنهم الصلاح في كل حال وقرر أن الإفساد طبع مستمر فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص177، تحت عنوان «بلاغة التتميم في قوله: ﴿ولا يصلحون﴾»","url":""}]},{"id":"s27-58","number":58,"surah":27,"verses":[49],"references":[{"surah":27,"verses":[49]}],"verseLabel":"النمل: 49","question":"ما دلالة صيغة ﴿تَقَاسَمُوا﴾؟","answer":"تفيد المشاركة الجماعية؛ أمر بعضهم بعضًا بالقسم أو أقسموا جميعًا، فصوّرت اجتماعهم وتواطؤهم على المكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص181–182، تحت عنوان «دلالة التعبير بـ﴿تقاسموا﴾ صيغة»","url":""}]},{"id":"s27-133","number":133,"surah":27,"verses":[49],"references":[{"surah":27,"verses":[49]}],"verseLabel":"النمل: 49","question":"ما دلالة متعلق القسم ﴿بِاللَّهِ﴾ مع كون المتآمرين مشركين؟","answer":"دل على أنهم كانوا يعرفون الله ويحلفون به عند الشدائد، مع إشراكهم به في العبادة؛ ففضح تناقضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص182–183، تحت عنوان «دلالة التعبير بمتعلق القسم ﴿بالله﴾»","url":""}]},{"id":"s27-59","number":59,"surah":27,"verses":[51],"references":[{"surah":27,"verses":[51]}],"verseLabel":"النمل: 51","question":"ما دلالة إضافة العاقبة إلى مكرهم؟","answer":"نصت على أن سوء العاقبة كان ثمرة مكرهم نفسه، وفيها تحذير خفي من السبب الذي يقود إلى ذلك المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص207، تحت عنوان «دلالة الإضافة في قوله: ﴿عاقبة مكرهم﴾»","url":""}]},{"id":"s27-60","number":60,"surah":27,"verses":[52],"references":[{"surah":27,"verses":[52]}],"verseLabel":"النمل: 52","question":"ما دلالة اسم الإشارة ﴿تِلْكَ﴾ في قوله: ﴿فَتِلْكَ بُيُوتُهُمْ﴾؟","answer":"أشار بالبعيد إلى منازل شاخصة عظيمة كانت حصونًا آمنة ثم خلت من أهلها، تنبيهًا على فظاعة العاقبة والاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص216، تحت عنوان «دلالة التعبير بالإشارة (تلك)»","url":""}]},{"id":"s27-134","number":134,"surah":27,"verses":[52],"references":[{"surah":27,"verses":[52]}],"verseLabel":"النمل: 52","question":"ما سر وصف بيوت ثمود بقوله: ﴿خَاوِيَةً﴾؟","answer":"الخواء أبلغ من مجرد الخلو؛ إذ يصور البيوت خالية ساقطة متهدمة بعد شدة بنائها، فغدت آية على تمام الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص217–218، تحت عنوان «سر التعبير بقوله: ﴿خاوية﴾»","url":""}]},{"id":"s27-135","number":135,"surah":27,"verses":[52],"references":[{"surah":27,"verses":[52]}],"verseLabel":"النمل: 52","question":"ما دلالة الباء في قوله: ﴿بِمَا ظَلَمُوا﴾؟","answer":"هي للسببية؛ جعل ظلمهم مصدر خراب بيوتهم وهلاكهم، فدل على إقامة الحجة وعدل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص218، تحت عنوان «دلالة الباء في قوله: ﴿بما﴾»","url":""}]},{"id":"s27-61","number":61,"surah":27,"verses":[54],"references":[{"surah":27,"verses":[54]}],"verseLabel":"النمل: 54","question":"ما دلالة الجملة الحالية ﴿وَأَنْتُمْ تُبْصِرُونَ﴾؟","answer":"شددت الإنكار لأنهم يأتون الفاحشة عن علم ومشاهدة، لا عن خفاء، فجمع الفعل القبيح مع قيام البصيرة والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص237–238، تحت عنوان «دلالة التعبير بجملة: ﴿وأنتم تبصرون﴾»","url":""}]},{"id":"s27-136","number":136,"surah":27,"verses":[54],"references":[{"surah":27,"verses":[54]}],"verseLabel":"النمل: 54","question":"ما بلاغة التعبير بالبصر في قوله: ﴿تُبْصِرُونَ﴾؟","answer":"يحتمل بصيرة القلب ورؤية قبح الفعل وعاقبته، ويحتمل إبصار بعضهم بعضًا عند ارتكابه؛ وفي الوجهين تشتد الفاحشة والجرأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص238–239، تحت عنوان «بلاغة التعبير بـ(البصر) في قوله: ﴿تبصرون﴾»","url":""}]},{"id":"s27-62","number":62,"surah":27,"verses":[55],"references":[{"surah":27,"verses":[55]}],"verseLabel":"النمل: 55","question":"ما دلالة الخطاب المباشر في قوله: ﴿تَجْهَلُونَ﴾؟","answer":"نقلهم من الغيبة إلى المواجهة، فكان أصرح في التوبيخ وأشد تأثيرًا بعد قيام الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص246، تحت عنوان «دلالة الخطاب في قوله: ﴿تجهلون﴾»","url":""}]},{"id":"s27-63","number":63,"surah":27,"verses":[59],"references":[{"surah":27,"verses":[59]}],"verseLabel":"النمل: 59","question":"ما سر فصل جملة ﴿قُلِ الْحَمْدُ لِلَّهِ﴾ عما قبلها؟","answer":"استؤنفت بعد القصص لاستخلاص العبرة: حمد الله على نصر الرسل وإهلاك المكذبين وما أظهره من دلائل القدرة والوحدانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص274، تحت عنوان «سر فصل جملة ﴿قل الحمد لله﴾ عما قبلها»","url":""}]},{"id":"s27-137","number":137,"surah":27,"verses":[59],"references":[{"surah":27,"verses":[59]}],"verseLabel":"النمل: 59","question":"ما بلاغة عطف ﴿وَسَلَامٌ﴾ على الحمد؟","answer":"جعل السلام تابعًا للحمد ومظهرًا له؛ فبعد حمد الله على نصر رسله جاء الدعاء لهم بالسلام والتكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص275، تحت عنوان «بلاغة عطف لفظ ﴿وسلام﴾ في السياق»","url":""}]},{"id":"s27-138","number":138,"surah":27,"verses":[59],"references":[{"surah":27,"verses":[59]}],"verseLabel":"النمل: 59","question":"ما بلاغة الاستفهام في قوله: ﴿آللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ﴾؟","answer":"هو استفهام إنكاري إلزامي يقرر أن الله وحده خير، ويفضح جهل المشركين إذ لا وجه للموازنة بين الخالق ومعبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص277، تحت عنوان «بلاغة الاستفهام في الآية الكريمة»","url":""}]},{"id":"s27-64","number":64,"surah":27,"verses":[60],"references":[{"surah":27,"verses":[60]}],"verseLabel":"النمل: 60","question":"ما سرّ تكرار سؤال ﴿أَإِلَهٌ مَعَ اللَّهِ﴾ في براهين التوحيد؟","answer":"يتكرر الاستفهام الإنكاري عقب وجوه النعم والقدرة لتأكيد الوحدانية، وتجديد تنبيه السامع إلى أن كل دليل منها ينفي الشريك. وليس تكراره خاليًا من زيادة؛ فكل موضع يعقب برهانًا جديدًا، ويزيد التوبيخ ووضوح الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص332–333، تحت عنوان «فائدة تكرار قوله: ﴿أإله مع الله﴾»","url":""}]},{"id":"s27-65","number":65,"surah":27,"verses":[61],"references":[{"surah":27,"verses":[61]}],"verseLabel":"النمل: 61","question":"ما نكتة وصف الأرض بأنها ﴿قَرَارًا﴾؟","answer":"جعلها مهيأة مستقرة صالحة للإقامة والعمارة، مع أنها جرم متحرك؛ فالوصف يبرز نعمة التثبيت والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص291، تحت عنوان «نكتة وصف ﴿الأرض﴾ بكونها ﴿قرارا﴾»","url":""}]},{"id":"s27-66","number":66,"surah":27,"verses":[62],"references":[{"surah":27,"verses":[62]}],"verseLabel":"النمل: 62","question":"ما دلالة لفظ ﴿الْمُضْطَرَّ﴾ وأهميته في السياق؟","answer":"هو من بلغ شدة لا يجد معها ملجأ إلا الله؛ فذكره يصور انقطاع الأسباب وإخلاص الدعاء، ويقيم حجة محسوسة على استجابة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص304–305، تحت عنوان «دلالة لفظ ﴿المضطر﴾ وأهميته في السياق»","url":""}]},{"id":"s27-139","number":139,"surah":27,"verses":[62],"references":[{"surah":27,"verses":[62]}],"verseLabel":"النمل: 62","question":"ما بلاغة الاستفهام في قوله: ﴿أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ﴾؟","answer":"هو تقرير وإنكار لأن يجيب المضطر غير الله؛ حتى المشركون يتجهون إليه وحده عند الشدائد.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص304، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s27-67","number":67,"surah":27,"verses":[64],"references":[{"surah":27,"verses":[64]}],"verseLabel":"النمل: 64","question":"ما علة فصل قوله: ﴿قُلْ هَاتُوا بُرْهَانَكُمْ﴾ عما قبله؟","answer":"استؤنف جوابًا عن براهين التوحيد السابقة، متحديًا المشركين أن يأتوا بدليل يقابلها، فكشف عجزهم وبطلان دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص333، تحت عنوان «علة فصل قوله تعالى: ﴿قل هاتوا برهانكم﴾ عما قبله»","url":""}]},{"id":"s27-140","number":140,"surah":27,"verses":[64],"references":[{"surah":27,"verses":[64]}],"verseLabel":"النمل: 64","question":"ما دلالة الفعل ﴿هَاتُوا﴾؟","answer":"هو أمر يتضمن الإلزام والإلحاح والتحدي بالتقديم الفوري للبرهان، لا مجرد طلب لطيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص333–334، تحت عنوان «دلالة الفعل ﴿هاتوا﴾»","url":""}]},{"id":"s27-68","number":68,"surah":27,"verses":[65],"references":[{"surah":27,"verses":[65]}],"verseLabel":"النمل: 65","question":"ما بلاغة القصر في قوله: ﴿لَا يَعْلَمُ مَنْ فِي السَّمَاوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ﴾؟","answer":"قصر علم الغيب على الله بالنفي والاستثناء، فنفاه عن جميع الخلق وأبطل دعوى الكهان والمشركين أن لمعبوداتهم نصيبًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص342–343، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s27-69","number":69,"surah":27,"verses":[66],"references":[{"surah":27,"verses":[66]}],"verseLabel":"النمل: 66","question":"ما فائدة تكرار حرف ﴿بَلْ﴾ في وصف حال المكذبين بالآخرة؟","answer":"رتب انتقالًا تصاعديًا في ذمهم: من اضطراب علمهم بالآخرة، إلى الشك فيها، ثم إلى العمى عنها؛ فكل إضراب يكشف حالًا أشد من سابقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص355–356، تحت عنوان «فائدة تكرار حرف ﴿بل﴾»","url":""}]},{"id":"s27-141","number":141,"surah":27,"verses":[66],"references":[{"surah":27,"verses":[66]}],"verseLabel":"النمل: 66","question":"ما دلالة الإضراب الثالث بـ﴿بَلْ﴾ في قوله: ﴿بَلْ هُمْ مِنْهَا عَمُونَ﴾؟","answer":"نقل وصفهم من مجرد الشك إلى العمى الذي يعطل البصيرة عن دلائل الآخرة، فبلغ الغاية في بيان فساد عقولهم وقلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص356–357، تحت عنوان «دلالة الإضراب الثالث بـ﴿بل﴾»","url":""}]},{"id":"s27-70","number":70,"surah":27,"verses":[69],"references":[{"surah":27,"verses":[69]}],"verseLabel":"النمل: 69","question":"ما سرّ التعبير في النمل بـ﴿قُلْ سِيرُوا... فَانْظُرُوا﴾، وفي الأنعام بـ﴿ثُمَّ انْظُرُوا﴾؟","answer":"الفاء تفيد ترتيب النظر على بدء السير وتعقيبه به، أما ﴿ثم﴾ في الأنعام فتراعي تمام السير والتراخي، وناسبت كذلك سياق الأنعام المفصل في الحجج؛ وقد عرض مبحث النمل اللفظين والموضعين معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص378–379، تحت عنوان «العدول عن (ثم) إلى الفاء»","url":""}]},{"id":"s27-71","number":71,"surah":27,"verses":[70],"references":[{"surah":27,"verses":[70]}],"verseLabel":"النمل: 70","question":"ما الإعجاز البياني في الجمع بين الحزن والضيق في الآية؟","answer":"أزال عنه نوعي الألم: الحزن الباطن على فقد إيمانهم، والضيق الناشئ من مكرهم الخارجي؛ فاستوعبت التسلية ما يؤلمه من داخل نفسه وما يحيط به.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص391–392، تحت عنوان «الإعجاز البياني في الجمع بين الحزن والضيق في الآية»","url":""}]},{"id":"s27-142","number":142,"surah":27,"verses":[70],"references":[{"surah":27,"verses":[70]}],"verseLabel":"النمل: 70","question":"ما دلالة حرف الجر ﴿مِنْ﴾ في قوله: ﴿مِمَّا يَمْكُرُونَ﴾؟","answer":"أفاد التعليل؛ أي لا تكن في ضيق بسبب مكرهم ومحاولتهم الإضرار بك وبالدعوة، وفيه وعد ضمني بالحفظ والعصمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص392، تحت عنوان «دلالة حرف الجر (من)»","url":""}]},{"id":"s27-72","number":72,"surah":27,"verses":[71],"references":[{"surah":27,"verses":[71]}],"verseLabel":"النمل: 71","question":"ما نكتة التعبير باسم الإشارة في قولهم: ﴿مَتَى هَذَا الْوَعْدُ﴾؟","answer":"استحضروا العذاب الموعود كأنه حاضر معروف ثم أشاروا إليه استهزاءً واستبعادًا لوقوعه، فكشف التعبير تهكمهم وفساد عقولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص399، تحت عنوان «نكتة التعبير باسم الإشارة»","url":""}]},{"id":"s27-143","number":143,"surah":27,"verses":[71],"references":[{"surah":27,"verses":[71]}],"verseLabel":"النمل: 71","question":"ما دلالة ﴿أل﴾ في لفظ ﴿الْوَعْدُ﴾؟","answer":"هي للعهد العلمي؛ تشير إلى وعد العذاب الذي تكرر إنذارهم به وعرفوه، فليس سؤالهم عن أمر مجهول بل عن وعيد معهود أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص400، تحت عنوان «دلالة (أل) في لفظ ﴿الوعد﴾»","url":""}]},{"id":"s27-144","number":144,"surah":27,"verses":[71],"references":[{"surah":27,"verses":[71]}],"verseLabel":"النمل: 71","question":"ما نكتة التعبير بالمصدر ﴿الْوَعْدُ﴾ وإرادة الموعود به؟","answer":"أطلق المصدر على العذاب الموعود به مبالغة، فجعل تحقق الموعود كأنه نفس الوعد، ثم جاء سؤالهم إنكارًا واستبعادًا لذلك الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص400، تحت عنوان «نكتة التعبير بالمصدر ﴿الوعد﴾»","url":""}]},{"id":"s27-73","number":73,"surah":27,"verses":[72],"references":[{"surah":27,"verses":[72]}],"verseLabel":"النمل: 72","question":"ما فائدة التعبير بـ﴿عَسَى﴾ في الوعيد الإلهي؟","answer":"هي في كلام الله تفيد تحقق الوقوع لا مجرد الرجاء؛ فجاءت في صورة التلطف مع تهديد صادق قريب، وفيها تهكم بمن استعجل العذاب مكذبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص405، تحت عنوان «فائدة التعبير بـ﴿عسى﴾»","url":""}]},{"id":"s27-145","number":145,"surah":27,"verses":[72],"references":[{"surah":27,"verses":[72]}],"verseLabel":"النمل: 72","question":"ما سر التعبير بقوله: ﴿عَسَى أَنْ يَكُونَ رَدِفَ لَكُمْ﴾؟","answer":"ذكر الكون أولًا لإثبات حصول العذاب، ثم خصه بخبر ﴿ردف لكم﴾ الذي يصور لحاقه ودنوه، وجاءت اللام لتوكيد اختصاصهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص405–406، تحت عنوان «سر التعبير بـ﴿عسى أن يكون ردف لكم﴾»","url":""}]},{"id":"s27-74","number":74,"surah":27,"verses":[74],"references":[{"surah":27,"verses":[74]}],"verseLabel":"النمل: 74","question":"ما فائدة تقديم ما تكنه الصدور على ما يعلنون؟","answer":"قدم الخفي لأنه منشأ ما يظهر على الجوارح، ولأن العلم بما استتر في الصدور أدل على الإحاطة؛ فإذا علمه الله فعلمه بالمعلن أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص422، تحت عنوان «فائدة تقديم الكن على الإعلان»","url":""}]},{"id":"s27-75","number":75,"surah":27,"verses":[76],"references":[{"surah":27,"verses":[76]}],"verseLabel":"النمل: 76","question":"ما علة فصل قوله: ﴿إِنَّ هَذَا الْقُرْآنَ يَقُصُّ عَلَى بَنِي إِسْرَائِيلَ﴾ عما قبله؟","answer":"استؤنفت الآية انتقالًا من جدال المكذبين في البعث إلى دليل جديد على صدق الوحي: إخبار القرآن بما اختلف فيه بنو إسرائيل وبيان الحق فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص431–432، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s27-146","number":146,"surah":27,"verses":[76],"references":[{"surah":27,"verses":[76]}],"verseLabel":"النمل: 76","question":"ما سر اختيار الفعل ﴿يَقُصُّ﴾ مادة وصيغة؟","answer":"مادته تصور تتبع الخبر وسرده على وجه منظم يميز مواضع النزاع، وصيغته المضارعة تدل على تجدد بيان القرآن واستمراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص433، تحت عنوان «سر اختيار الفعل ﴿يقص﴾ مادة وصيغة»","url":""}]},{"id":"s27-147","number":147,"surah":27,"verses":[76],"references":[{"surah":27,"verses":[76]}],"verseLabel":"النمل: 76","question":"ما علة تخصيص ﴿بَنِي إِسْرَائِيلَ﴾ بالذكر؟","answer":"لكثرة اختلافهم وتفرقهم مع اجتماع أصل كتابهم ونسبهم، فجاء القرآن حاكمًا بينهم يبين أكثر ما تنازعوا فيه ويحذر من طريقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص434، تحت عنوان «علة تخصيص ﴿بني إسرائيل﴾ بالذكر»","url":""}]},{"id":"s27-76","number":76,"surah":27,"verses":[82],"references":[{"surah":27,"verses":[82]}],"verseLabel":"النمل: 82","question":"ما بلاغة الاكتفاء في قوله: ﴿وَقَعَ الْقَوْلُ عَلَيْهِمْ﴾؟","answer":"حذف المضاف واكتفى بالقول، والتقدير: وقع عليهم مضمون القول أو الوعيد بالعذاب؛ فحقق الإيجاز تهديدًا شاملًا وترك الموعود به على هوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص473، تحت عنوان «بلاغة الاكتفاء في قوله: ﴿وقع القول عليهم﴾»","url":""}]},{"id":"s27-148","number":148,"surah":27,"verses":[82],"references":[{"surah":27,"verses":[82]}],"verseLabel":"النمل: 82","question":"ما دلالة وصف الدابة بقوله: ﴿تُكَلِّمُهُمْ﴾؟","answer":"هيأ السامع لخارق عجيب: حيوان من غير جنس المتكلمين يخاطب الناس، وفي ذلك تهويل للآية وإذلال للمعرضين الذين لم ينتفعوا بكلام الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص475، تحت عنوان «دلالة وصف الدابة بـ﴿تكلمهم﴾»","url":""}]},{"id":"s27-149","number":149,"surah":27,"verses":[82],"references":[{"surah":27,"verses":[82]}],"verseLabel":"النمل: 82","question":"كيف تُوجَّه القراءات في قوله: ﴿أَنَّ النَّاسَ﴾؟","answer":"على فتح الهمزة يكون الكلام متعلقًا بتكليم الدابة: تخبرهم بأن الناس لم يوقنوا بالآيات، وعلى الكسر يكون مقول كلامها مستأنفًا؛ والقراءتان تبينان مضمون خطابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص477–478، تحت عنوان «توجيه القراءات في قوله: ﴿أن الناس﴾»","url":""}]},{"id":"s27-77","number":77,"surah":27,"verses":[83],"references":[{"surah":27,"verses":[83]}],"verseLabel":"النمل: 83","question":"ما دلالة الجملة الاسمية ﴿فَهُمْ يُوزَعُونَ﴾ في حشر المكذبين؟","answer":"أكدت ثبوت الوزع واتصافهم به حال الحشر، فكأن ضبطهم ومنعهم من التفرق وصف ملازم لهم في ذلك الموقف المهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص485، تحت عنوان «دلالة التعبير بالجملة الاسمية ﴿فهم يوزعون﴾»","url":""}]},{"id":"s27-78","number":78,"surah":27,"verses":[87],"references":[{"surah":27,"verses":[87]}],"verseLabel":"النمل: 87","question":"ما معنى ﴿مَنْ﴾ ودلالتها في قوله: ﴿فَفَزِعَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ﴾؟","answer":"هي اسم موصول للعقلاء يفيد العموم، فشمل الفزع جميع من في العالمين ودل على شدته التي لا يخرج منها إلا المستثنى بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص513، تحت عنوان «معنى ﴿من﴾ ودلالتها»","url":""}]},{"id":"s27-150","number":150,"surah":27,"verses":[87],"references":[{"surah":27,"verses":[87]}],"verseLabel":"النمل: 87","question":"ما دلالة تكرار الموصول ﴿مَنْ﴾ في الآية؟","answer":"أعاد ذكر أهل الأرض بعد أهل السماوات تهويلًا وتأكيدًا لشمول الحكم، وخص أهل الأرض بالذكر مرة ثانية لأنهم موضع الخطاب والتخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص513، تحت عنوان «دلالة تكرار الموصول (من)»","url":""}]},{"id":"s27-151","number":151,"surah":27,"verses":[87],"references":[{"surah":27,"verses":[87]}],"verseLabel":"النمل: 87","question":"ما دلالة إسناد المشيئة إلى الاسم الأحسن ﴿اللَّهُ﴾؟","answer":"أسند الاستثناء إلى الاسم الجامع لصفات الكمال ليدل على عظمة المشيئة ونفاذها؛ فلا يعصم من الفزع إلا من شاء الله بعلمه وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص514، تحت عنوان «دلالة إسناد المشيئة إلى الاسم الأحسن ﴿الله﴾»","url":""}]},{"id":"s27-79","number":79,"surah":27,"verses":[88],"references":[{"surah":27,"verses":[88]}],"verseLabel":"النمل: 88","question":"من المخاطب بقوله: ﴿وَتَرَى الْجِبَالَ﴾ وما أثر الخطاب؟","answer":"الخطاب للنبي ويصح أن يراد به كل من تتأتى منه الرؤية، فيستحضر المشهد للسامع كأنه يراه ويقف على قدرة الله في سير الجبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص520، تحت عنوان «تعيين المخاطب بـ﴿وترى﴾»","url":""}]},{"id":"s27-152","number":152,"surah":27,"verses":[88],"references":[{"surah":27,"verses":[88]}],"verseLabel":"النمل: 88","question":"ما دلالة الاستعارة في وصف الجبال بقوله: ﴿تَحْسَبُهَا جَامِدَةً﴾؟","answer":"استعير الجمود لظهورها في غاية الثبات، مع أنها تسير؛ فجمع التصوير بين ما يحسبه الناظر وحقيقة الحركة، وأبرز دقة صنع الله وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص521، تحت عنوان «دلالة الاستعارة في لفظ ﴿جامدة﴾»","url":""}]},{"id":"s27-153","number":153,"surah":27,"verses":[88],"references":[{"surah":27,"verses":[88]}],"verseLabel":"النمل: 88","question":"ما بلاغة تشبيه مرور الجبال بمر السحاب؟","answer":"شبه حركتها بالسحاب الذي يبدو للناظر مستقرًا وهو يسير، فقرّب اجتماع الضخامة مع السرعة وأظهر تحول الجبال في مشهد مهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص521–522، تحت عنوان «بلاغة التشبيه في قوله: ﴿مر السحاب﴾»","url":""}]},{"id":"s27-80","number":80,"surah":27,"verses":[89],"references":[{"surah":27,"verses":[89]}],"verseLabel":"النمل: 89","question":"ما دلالة صيغة ﴿خَيْرٌ﴾ بين التفضيل والمبالغة في قوله: ﴿فَلَهُ خَيْرٌ مِنْهَا﴾؟","answer":"إن حملت على التفضيل كان الثواب خيرًا من الحسنة لما فيه من المضاعفة والدوام، وإن حملت على الوصف دلت على خير عظيم حاصل بسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص532–533، تحت عنوان «صيغة ﴿خير﴾ بين التفضيل والمبالغة»","url":""}]},{"id":"s27-154","number":154,"surah":27,"verses":[89],"references":[{"surah":27,"verses":[89]}],"verseLabel":"النمل: 89","question":"ما نوع ﴿مِنْ﴾ ودلالتها في قوله: ﴿خَيْرٌ مِنْهَا﴾؟","answer":"على كون ﴿خير﴾ اسم تفضيل تكون ﴿من﴾ داخلة على المفضّل عليه، وعلى كونها صفة مشبهة تحتمل ابتداء الغاية أو السببية، أي خير ناشئ من الحسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص533، تحت عنوان «نوع (من) ودلالتها»","url":""}]},{"id":"s27-155","number":155,"surah":27,"verses":[89],"references":[{"surah":27,"verses":[89]}],"verseLabel":"النمل: 89","question":"ما نوع الواو ودلالتها في قوله: ﴿وَهُمْ مِنْ فَزَعٍ يَوْمَئِذٍ آمِنُونَ﴾؟","answer":"هي للعطف، ويحتمل الاستئناف؛ وجمعت إلى ثواب الحسنة نعمةً أخرى هي الأمن من فزع القيامة، فتكامل الجزاء والطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص534، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s27-81","number":81,"surah":27,"verses":[90],"references":[{"surah":27,"verses":[90]}],"verseLabel":"النمل: 90","question":"ما نكتة التعبير بصيغة المبني للمفعول في قوله: ﴿فَكُبَّتْ وُجُوهُهُمْ فِي النَّارِ﴾؟","answer":"سلطت الصيغة النظر على سرعة حركة الكب وهولها، وأغفلت الفاعل لأن المقام مقام تصوير المصير، ولأن احتمالات من يتولى الكب تزيد المشهد تخويفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص542، تحت عنوان «نكتة التعبير بصيغة المبني للمفعول»","url":""}]},{"id":"s27-82","number":82,"surah":27,"verses":[91],"references":[{"surah":27,"verses":[91]}],"verseLabel":"النمل: 91","question":"ما توجيه تخصيص ﴿هَذِهِ الْبَلْدَةِ﴾ بالذكر؟","answer":"خص مكة لأنها أحب البلاد وأشرفها ولأن الله أمّن أهلها وحرمها؛ فتذكير قريش بهذه النعمة يعرض ببطلان شركهم ويلزمهم بعبادة ربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص558، تحت عنوان «توجيه تخصيص البلدة بالذكر»","url":""}]},{"id":"s27-156","number":156,"surah":27,"verses":[91],"references":[{"surah":27,"verses":[91]}],"verseLabel":"النمل: 91","question":"ما فائدة نعت رب البلدة بالموصول في قوله: ﴿الَّذِي حَرَّمَهَا﴾؟","answer":"ربط حرمة مكة بالله وحده، فبيّن أن تقديسها وأمنها أثر من آثار ربوبيته، وذكّر بالأصل الذي بُنيت عليه بقية الأحكام والنعَم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص560–561، تحت عنوان «فائدة النعت بالموصول»","url":""}]},{"id":"s27-83","number":83,"surah":27,"verses":[92],"references":[{"surah":27,"verses":[92]}],"verseLabel":"النمل: 92","question":"ما فائدة استعمال مفردة التلاوة مادة وصيغة في قوله: ﴿وَأَنْ أَتْلُوَ الْقُرْآنَ﴾؟","answer":"مادة التلاوة تدل على القراءة والاتباع، وصيغة المضارع تفيد التجدد والاستمرار؛ فصورت وظيفة الرسول في تكرار إسماع الوحي ودعوة الناس إلى اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص567–568، تحت عنوان «فائدة استعمال مفردة التلاوة مادة وصيغة»","url":""}]},{"id":"s27-157","number":157,"surah":27,"verses":[92],"references":[{"surah":27,"verses":[92]}],"verseLabel":"النمل: 92","question":"ما نكتة التعبير بالقرآن دون الكتاب في قوله: ﴿وَأَنْ أَتْلُوَ الْقُرْآنَ﴾؟","answer":"ناسب اسم القرآن مقام التلاوة والإسماع لأنه مشتق من القراءة، أما الكتاب فيناسب جهة التدوين؛ فاختير اللفظ الموافق لوظيفة البلاغ الشفهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص568–569، تحت عنوان «نكتة التعبير بالقرآن دون الكتاب»","url":""}]},{"id":"s27-84","number":84,"surah":27,"verses":[93],"references":[{"surah":27,"verses":[93]}],"verseLabel":"النمل: 93","question":"ما غرض الإخبار في قوله: ﴿سَيُرِيكُمْ آيَاتِهِ﴾؟","answer":"جاء تهديدًا للمكذبين ووعدًا بأن يريهم الله من دلائل صدق رسوله ما يضطرهم إلى المعرفة، مع تثبيت النبي بأن العاقبة للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص580، تحت عنوان «غرض الإخبار بإراءة الآيات»","url":""}]},{"id":"s27-158","number":158,"surah":27,"verses":[93],"references":[{"surah":27,"verses":[93]}],"verseLabel":"النمل: 93","question":"ما نوع الفاء ودلالتها في قوله: ﴿فَتَعْرِفُونَهَا﴾؟","answer":"هي فاء العطف والتعقيب؛ رتبت المعرفة على رؤية الآيات بسرعة، فمتى ظهرت لهم تحققوا صدقها ولم يبق لهم عذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص581، تحت عنوان «نوع الفاء ودلالتها في ﴿فتعرفونها﴾»","url":""}]},{"id":"s27-85","number":85,"surah":27,"verses":[80],"references":[{"surah":27,"verses":[80]},{"surah":30,"verses":[52]}],"verseLabel":"النمل: 80؛ الروم: 52","question":"ما دلالة الفاء في قوله في الروم: ﴿فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَى﴾؟","answer":"فرعت نفي إسماعهم على ما سبق من اتباع الظالمين أهواءهم واستمرارهم في الكفر، ويصح أن تفصح عن شرط مقدر: إن شق عليك إعراضهم فإنهم كالموتى فلا تسمعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص512–513، تحت عنوان «دلالة التعبير بالفاء في قوله: ﴿فإنك لا تسمع﴾»","url":""}]},{"id":"s27-159","number":159,"surah":27,"verses":[80],"references":[{"surah":27,"verses":[80]},{"surah":30,"verses":[52]}],"verseLabel":"النمل: 80؛ الروم: 52","question":"ما علة فصل قوله في النمل: ﴿إِنَّكَ لَا تُسْمِعُ الْمَوْتَى﴾ عما قبله؟","answer":"جاء استئنافًا بيانيًا يجيب عن سبب إعراضهم مع وضوح الحق: لأن كفرهم طبع قلوبهم فصاروا بمنزلة الموتى الذين لا يسمعون الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص457، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s27-160","number":160,"surah":27,"verses":[80],"references":[{"surah":27,"verses":[80]},{"surah":30,"verses":[52]}],"verseLabel":"النمل: 80؛ الروم: 52","question":"ما دلالة ﴿إِنَّ﴾ في قوله: ﴿إِنَّكَ لَا تُسْمِعُ الْمَوْتَى﴾؟","answer":"أكدت ثبوت عجز البشر عن إسماع من ماتت قلوبهم، تسلية للنبي عن مسارعتهم إلى الكفر وتقريرًا أن الهداية ليست في قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص457–458، تحت عنوان «دلالة (إن) في الآية»","url":""}]},{"id":"s28-1","number":1,"surah":28,"verses":[2],"references":[{"surah":28,"verses":[2]}],"verseLabel":"القصص: 2","question":"لماذا أُشير إلى آيات القرآن باسم الإشارة للبعيد في ﴿تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ﴾؟","answer":"الإشارة بالبعيد لتعظيم شأن الآيات وبيان علو منزلتها وكمالها؛ فالبعد هنا بعد منزلة، وليس بُعد مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص600، تحت عنوان «بلاغة التعبير باسم الإشارة للبعيد»","url":""}]},{"id":"s28-110","number":110,"surah":28,"verses":[2],"references":[{"surah":28,"verses":[2]}],"verseLabel":"القصص: 2","question":"ما المعنيان اللذان يحتملهما وصف الكتاب بـ﴿الْمُبِينِ﴾؟","answer":"يحتمل أنه واضح في نفسه، ظاهر أنه من عند الله، وأنه مبيّن للحقائق وما يحتاج الناس إلى بيانه؛ فيجمع الوصف الوضوح والإيضاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص602، تحت عنوان «نكتة وصف ﴿الكتاب﴾ بـ﴿المبين﴾»","url":""}]},{"id":"s28-2","number":2,"surah":28,"verses":[3],"references":[{"surah":28,"verses":[3]}],"verseLabel":"القصص: 3","question":"لماذا اختير لفظ ﴿نَبَإِ﴾ دون «خبر» في قوله ﴿مِنْ نَبَإِ مُوسَى وَفِرْعَوْنَ﴾؟","answer":"لأن النبأ خبر عظيم الشأن والفائدة؛ فاختياره ينبه إلى أهمية ما سيُتلى من قصة موسى وفرعون، ويستدعي اليقظة والانتباه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص605، تحت عنوان «دلالة استعمال مفردة ﴿نبإ﴾»","url":""}]},{"id":"s28-107","number":107,"surah":28,"verses":[3],"references":[{"surah":28,"verses":[3]}],"verseLabel":"القصص: 3","question":"ما دلالة ﴿مِنْ﴾ في قوله ﴿مِنْ نَبَإِ مُوسَى وَفِرْعَوْنَ﴾؟","answer":"تحتمل «مِن» التبعيض؛ لأن المتلو في هذه السورة بعض أخبار موسى وفرعون. وتحتمل البيان، أي: نتلو عليك شيئًا من شأنهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص604–605، تحت عنوان «نوع ﴿من﴾ ودلالتها»","url":""}]},{"id":"s28-108","number":108,"surah":28,"verses":[3],"references":[{"surah":28,"verses":[3]}],"verseLabel":"القصص: 3","question":"لماذا خُصّ المؤمنون بالذكر في قوله ﴿لِقَوْمٍ يُؤْمِنُونَ﴾ مع عموم الهداية للناس؟","answer":"لأن المؤمنين أكثر انتفاعًا بما يُتلى من العبر والمواعظ؛ فإيمانهم يدعوهم إلى طلب العلم والاعتبار ليزدادوا يقينًا. فالتخصيص يبرز انتفاعهم، ولا ينفي عموم الهداية للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص607–608، تحت عنوان «توجيه تخصيص صفة المؤمنين بالذكر»","url":""}]},{"id":"s28-3","number":3,"surah":28,"verses":[4],"references":[{"surah":28,"verses":[4]}],"verseLabel":"القصص: 4","question":"ما سرّ إظهار اسم ﴿فِرْعَوْنَ﴾ بعد ذكره في الآية السابقة؟","answer":"أُظهر اسمه في موضع يمكن فيه الإضمار زيادةً في التشنيع عليه وذمه، حتى يقترن اسمه بالعلو والفساد، وتكون الجملة كالمثل الجاري في تقبيح شأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص613، تحت عنوان «علة إظهار اسم ﴿فرعون﴾»","url":""}]},{"id":"s28-4","number":4,"surah":28,"verses":[4],"references":[{"surah":28,"verses":[4]}],"verseLabel":"القصص: 4","question":"لماذا قيل ﴿وَجَعَلَ أَهْلَهَا شِيَعًا﴾ ولم يُكتفَ بذكر تفريقهم؟","answer":"في «جعل» معنى التصيير: حوّل فرعون أهل البلد من حال الاجتماع والائتلاف إلى فرق متنازعة. فالتعبير يبرز مسؤوليته عن إفساد جماعتهم وإضعافها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص615، تحت عنوان «سر استعمال مفردة الجعل دون التفريق»","url":""}]},{"id":"s28-111","number":111,"surah":28,"verses":[4],"references":[{"surah":28,"verses":[4]}],"verseLabel":"القصص: 4","question":"ماذا يصوّر لفظ ﴿شِيَعًا﴾ وتنكيره في وصف أهل مدينة فرعون؟","answer":"يصوّر فرقًا مختلفة الأهواء، تتناصر كل فرقة فيما بينها، ويبرز التنكير تنوّعها واختلافها. وقد أثار فرعون ذلك التفرق ليضعف اجتماعهم ويسهل التحكم فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص616، تحت عنوان «نكتة استعمال مفردة ﴿شيعا﴾ وغرض تنكيرها»","url":""}]},{"id":"s28-5","number":5,"surah":28,"verses":[4],"references":[{"surah":28,"verses":[4]}],"verseLabel":"القصص: 4","question":"ما دلالة التشديد في ﴿يُذَبِّحُ أَبْنَاءَهُمْ﴾؟","answer":"صيغة التفعيل تدل على تكثير الذبح وتكراره، فتبرز شدة بطش فرعون وكثرة ما ارتكبه من قتل الأبناء خوفًا على ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص620، تحت عنوان «بلاغة صيغة التفعيل»","url":""}]},{"id":"s28-112","number":112,"surah":28,"verses":[4],"references":[{"surah":28,"verses":[4]}],"verseLabel":"القصص: 4","question":"لماذا صُوّر بطش فرعون بالفعل المضارع في ﴿يُذَبِّحُ أَبْنَاءَهُمْ﴾؟","answer":"المضارع يستحضر الجريمة الماضية كأنها تقع أمام السامع، فيشتد استقباحها ويظهر هول ما كان يفعله فرعون بالمستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص620، تحت عنوان «غرض التعبير بصيغة المضارع»","url":""}]},{"id":"s28-113","number":113,"surah":28,"verses":[4],"references":[{"surah":28,"verses":[4]}],"verseLabel":"القصص: 4","question":"هل يدل قوله ﴿وَيَسْتَحْيِي نِسَاءَهُمْ﴾ على إحسان فرعون إليهن؟","answer":"الاستحياء إبقاؤهن أحياء، ولكنه هنا إبقاء للاسترقاق والامتهان، وليس رحمة بهن؛ فاجتمع في فعله قتل الأبناء وإذلال النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص621–622، تحت عنوان «دلالة استعمال مفردة الاستحياء»","url":""}]},{"id":"s28-6","number":6,"surah":28,"verses":[5,6],"references":[{"surah":28,"verses":[5,6]}],"verseLabel":"القصص: 5-6","question":"لماذا جاء ﴿وَنُرِيدُ أَنْ نَمُنَّ﴾ بالمضارع في أثناء قصة فرعون الماضية؟","answer":"لاستحضار الحال كأنها تقع الآن: فرعون يستضعفهم، والله يريد المنّ عليهم. وفي هذه المقابلة إظهار أن إرادة الله فوق إرادة الظالم، وأنه قادر على قلب حال المستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص630، تحت عنوان «نكتة التعبير بصيغة المضارع»","url":""}]},{"id":"s28-114","number":114,"surah":28,"verses":[5,6],"references":[{"surah":28,"verses":[5,6]}],"verseLabel":"القصص: 5-6","question":"ما فائدة عطف ﴿وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ﴾ على المنّ بالمستضعفين؟","answer":"هو تفصيل لنعم عظيمة بعد إجمال المنّ: يجعلهم قادة بعد استضعافهم، ويورثهم ما كان في أيدي عدوهم. وخصّ هاتين النعمتين بالذكر لإبراز شأنهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص634، تحت عنوان «بلاغة عطف الجمل»","url":""}]},{"id":"s28-115","number":115,"surah":28,"verses":[5,6],"references":[{"surah":28,"verses":[5,6]}],"verseLabel":"القصص: 5-6","question":"ماذا تضيف جملة ﴿وَنُمَكِّنَ لَهُمْ فِي الْأَرْضِ﴾ إلى نعم الإمامة والوراثة؟","answer":"تضيف نعمة التمكين: لا يقتصر الإنعام على انتقال الملك إليهم، بل يثبت لهم سلطان يستطيعون معه التصرف في الأرض. فالواو تجمع هذه النعمة إلى النعم السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص639، تحت عنوان «معنى الواو في صدر الجملة»","url":""}]},{"id":"s28-116","number":116,"surah":28,"verses":[5,6],"references":[{"surah":28,"verses":[5,6]}],"verseLabel":"القصص: 5-6","question":"ما النعمة التي يضيفها قوله ﴿وَنُرِيَ فِرْعَوْنَ وَهَامَانَ وَجُنُودَهُمَا مِنْهُمْ مَا كَانُوا يَحْذَرُونَ﴾؟","answer":"يضيف إلى نعم المستضعفين أن يُري الله أعداءهم الهلاك الذي كانوا يخشونه من جهتهم. فالواو تضم هذا الإنعام إلى الإمامة والوراثة والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص642، تحت عنوان «معنى (الواو) في جملة: ﴿ونري﴾»","url":""}]},{"id":"s28-117","number":117,"surah":28,"verses":[5,6],"references":[{"surah":28,"verses":[5,6]}],"verseLabel":"القصص: 5-6","question":"ما دلالة إسناد أفعال المنّ وجعل الأئمة والوارثين إلى نون العظمة؟","answer":"يعظّم هذا الإسناد شأن الأفعال، ويبيّن أنها صادرة عن قدرة الله التي لا يردّها بطش فرعون؛ فمن تولّى هذه النعم هو القادر على إنفاذها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص630، تحت عنوان «بلاغة إسناد الأفعال إلى نون العظمة»","url":""}]},{"id":"s28-7","number":7,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"لماذا أُمرت أم موسى بـ﴿أَرْضِعِيهِ﴾ مع أن إرضاع الأم طفلها أمر معتاد؟","answer":"المقصود إرشادها إلى المداومة على إرضاعه ما لم يتحقق الخوف عليه؛ فلا تحملها خشية الخطر على ترك رضاعه قبل أوان إلقائه في اليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص652، تحت عنوان «الغرض من الأمر في ﴿أرضعيه﴾»","url":""}]},{"id":"s28-118","number":118,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"ما الحكمة المذكورة في الموسوعة لاستمرار أم موسى في إرضاعه قبل إلقائه؟","answer":"ذكرت الموسوعة أن استمرار رضاعه يقوّي بنيانه ويهيئه لما يستقبله من أحوال؛ فكان الأمر بالإرضاع من العناية به قبل انتقاله إلى تلك المحنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص652–653، تحت عنوان «سبب الأمر بالمداومة على إرضاعه»","url":""}]},{"id":"s28-119","number":119,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"ماذا تفيد الفاء في ﴿فَإِذَا خِفْتِ عَلَيْهِ فَأَلْقِيهِ فِي الْيَمِّ﴾؟","answer":"تربط الفاء الإلقاء بتحقق الخوف، وتفيد التعقيب: إذا تحقق خطر قتله بادرت إلى ما أمرها الله به دون تردد، اعتمادًا على وعده بحفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص654، تحت عنوان «معنى الفاء في جملة: ﴿فألقيه﴾»","url":""}]},{"id":"s28-8","number":8,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"كيف يطمئن قوله ﴿وَلَا تَخَافِي وَلَا تَحْزَنِي﴾ أم موسى من جهتين؟","answer":"ينهاها عن الخوف مما قد يصيب طفلها، وعن الحزن لفراقه؛ فيجمع طمأنتها على سلامته وتسكين ألم مفارقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص655، تحت عنوان «الغرض من النهي في ﴿ولا تخافي ولا تحزني﴾»","url":""}]},{"id":"s28-120","number":120,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"لماذا تكررت ﴿لَا﴾ في ﴿وَلَا تَخَافِي وَلَا تَحْزَنِي﴾؟","answer":"لتأكيد كل نهي على حدة؛ فيكون النهي عن الحزن مقصودًا مؤكدًا كالنهي عن الخوف، وتكتمل طمأنتها من الأمرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص656، تحت عنوان «دلالة تكرار حرف النهي»","url":""}]},{"id":"s28-121","number":121,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"لماذا قُدّم الخوف على الحزن في خطاب أم موسى؟","answer":"لأن الخوف على سلامة طفلها أشد تعلقًا بالمقام وأسبق إلى نفسها، وهو سبب لكثير من الحزن؛ فبدأ بما يؤدي دفعه إلى تخفيف ما بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص656، تحت عنوان «لطيفة تقديم النهي عن الخوف»","url":""}]},{"id":"s28-9","number":9,"surah":28,"verses":[7],"references":[{"surah":28,"verses":[7]}],"verseLabel":"القصص: 7","question":"ما سرّ الجمع بين ﴿إِنَّا رَادُّوهُ إِلَيْكِ﴾ و﴿وَجَاعِلُوهُ مِنَ الْمُرْسَلِينَ﴾؟","answer":"جمع لها بشارتين تقابلان الخوف والحزن: سيرده إليها فتسكن نفسها، وسيجعله رسولًا فتزداد طمأنينتها إلى حفظه وكرامته. وليس في العطف مجرد رد الولد، بل زيادة بشارة بمستقبله وشرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص658، تحت عنوان «معنى الواو في جملة: ﴿وجاعلوه﴾»","url":""}]},{"id":"s28-10","number":10,"surah":28,"verses":[8],"references":[{"surah":28,"verses":[8]}],"verseLabel":"القصص: 8","question":"ما سرّ اختيار ﴿فَالْتَقَطَهُ آلُ فِرْعَوْنَ﴾ بدل «أخذوه»؟","answer":"الالتقاط يدل على العثور عليه مصادفة والتقاطه كما يلتقط الشيء الضائع، ويزيد تصوير حال الرضيع المحتاج إلى الرعاية. أما الأخذ فأعم، وقد يوحي بالقصد والعناية منذ البداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص664، تحت عنوان «نكتة التعبير بمفردة الالتقاط دون الأخذ»","url":""}]},{"id":"s28-11","number":11,"surah":28,"verses":[8],"references":[{"surah":28,"verses":[8]}],"verseLabel":"القصص: 8","question":"كيف يصوّر قوله ﴿لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا﴾ انقلاب قصد آل فرعون؟","answer":"التقطوه رجاء النفع والسرور، فانتهى أمره إلى العداوة والحزن. وصُوّرت هذه العاقبة كأنها الغرض الذي التقطوه لأجله، باستعارة لام التعليل؛ ليبرز انقلاب قصدهم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص665، تحت عنوان «بلاغة الاستعارة في جملة: ﴿ليكون لهم﴾»","url":""}]},{"id":"s28-122","number":122,"surah":28,"verses":[8],"references":[{"surah":28,"verses":[8]}],"verseLabel":"القصص: 8","question":"لماذا سمّى بعض العلماء اللام في ﴿لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَنًا﴾ لام العاقبة؟","answer":"لأن العداوة والحزن نتيجة الالتقاط، ولم يكونا غرض آل فرعون منه. وذكرت الموسوعة أيضًا وجهًا يجعلها للتعليل بالنظر إلى تقدير الله، لا إلى قصد الملتقطين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص665–666، تحت عنوان «رأي آخر في اللام»","url":""}]},{"id":"s28-12","number":12,"surah":28,"verses":[9],"references":[{"surah":28,"verses":[9]}],"verseLabel":"القصص: 9","question":"ما سرّ تقديم امرأة فرعون نفسها في ﴿قُرَّتُ عَيْنٍ لِي وَلَكَ﴾؟","answer":"قدمت ﴿لي﴾ لأن حاجتها إلى الرضيع أظهر وأشد، ولما في ذلك من دلالة العطف والحنان، ثم أشركت فرعون في رجاء قرة العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص675، تحت عنوان «لطيفة تقديم ضميرها على ضمير فرعون»","url":""}]},{"id":"s28-13","number":13,"surah":28,"verses":[9],"references":[{"surah":28,"verses":[9]}],"verseLabel":"القصص: 9","question":"ما سرّ التعبير بضمير الجمع في ﴿لَا تَقْتُلُوهُ﴾؟","answer":"من الأوجه أنها خاطبت فرعون بصيغة الجمع تعظيمًا له واستمالةً لقلبه كي يساعدها على إبقاء الرضيع. ويجوز أن يكون الخطاب لفرعون ورجاله الذين يتولون قتل الأطفال؛ فيشمل النهي صاحب الأمر ومنفذيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص676، تحت عنوان «نكتة إسناد فعل القتل إلى ضمير الجمع»","url":""}]},{"id":"s28-14","number":14,"surah":28,"verses":[9],"references":[{"surah":28,"verses":[9]}],"verseLabel":"القصص: 9","question":"أي حال تكشفها الواو في ﴿وَهُمْ لَا يَشْعُرُونَ﴾ بعد حديث امرأة فرعون؟","answer":"هي واو الحال على الأرجح، فتبيّن أنهم التقطوا موسى ورجوا الانتفاع به وهم لا يشعرون بخطئهم في تقدير مآله، وأنه سيكون لهم عدوًا وحزنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص679، تحت عنوان «معنى (الواو) في جملة ﴿وهم لا يشعرون﴾»","url":""}]},{"id":"s28-123","number":123,"surah":28,"verses":[9],"references":[{"surah":28,"verses":[9]}],"verseLabel":"القصص: 9","question":"لماذا جاء ﴿لَا يَشْعُرُونَ﴾ بالمضارع في حكاية موقف آل فرعون؟","answer":"ليستحضر المشهد الماضي كأنه حاضر: هم فرحون بالرضيع، مستبشرون بنفعه، غافلون عما يحذرونه منه. فيقرب المضارع هذه المفارقة إلى عين السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص680، تحت عنوان «دلالة التعبير بالفعل المضارع في: ﴿لا يشعرون﴾»","url":""}]},{"id":"s28-15","number":15,"surah":28,"verses":[10],"references":[{"surah":28,"verses":[10]}],"verseLabel":"القصص: 10","question":"ممّ كان فؤاد أم موسى فارغًا في قوله ﴿وَأَصْبَحَ فُؤَادُ أُمِّ مُوسَى فَارِغًا﴾؟","answer":"تذكر الموسوعة احتمالين: خلوه من الخوف والحزن ثقة بوعد الله بردّ موسى إليها، أو خلوه من التفكير في كل شيء إلا رضيعها وما قد يصيبه بعد إلقائه في اليم. وترى أن الاحتمال الثاني هو الأظهر هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص686–687، تحت عنوان «معنى الفراغ في قوله: ﴿فارغا﴾»","url":""}]},{"id":"s28-109","number":109,"surah":28,"verses":[10],"references":[{"surah":28,"verses":[10]}],"verseLabel":"القصص: 10","question":"كيف يصوّر وصف فؤاد أم موسى بأنه ﴿فَارِغًا﴾ شدة خوفها؟","answer":"من أوجه تفسيره أنه كناية عن ذهول العقل وطيش اللب من شدة الخوف على موسى؛ فقد استولى عليها القلق، فشغلها عن كل ما يسكّن نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص688، تحت عنوان «بلاغة الكناية في لفظة ﴿فارغا﴾»","url":""}]},{"id":"s28-16","number":16,"surah":28,"verses":[10],"references":[{"surah":28,"verses":[10]}],"verseLabel":"القصص: 10","question":"ما سرّ تصوير تثبيت أم موسى بقوله ﴿لَوْلَا أَنْ رَبَطْنَا عَلَى قَلْبِهَا﴾؟","answer":"شُبه تثبيت قلبها بالصبر والطمأنينة برباط يمسك ما يخشى انفلاته. فالصورة تبين أن الله ثبّتها عن الجزع وإظهار أمر موسى، حتى بقيت على الثقة بوعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص691، تحت عنوان «بلاغة الاستعارة في الفعل ﴿ربطنا﴾»","url":""}]},{"id":"s28-17","number":17,"surah":28,"verses":[11],"references":[{"surah":28,"verses":[11]}],"verseLabel":"القصص: 11","question":"ما سرّ اختيار أم موسى قولها لأخته ﴿قُصِّيهِ﴾؟","answer":"القص تتبع الأثر للوصول إلى خبره، فأمرت أخته أن تتبع أثره وتتقصى حاله. والتعبير يضم البحث والمراقبة إلى معرفة ما يصير إليه، لا مجرد رؤيته مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص695، تحت عنوان «دلالة التعبير بالقص في الفعل: ﴿قصيه﴾»","url":""}]},{"id":"s28-18","number":18,"surah":28,"verses":[11],"references":[{"surah":28,"verses":[11]}],"verseLabel":"القصص: 11","question":"ماذا يفيد حرف ﴿عَنْ﴾ في مراقبة أخت موسى له ﴿عَنْ جُنُبٍ﴾؟","answer":"يفيد المجاوزة، فيدل على حذرها من الاقتراب الشديد من مكانه حتى لا يُلاحظ تعلق نظرها به، فينكشف ارتباطها به وأمرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص697، تحت عنوان «معنى ﴿عن﴾ في القيد ﴿عن جنب﴾»","url":""}]},{"id":"s28-124","number":124,"surah":28,"verses":[11],"references":[{"surah":28,"verses":[11]}],"verseLabel":"القصص: 11","question":"لماذا قيل ﴿عَنْ جُنُبٍ﴾ ولم يُكتفَ بقول «عن بُعد»؟","answer":"من معاني «جنب» البعد أو الجانب، ومن وجوهه أنها تنظر كالمتجانبة غير المكترثة. فيجمع التعبير إمكان إبصاره مع إخفاء اهتمامها به، ولا يلزم منه بُعد يحول دون رؤيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص697، تحت عنوان «دلالة التعبير بمفردة: ﴿جنب﴾ دون (بعد)»","url":""}]},{"id":"s28-19","number":19,"surah":28,"verses":[12],"references":[{"surah":28,"verses":[12]}],"verseLabel":"القصص: 12","question":"ما دلالة الماضي في ﴿وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ﴾؟","answer":"يشير إلى تدبير سابق قضاه الله: منع موسى من الرضاع من غير أمه تمهيدًا لرده إليها. فالمراد منع قدّره الله، لا تكليف الطفل بتحريم شرعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص704، تحت عنوان «دلالة التعبير بالماضي ﴿وحرمنا﴾»","url":""}]},{"id":"s28-125","number":125,"surah":28,"verses":[12],"references":[{"surah":28,"verses":[12]}],"verseLabel":"القصص: 12","question":"لماذا أُسند منع موسى من المراضع إلى نون العظمة في ﴿وَحَرَّمْنَا﴾؟","answer":"لبيان أن امتناعه من جميع المراضع أمر خارج عن المعتاد رتّبه الله بحكمته وعظمته، ليكون سببًا في عودته إلى أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص704–705، تحت عنوان «لطيفة إسناد التحريم إلى نون العظمة»","url":""}]},{"id":"s28-126","number":126,"surah":28,"verses":[12],"references":[{"surah":28,"verses":[12]}],"verseLabel":"القصص: 12","question":"ما فائدة ﴿مِنْ قَبْلُ﴾ في خبر تحريم المراضع على موسى؟","answer":"تؤكد سبق هذا التدبير؛ ومن الأوجه أنه سبق قصّ أخته أثره وإبصارها له، وقيل غير ذلك. فامتناعه لم ينشأ من اقتراح أخته، بل كان من تهيئة الله لرده إلى أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص705–706، تحت عنوان «فائدة تقييد التحريم بالجار والمجرور: ﴿من قبل﴾»","url":""}]},{"id":"s28-20","number":20,"surah":28,"verses":[12],"references":[{"surah":28,"verses":[12]}],"verseLabel":"القصص: 12","question":"ما سرّ زيادة ﴿وَهُمْ لَهُ نَاصِحُونَ﴾ في القصص على نظيرها في طه؟","answer":"اقتصر موضع طه على ﴿هل أدلكم على من يكفله﴾، وزاد في القصص ﴿وهم له ناصحون﴾. وفي الزيادة توجيه يحتمل فيه الضمير موسى أو فرعون: يُفهم إخلاصهم للصبي، ويمكن عند الاتهام تفسيره بالنصح للملك؛ فتلائم دقة الموقف وخوف انكشاف صلتها بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص79، تحت عنوان «زيادة ﴿وهم له ناصحون﴾ في سورة القصص»","url":""}]},{"id":"s28-21","number":21,"surah":28,"verses":[13],"references":[{"surah":28,"verses":[13]}],"verseLabel":"القصص: 13","question":"لماذا قُدّمت قرة عين أم موسى على علمها بتحقق الوعد؟","answer":"رعايةً لحالها ولطفًا بها؛ فاطمئنان قلبها وزوال حزنها يعينان على رسوخ العلم، فجاءت قرة العين قبل ذكر علمها بأن وعد الله حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص718، تحت عنوان «سر تقديم جملة: ﴿تقر عينها﴾»","url":""}]},{"id":"s28-127","number":127,"surah":28,"verses":[13],"references":[{"surah":28,"verses":[13]}],"verseLabel":"القصص: 13","question":"ما الذي يضيفه ﴿وَلِتَعْلَمَ أَنَّ وَعْدَ اللَّهِ حَقٌّ﴾ مع أنها كانت مصدقة بالوعد؟","answer":"ينقلها تحقق الوعد من التصديق بالغيب إلى مشاهدة وقوعه؛ فيثبت يقينها ويتمكن، فلا يكون المراد أنها لم تكن تعلم صدق وعد الله قبل ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص717، تحت عنوان «دلالة التعبير بالعلم في: ﴿ولتعلم﴾»","url":""}]},{"id":"s28-22","number":22,"surah":28,"verses":[14],"references":[{"surah":28,"verses":[14]}],"verseLabel":"القصص: 14","question":"ما سرّ زيادة ﴿وَاسْتَوَى﴾ في القصص، وحذفها من نظيرها في يوسف؟","answer":"يربط مبحث المتشابه اللفظي ذكر «واستوى» في القصص ببلوغ موسى كمال الشباب والعقل عند الإيحاء إليه في الأربعين. وأما يوسف فكان إيتاؤه قبل ذلك، وسبقه الوحي في الجب؛ لذا اكتفى موضع يوسف ببلوغ الأشد دون زيادة «واستوى».","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص731–732، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s28-23","number":23,"surah":28,"verses":[14],"references":[{"surah":28,"verses":[14]}],"verseLabel":"القصص: 14","question":"ما معنى ﴿حُكْمًا﴾ فيما آتاه الله موسى؟","answer":"قيل: الحكمة التي تمنع من الزلل وتضع الشيء في موضعه، وقيل: النبوة، وقيل: القضاء. وتلتقي هذه الأقوال في صلاح القول والعمل والقدرة على معرفة الحق والحكم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص726، تحت عنوان «سر التعبير بالحكم في ﴿حكما﴾»","url":""}]},{"id":"s28-128","number":128,"surah":28,"verses":[14],"references":[{"surah":28,"verses":[14]}],"verseLabel":"القصص: 14","question":"ما فائدة الجمع بين الحكم والعلم مع تقديم الحكم في ﴿آتَيْنَاهُ حُكْمًا وَعِلْمًا﴾؟","answer":"يبين الجمع أن العلم وحده لا يستلزم الحكمة، فليس كل عالم حكيمًا. ومن توجيه التقديم أن الحكم هو النبوة، ثم يُفتح لصاحبها من علم الشريعة ما يحتاج إليه؛ فيجتمع العلم والهداية إلى العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص727، تحت عنوان «بلاغة تقديم الحكم على العلم»","url":""}]},{"id":"s28-24","number":24,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"لماذا حُدّد وقت دخول موسى المدينة بأنه ﴿عَلَى حِينِ غَفْلَةٍ مِنْ أَهْلِهَا﴾؟","answer":"لبيان أنه دخل في وقت سكون الناس وراحتهم وخلو الطريق، فلم يشعر به أحد. وهذا الظرف يمهّد لما وقع بعده من الحادثة وخروجه من مصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص736، تحت عنوان «دلالة الإتيان بالظرف الزماني ﴿حين﴾»","url":""}]},{"id":"s28-129","number":129,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"ما فائدة تنكير ﴿غَفْلَةٍ﴾ في ﴿غَفْلَةٍ مِنْ أَهْلِهَا﴾ بدل إضافتها إليهم؟","answer":"التنكير يفيد تفخيم الغفلة: كانت غفلة عظيمة من أهل المدينة، فناسب تصوير خلوها في وقت راحتهم. ولذلك عُدل عن «غفلة أهلها» إلى هذا التعبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص736، تحت عنوان «نكتة العدول عن الإضافة في ﴿غفلة من أهلها﴾»","url":""}]},{"id":"s28-25","number":25,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"لماذا جاءت ﴿هَذَا مِنْ شِيعَتِهِ وَهَذَا مِنْ عَدُوِّهِ﴾ دون عاطف بعد ذكر الرجلين؟","answer":"لأنها تفصيل لما أُجمل من حال الرجلين في الجملة السابقة، فكأنها جزء منها؛ وقد أغنت شدة الاتصال بينهما عن العطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص738، تحت عنوان «بلاغة الفصل في ﴿هذا من شيعته﴾»","url":""}]},{"id":"s28-130","number":130,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"ماذا تبين إضافة ﴿شِيعَتِهِ﴾ و﴿عَدُوِّهِ﴾ إلى موسى في وصف الرجلين؟","answer":"تبيّن صلة كل منهما به: أحدهما من بني إسرائيل، والآخر قبطي من قوم فرعون. وتكشف الإضافة عن موالاته للمظلومين من بني إسرائيل وعداوته لظلم القبط.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص740، تحت عنوان «دلالة الإضافة في لفظي ﴿شيعته﴾، ﴿عدوه﴾»","url":""}]},{"id":"s28-131","number":131,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"ماذا تفيد الفاء في ﴿فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ﴾؟","answer":"تفيد التعقيب وتصور تسارع أحداث القصة؛ فما إن أبصر الإسرائيلي موسى حتى طلب إعانته على خصمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص741، تحت عنوان «نكتة العطف بالفاء في ﴿فاستغاثه﴾»","url":""}]},{"id":"s28-26","number":26,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"ماذا يدل لفظ ﴿فَوَكَزَهُ﴾ على كيفية ضرب موسى للقبطي؟","answer":"الوكز هو الضرب باليد مجموعة، وورد تفسيره بالدفع أو الطعن. فاللفظ يحدد صورة الضربة التي وجّهها موسى إلى القبطي لنصرة المستغيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص742–743، تحت عنوان «نكتة التعبير بلفظ ﴿فوكزه﴾»","url":""}]},{"id":"s28-132","number":132,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"ما دلالة الفاء في ﴿فَقَضَى عَلَيْهِ﴾ بعد ﴿فَوَكَزَهُ مُوسَى﴾؟","answer":"تدل على وقوع الموت عقب الوكزة مباشرة؛ فهي تربط السبب بنتيجته وتصور سرعة انتهاء الضربة إلى موت القبطي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص744، تحت عنوان «نكتة العطف بالفاء في قوله: ﴿فقضى عليه﴾»","url":""}]},{"id":"s28-133","number":133,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"لماذا جاء ﴿قَالَ هَذَا مِنْ عَمَلِ الشَّيْطَانِ﴾ دون عطف بعد موت القبطي؟","answer":"كأن وقوع القتل أثار سؤالًا: ماذا كان موقف موسى حين أدرك ما وقع؟ فجاء قوله جوابًا مباشرًا، يكشف ندمه وسرعة تنبهه إلى خطئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص745، تحت عنوان «بلاغة الفصل في ﴿قال هذا من عمل الشيطان﴾»","url":""}]},{"id":"s28-134","number":134,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"هل وقوع موت القبطي عقب الوكزة يعني أن موسى تعمد قتله؟","answer":"تذكر الموسوعة أن موسى لم يتعمد قتله، ولكن الوكزة أنهت حياته. فبيان وقوع الموت نتيجة الضربة لا يقتضي أنه قصد إزهاق روحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص744، تحت عنوان «سر إضمار الفاعل في ﴿فقضى عليه﴾»","url":""}]},{"id":"s28-27","number":27,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"ما فائدة الإشارة بـ﴿هَذَا﴾ في قول موسى ﴿هَذَا مِنْ عَمَلِ الشَّيْطَانِ﴾؟","answer":"تميّز الإشارة العمل الذي وقع تمييزًا واضحًا، سواء أُريدت الضربة أو ما نشأ عنها من موت؛ وفيها تقرير لخطئه وتنبه إلى ما حمله عليه الغضب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص746، تحت عنوان «بلاغة التعبير باسم الإشارة ﴿هذا﴾»","url":""}]},{"id":"s28-135","number":135,"surah":28,"verses":[15],"references":[{"surah":28,"verses":[15]}],"verseLabel":"القصص: 15","question":"لماذا نسب موسى ما وقع إلى ﴿عَمَلِ الشَّيْطَانِ﴾ مع أنه باشر الضربة؟","answer":"لما كان للشيطان من تزيين وتهييج للغضب، نُسب الفعل إلى سببه؛ وهذا من المجاز العقلي. فالإسناد يبين سبب الاندفاع إلى الفعل، مع بقاء موسى مباشرًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص747، تحت عنوان «بلاغة إسناد الفعل إلى سببه»","url":""}]},{"id":"s28-28","number":28,"surah":28,"verses":[16],"references":[{"surah":28,"verses":[16]}],"verseLabel":"القصص: 16","question":"لماذا قدّم موسى ﴿إِنِّي ظَلَمْتُ نَفْسِي﴾ على طلب المغفرة؟","answer":"قدّم الاعتراف بخطئه أدبًا مع الله وتذللًا بين يدي الدعاء، ثم طلب العفو؛ فاجتمع الإقرار بالذنب والافتقار إلى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص756، تحت عنوان «سر الإخبار عن ظلم النفس قبل الدعاء»","url":""}]},{"id":"s28-136","number":136,"surah":28,"verses":[16],"references":[{"surah":28,"verses":[16]}],"verseLabel":"القصص: 16","question":"كيف تصوّر الفاء في ﴿فَاغْفِرْ لِي﴾ سرعة رجوع موسى إلى الله؟","answer":"تفيد التعقيب؛ فقد أعقب اعترافه بظلم نفسه بطلب المغفرة مباشرة. وفي ذلك مبادرته إلى الاستغفار وأن مخرج الذنب هو الرجوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص757، تحت عنوان «سر العطف بالفاء في ﴿فاغفر﴾»","url":""}]},{"id":"s28-29","number":29,"surah":28,"verses":[17],"references":[{"surah":28,"verses":[17]}],"verseLabel":"القصص: 17","question":"ما صلة الفاء في ﴿فَلَنْ أَكُونَ ظَهِيرًا لِلْمُجْرِمِينَ﴾ بنعمة الله على موسى؟","answer":"تربط التعهد بالإنعام السابق: لما أنعم الله عليه جعل شكر النعمة نصرة الحق وترك إعانة المجرمين. فالالتزام نتيجة لما استشعره من فضل ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص763–764، تحت عنوان «نكتة التعبير بالفاء في ﴿فلن أكون﴾»","url":""}]},{"id":"s28-137","number":137,"surah":28,"verses":[17],"references":[{"surah":28,"verses":[17]}],"verseLabel":"القصص: 17","question":"ما الذي تؤكده ﴿لَنْ﴾ في تعهد موسى ﴿فَلَنْ أَكُونَ ظَهِيرًا لِلْمُجْرِمِينَ﴾؟","answer":"تؤكد نفي المعاونة في المستقبل؛ فيلزم موسى نفسه أن تكون قوته في نصرة أولياء الله، وألا يستعملها في مظاهرة المجرمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص764، تحت عنوان «فائدة النفي بـ(لن)»","url":""}]},{"id":"s28-138","number":138,"surah":28,"verses":[17],"references":[{"surah":28,"verses":[17]}],"verseLabel":"القصص: 17","question":"كيف يصوّر لفظ ﴿ظَهِيرًا﴾ إعانة الإنسان غيره؟","answer":"الظهير هو المعين الذي يقوّي غيره ويسنده. وأصل اللفظ من الظهر؛ فكأن المعاون يحمل من يعينه على ظهره، فيجسّم معنى التقوية والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص764–765، تحت عنوان «بلاغة التعبير بلفظ: ﴿ظهيرا﴾»","url":""}]},{"id":"s28-30","number":30,"surah":28,"verses":[18],"references":[{"surah":28,"verses":[18]}],"verseLabel":"القصص: 18","question":"كيف يجمع ﴿خَائِفًا يَتَرَقَّبُ﴾ بين شعور موسى وسلوكه في المدينة؟","answer":"الخوف يصف ما في نفسه من خشية انكشاف أمر القتيل، والترقب يصف مراقبته لما يتحدث به الناس وما يصنعونه؛ فيكتمل تصوير حاله النفسية وما نتج عنها من حذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص769، تحت عنوان «بلاغة تعدد الخبر في ﴿خائفا يترقب﴾»","url":""}]},{"id":"s28-139","number":139,"surah":28,"verses":[18],"references":[{"surah":28,"verses":[18]}],"verseLabel":"القصص: 18","question":"ما دلالة وصف موسى بـ﴿خَائِفًا﴾ مع معرفته بالله وتوكله عليه؟","answer":"تذكر الموسوعة أن خوف الأذى من الأعداء من مقتضى الطبيعة البشرية، ولا ينافي المعرفة بالله أو التوكل عليه؛ فكان يخاف أن يؤخذ بسبب قتل القبطي.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص770، تحت عنوان «نكتة التعبير باسم الفاعل في ﴿خائفا﴾»","url":""}]},{"id":"s28-140","number":140,"surah":28,"verses":[18],"references":[{"surah":28,"verses":[18]}],"verseLabel":"القصص: 18","question":"لماذا عُبّر بالمضارع في ﴿يَتَرَقَّبُ﴾ عند وصف حال موسى؟","answer":"ليستحضر حاله، ويدل على تجدد قلقه ومراقبته أخبار الناس وحديثهم عن القتيل، فليس ترقبه لحظة عابرة انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص770، تحت عنوان «نكتة التعبير بالمضارع في ﴿يترقب﴾»","url":""}]},{"id":"s28-31","number":31,"surah":28,"verses":[18],"references":[{"surah":28,"verses":[18]}],"verseLabel":"القصص: 18","question":"لماذا أُكّد عتاب موسى بـ«إنّ» واللام في ﴿إِنَّكَ لَغَوِيٌّ مُبِينٌ﴾؟","answer":"لأن الإسرائيلي عاد إلى الخصام والاستصراخ بعد ورطة الأمس، فكأنه لم يعتبر بما جرّه خصامه. فناسب ذلك تأكيد العتاب على سوء تدبيره وتكرر مخاصماته.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص774، تحت عنوان «فائدة التأكيد في قوله: ﴿إنك لغوي مبين﴾»","url":""}]},{"id":"s28-141","number":141,"surah":28,"verses":[18],"references":[{"surah":28,"verses":[18]}],"verseLabel":"القصص: 18","question":"ماذا يضيف وصف ﴿مُبِينٌ﴾ إلى ﴿لَغَوِيٌّ﴾ في عتاب موسى؟","answer":"يبين أن غوايته ظاهرة غير خفية؛ فقد تسبب خصامه بالأمس في قتل رجل، ثم عاد اليوم إلى قتال آخر، فكشف تكرار الخصام عن سوء حاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص775، تحت عنوان «الغرض من الوصف بـ﴿مبين﴾»","url":""}]},{"id":"s28-32","number":32,"surah":28,"verses":[19],"references":[{"surah":28,"verses":[19]}],"verseLabel":"القصص: 19","question":"من القائل ﴿يَا مُوسَى أَتُرِيدُ أَنْ تَقْتُلَنِي﴾، وما وجه قوله؟","answer":"الراجح في المبحث أن القائل هو الإسرائيلي؛ ظن أن موسى يريد البطش به لما رآه غاضبًا، وهو الذي عرف قتل الأمس. وقيل: القائل هو القبطي؛ لذلك أثبت الخلاف ولم يحصر الجواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص782، تحت عنوان «نكتة إضمار الفاعل في قوله: ﴿قال يا موسى﴾»","url":""}]},{"id":"s28-33","number":33,"surah":28,"verses":[20],"references":[{"surah":28,"verses":[20]}],"verseLabel":"القصص: 20","question":"لماذا ذُكر أن الرجل جاء ﴿مِنْ أَقْصَى الْمَدِينَةِ﴾ لتحذير موسى؟","answer":"تذكر الموسوعة أن الظاهر أن الجهة كانت ناحية قصر فرعون ومنازل الأشراف. فذكرها يناسب مجيء التحذير من موضع الملأ وما يدبرونه، ويوضح مسار الرجل إلى موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص792، تحت عنوان «مناسبة ذكر المكان في الآية»","url":""}]},{"id":"s28-142","number":142,"surah":28,"verses":[20],"references":[{"surah":28,"verses":[20]}],"verseLabel":"القصص: 20","question":"ماذا يصوّر ﴿يَسْعَى﴾ في مجيء الرجل لتحذير موسى؟","answer":"السعي مشي شديد سريع دون الجري؛ فيصور عجلة الرجل وحرصه على إيصال الخبر والنصح لموسى، مع تجنب الجري الذي يلفت الأنظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص793، تحت عنوان «نكتة التعبير بلفظ: ﴿يسعى﴾»","url":""}]},{"id":"s28-34","number":34,"surah":28,"verses":[20],"references":[{"surah":28,"verses":[20]}],"verseLabel":"القصص: 20","question":"لماذا عُبّر عن تشاور الملأ بلفظ ﴿يَأْتَمِرُونَ﴾؟","answer":"أصل الائتمار أخذ الأمر والعمل به، ثم أُطلق على التشاور لأن المتشاورين يأخذ بعضهم برأي بعض وأمره؛ فهو يصور تدبيرهم المشترك لقتل موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص795، تحت عنوان «نكتة التعبير بلفظ ﴿يأتمرون﴾»","url":""}]},{"id":"s28-143","number":143,"surah":28,"verses":[20],"references":[{"surah":28,"verses":[20]}],"verseLabel":"القصص: 20","question":"ماذا تضيف الباء في ﴿يَأْتَمِرُونَ بِكَ﴾ إلى معنى التشاور؟","answer":"تضمّن الفعل معنى «يهمّون»، فاجتمع في التعبير أنهم يتشاورون في أمر موسى ويهمّون بقتله؛ فأفادت الكلمة المعدّاة بالباء معنى الفعلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج40، ص796، تحت عنوان «سر تعدية الفعل ﴿يأتمرون﴾»","url":""}]},{"id":"s28-35","number":35,"surah":28,"verses":[21],"references":[{"surah":28,"verses":[21]}],"verseLabel":"القصص: 21","question":"ما سرّ تكرار ﴿خَائِفًا يَتَرَقَّبُ﴾ عند خروج موسى؟","answer":"تكرر الوصف مع اختلاف درجته: خاف أولًا عقب قتل القبطي وترقب ظهور خبره، ثم اشتد خوفه وترقبه بعد شيوع الحادثة وتشاور الملأ في قتله، فخرج من المدينة خائفًا يترقب.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص12، تحت عنوان «سر تكرار الوصفين ﴿خائفا يترقب﴾»","url":""}]},{"id":"s28-36","number":36,"surah":28,"verses":[22],"references":[{"surah":28,"verses":[22]}],"verseLabel":"القصص: 22","question":"ما فائدة أسلوب الترجي في قوله: ﴿عَسَى رَبِّي أَنْ يَهْدِيَنِي﴾؟","answer":"جمع الرجاء بحسن الظن بالله والتوكل عليه مع العمل؛ فقد سلك موسى الطريق ثم دعا ربه أن يبلغه مدين سالمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص19–20، تحت عنوان «فائدة استعمال أسلوب الترجي»","url":""}]},{"id":"s28-144","number":144,"surah":28,"verses":[22],"references":[{"surah":28,"verses":[22]}],"verseLabel":"القصص: 22","question":"ما نكتة استعمال لفظ ﴿سَوَاءَ﴾ في قوله: ﴿سَوَاءَ السَّبِيلِ﴾؟","answer":"السواء هو الطريق المستقيم السهل الأقصد الذي لا عوج فيه، فخص بالدعاء السبيل الموصل إلى النجاة لا مطلق طريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص21، تحت عنوان «نكتة استعمال لفظ ﴿سواء﴾»","url":""}]},{"id":"s28-37","number":37,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما نوع ﴿مِنْ﴾ ودلالتها في قوله: ﴿مِنْ دُونِهِمُ﴾؟","answer":"هي للظرفية؛ بينت أن المرأتين في موضع منفصل عن السقاة وأدنى إلى جهة مجيء موسى، فصورت بعدهما عن الزحام.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص30، تحت عنوان «نوع ﴿من﴾ ودلالتها»","url":""}]},{"id":"s28-145","number":145,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما نكتة استعمال مفردة ﴿تَذُودَانِ﴾؟","answer":"الذود دفع الغنم ومنعها من ورود الماء؛ فصورت الصيغة تجدد جهدهما ومشقتهما في كف الماشية حتى يفرغ الرعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص31، تحت عنوان «نكتة استعمال مفردة ﴿تذودان﴾»","url":""}]},{"id":"s28-38","number":38,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما غرض الاستفهام في قوله: ﴿مَا خَطْبُكُمَا﴾؟","answer":"سأل لمعرفة سبب وقوفهما وذودهما عن السقي، وفي الاستفهام عناية بحالهما وإنكار لإهمال الرعاء امرأتين ضعيفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص32، تحت عنوان «غرض الاستفهام ﴿ما خطبكما﴾»","url":""}]},{"id":"s28-146","number":146,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما بلاغة استعمال مفردة ﴿خَطْبُكُمَا﴾؟","answer":"الخطب شأن عظيم يوجب السؤال والاهتمام، فدل اللفظ على أن حالهما لافتة تستدعي التعاطف والمساعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص32–33، تحت عنوان «بلاغة استعمال مفردة ﴿خطبكما﴾»","url":""}]},{"id":"s28-39","number":39,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما دلالة استعمال لفظ ﴿شَيْخٌ﴾ في قول المرأتين؟","answer":"دل على تقدم سن أبيهما وعجزه عن مباشرة السقي، فبيّن سبب خروجهما للعمل وأعفاهما من تهمة مخالفة المروءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص35، تحت عنوان «دلالة استعمال لفظ الشيخ»","url":""}]},{"id":"s28-147","number":147,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما بلاغة الاحتراس بوصف الشيخ بأنه ﴿كَبِيرٌ﴾؟","answer":"دفع توهم أن الشيخ ما زال قويًا قادرًا؛ فقرر بلوغه غاية الكبر التي تمنعه من الخروج والسقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص35، تحت عنوان «بلاغة الاحتراس في الوصف»","url":""}]},{"id":"s28-148","number":148,"surah":28,"verses":[23],"references":[{"surah":28,"verses":[23]}],"verseLabel":"القصص: 23","question":"ما بلاغة التعريض في قولهما: ﴿وَأَبُونَا شَيْخٌ كَبِيرٌ﴾؟","answer":"عرضتا حاجتهما إلى من يعينهما من غير تصريح بالطلب، فجمع الكلام عفة النفس وحسن الأدب مع إفهام سبب الانتظار.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص36، تحت عنوان «بلاغة التعريض»","url":""}]},{"id":"s28-40","number":40,"surah":28,"verses":[24],"references":[{"surah":28,"verses":[24]}],"verseLabel":"القصص: 24","question":"ما فائدة العطف بالفاء في قوله: ﴿فَسَقَى لَهُمَا﴾؟","answer":"أفادت سرعة استجابة موسى ومبادرته إلى الخير من غير تردد ولا طلب عوض، فكشفت شهامته وفعاليته.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص39، تحت عنوان «فائدة العطف بحرف الفاء»","url":""}]},{"id":"s28-149","number":149,"surah":28,"verses":[24],"references":[{"surah":28,"verses":[24]}],"verseLabel":"القصص: 24","question":"ما معنى اللام ودلالتها في قوله: ﴿لَهُمَا﴾؟","answer":"هي لام الأجل؛ أي سقى لأجلهما رفقًا بهما وعونًا، فدل المتعلق على أن فعله إحسان خالص للمرأتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص39–40، تحت عنوان «معنى اللام ودلالتها»","url":""}]},{"id":"s28-150","number":150,"surah":28,"verses":[24],"references":[{"surah":28,"verses":[24]}],"verseLabel":"القصص: 24","question":"ما دلالة التعبير بـ﴿تَوَلَّى﴾ مادة وصيغة؟","answer":"صور انصرافه إلى الظل ورجوعه عن البئر بعد إتمام السقي، وتفيد المادة ابتعاده عن موضع العمل ليلجأ إلى الراحة والدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص40، تحت عنوان «دلالة التعبير بمفردة ﴿تولى﴾ مادة وصيغة»","url":""}]},{"id":"s28-41","number":41,"surah":28,"verses":[24],"references":[{"surah":28,"verses":[24]}],"verseLabel":"القصص: 24","question":"ما فائدة الاسم الموصول ﴿مَا﴾ في قوله: ﴿لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ﴾؟","answer":"عمم كل خير ينزله الله قليلًا أو كثيرًا، وصار المعروف في الدعاء هو جنس الخير كله، فجمع السؤال مع الأدب والإجمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص42، تحت عنوان «فائدة استعمال الاسم الموصول»","url":""}]},{"id":"s28-151","number":151,"surah":28,"verses":[24],"references":[{"surah":28,"verses":[24]}],"verseLabel":"القصص: 24","question":"ما بلاغة تضمين ﴿فَقِيرٌ﴾ معنى سائل؟","answer":"أكد افتقاره باللام في ﴿لما﴾، فضمن الفقير معنى السائل الطالب؛ فهو لا يملك إلا أن يعرض حاجته ويرجو فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص43، تحت عنوان «بلاغة تضمين ﴿فقير﴾ معنى سائل»","url":""}]},{"id":"s28-152","number":152,"surah":28,"verses":[24],"references":[{"surah":28,"verses":[24]}],"verseLabel":"القصص: 24","question":"ما بلاغة الإيماء في جملة الفاصلة: ﴿إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ﴾؟","answer":"جمعت الثناء والشكر والدعاء في عبارة واحدة؛ فذكر إنزال الخير يعترف بالنعمة، ووصف الفقر يلمح إلى طلب المزيد بأدب.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص44، تحت عنوان «بلاغة الإيماء في جملة الفاصلة»","url":""}]},{"id":"s28-42","number":42,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما بلاغة الاستعارة في حرف الاستعلاء في قوله: ﴿عَلَى اسْتِحْيَاءٍ﴾؟","answer":"شبه تمكن الحياء منها بمن يعتلي الشيء ويملك زمامه؛ فكان الحياء صفة حاكمة لمشيتها وسائر حالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص49–50، تحت عنوان «بلاغة الاستعارة في استعمال حرف الاستعلاء»","url":""}]},{"id":"s28-153","number":153,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما دلالة التعبير بالمصدر المزيد ﴿اسْتِحْيَاءٍ﴾؟","answer":"صيغة الاستفعال أبلغ من الحياء المجرد، فدل المصدر المزيد على شدة حيائها وتمكنه منها في مقابلة المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص50، تحت عنوان «دلالة التعبير بالمصدر المزيد»","url":""}]},{"id":"s28-43","number":43,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما فائدة إسناد الدعوة إلى الأب في قولها: ﴿إِنَّ أَبِي يَدْعُوكَ﴾؟","answer":"رفع الريبة وحقق الطمأنينة؛ فهي تنقل دعوة أبيها لا دعوة صادرة منها، وفي ذلك كمال الحياء ووضوح المقصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص51–52، تحت عنوان «فائدة إسناد الدعوة إلى الأب»","url":""}]},{"id":"s28-154","number":154,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما نوع اللام ودلالتها في قوله: ﴿لِيَجْزِيَكَ﴾؟","answer":"هي لام التعليل؛ بينت أن الغرض من الدعوة مكافأته على السقي، فصار سبب الدعوة معلومًا ومحفزًا للإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص52، تحت عنوان «نوع اللام ودلالتها»","url":""}]},{"id":"s28-44","number":44,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما غرض النهي في قوله: ﴿لَا تَخَفْ﴾؟","answer":"خرج النهي إلى التسكين وإزالة خوف موسى؛ فقد صار في أرض لا يبلغها سلطان فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص55، تحت عنوان «غرض النهي ودلالته في قوله: ﴿لا تخف﴾»","url":""}]},{"id":"s28-155","number":155,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما غرض تقديم ﴿لَا تَخَفْ﴾ على الإخبار بالنجاة؟","answer":"قدّم التخلية من الخوف على التحلية بالبشارة، ليطمئن قلبه أولًا ثم يتلقى خبر نجاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص55، تحت عنوان «غرض تقديم النهي على الإخبار»","url":""}]},{"id":"s28-156","number":156,"surah":28,"verses":[25],"references":[{"surah":28,"verses":[25]}],"verseLabel":"القصص: 25","question":"ما بلاغة التذييل بالتعليل في قوله: ﴿نَجَوْتَ مِنَ الْقَوْمِ الظَّالِمِينَ﴾؟","answer":"علل نهيه عن الخوف بتمام النجاة من القوم الظالمين، فثبت الطمأنينة بالحجة وأقنع النفس بسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص55، تحت عنوان «بلاغة التذييل بالتعليل»","url":""}]},{"id":"s28-45","number":45,"surah":28,"verses":[26],"references":[{"surah":28,"verses":[26]}],"verseLabel":"القصص: 26","question":"ما سرّ الجمع بين ﴿الْقَوِيُّ﴾ و﴿الْأَمِينُ﴾ في وصف موسى؟","answer":"القوة تنجز العمل، والأمانة تمنع إساءة استعمالها؛ وهما جماع الكفاية الخلقية والعملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص63، تحت عنوان «نكتة اقتران صفتي القوة والأمانة»","url":""}]},{"id":"s28-46","number":46,"surah":28,"verses":[27],"references":[{"surah":28,"verses":[27]}],"verseLabel":"القصص: 27","question":"ما دلالة استعمال الفعل ﴿تَأْجُرَنِي﴾ مادة وصيغة؟","answer":"احتمل أن تكون أجيرًا لي أو تجعل عملك أجرًا للنكاح، فجمع اللفظ معاني الخدمة والإجارة والجزاء في إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص68–69، تحت عنوان «دلالة استعمال الفعل ﴿تأجرني﴾ مادة وصيغة»","url":""}]},{"id":"s28-157","number":157,"surah":28,"verses":[27],"references":[{"surah":28,"verses":[27]}],"verseLabel":"القصص: 27","question":"ما معنى ﴿مِنْ﴾ ودلالة دخولها على ﴿عِنْدِكَ﴾؟","answer":"هي لابتداء الغاية، أي إن إتمام العشر فضل متطوع به من موسى لا شرط لازم في العقد ولا عدوان عليه إن اقتصر على الثماني.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص69–70، تحت عنوان «معنى حرف ﴿من﴾ ودلالة دخوله على ﴿عندك﴾»","url":""}]},{"id":"s28-47","number":47,"surah":28,"verses":[28],"references":[{"surah":28,"verses":[28]}],"verseLabel":"القصص: 28","question":"ما غرض اسم الإشارة ﴿ذَلِكَ﴾ في قول موسى؟","answer":"استحضر الشرط المتفق عليه وأشار إلى تمامه، مثبتًا أن العقد بينهما قائم على ما ذُكر من غير زيادة خفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص76، تحت عنوان «غرض استعمال اسم الإشارة»","url":""}]},{"id":"s28-158","number":158,"surah":28,"verses":[28],"references":[{"surah":28,"verses":[28]}],"verseLabel":"القصص: 28","question":"ما بلاغة ذكر ﴿الْأَجَلَيْنِ﴾ بالتساوي؟","answer":"أبهم أيهما سيقضي لأن الخيار له، وسوّى بين الثماني والعشر في الوفاء بالعقد، فلا يلزمه الأطول إلا إن اختاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص77، تحت عنوان «بلاغة ذكر ﴿الأجلين﴾ بالتساوي»","url":""}]},{"id":"s28-159","number":159,"surah":28,"verses":[28],"references":[{"surah":28,"verses":[28]}],"verseLabel":"القصص: 28","question":"ما براعة استعمال لفظ العدوان في قوله: ﴿فَلَا عُدْوَانَ عَلَيَّ﴾؟","answer":"نفى كل تجاوز عليه بعد قضاء أحد الأجلين، وزادت شبه الجملة ﴿علي﴾ تقرير أن المطالبة بغير المتفق عدوان واقع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص78، تحت عنوان «براعة استعمال لفظ العدوان مع شبه الجملة»","url":""}]},{"id":"s28-48","number":48,"surah":28,"verses":[29],"references":[{"surah":28,"verses":[29]}],"verseLabel":"القصص: 29","question":"ما المراد بقوله: ﴿مِنْ جَانِبِ الطُّورِ﴾؟","answer":"حدد الجهة التي لاح منها الضوء لموسى، لا بعض الجبل نفسه؛ فالمعنى أنه أبصر النار من ناحية الطور.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص87، تحت عنوان «المراد بقوله: ﴿من جانب الطور﴾»","url":""}]},{"id":"s28-160","number":160,"surah":28,"verses":[29],"references":[{"surah":28,"verses":[29]}],"verseLabel":"القصص: 29","question":"ما سر تقديم ﴿مِنْ جَانِبِ الطُّورِ﴾ على ﴿نَارًا﴾؟","answer":"قدم الجهة للعناية بالمكان المبارك ولتشويق السامع إلى المؤخر، إذ كانت النار الواقعة هناك مبدأ النداء والرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص87، تحت عنوان «سر تقديم ﴿من جانب الطور﴾ على ﴿نارا﴾»","url":""}]},{"id":"s28-49","number":49,"surah":28,"verses":[29],"references":[{"surah":28,"verses":[29]}],"verseLabel":"القصص: 29","question":"ما دلالة ﴿أَوْ﴾ في قوله: ﴿أَوْ جَذْوَةٍ﴾؟","answer":"هي للتخيير في المطلوبين: خبر يدل على الطريق أو جذوة للنار، فكل واحد يحقق حاجة مستقلة عند تعذر الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص92، تحت عنوان «دلالة الحرف ﴿أو﴾ في ﴿أو جذوة﴾»","url":""}]},{"id":"s28-161","number":161,"surah":28,"verses":[29],"references":[{"surah":28,"verses":[29]}],"verseLabel":"القصص: 29","question":"ما سر الإتيان بـ﴿أَوْ﴾ دون الواو في قوله: ﴿أَوْ جَذْوَةٍ﴾؟","answer":"دل على أن رجاءه متعلق بالظفر بأحد الأمرين لا بهما معًا؛ لأنه لا يجزم باجتماع منفعتين في موقف مجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص92، تحت عنوان «سر الإتيان بـ﴿أو﴾ في قوله: ﴿أو جذوة﴾»","url":""}]},{"id":"s28-50","number":50,"surah":28,"verses":[30],"references":[{"surah":28,"verses":[30]}],"verseLabel":"القصص: 30","question":"ما معنى ﴿مِنْ﴾ في وصف موضع النداء؟","answer":"دلت على ابتداء غاية الصوت أو مكان النداء؛ أي جاء النداء من شاطئ الوادي ومن جهة الشجرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص101–102، تحت عنوان «معنى ﴿من﴾ في الآية»","url":""}]},{"id":"s28-162","number":162,"surah":28,"verses":[30],"references":[{"surah":28,"verses":[30]}],"verseLabel":"القصص: 30","question":"ما دلالة إعراب لفظ ﴿الْأَيْمَنِ﴾؟","answer":"يحتمل أن يكون صفة للشاطئ من جهة يمين موسى، أو وصفًا باليمن والبركة؛ فيعين الجهة ويشرفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص102، تحت عنوان «دلالة إعراب لفظ ﴿الأيمن﴾»","url":""}]},{"id":"s28-163","number":163,"surah":28,"verses":[30],"references":[{"surah":28,"verses":[30]}],"verseLabel":"القصص: 30","question":"ما دلالة إعراب قوله: ﴿مِنَ الشَّجَرَةِ﴾؟","answer":"يتعلق بفعل النداء لبيان جهته، ويجوز أن يكون بدلًا أو متعلقًا بمحذوف؛ وفي الوجوه تعيين الشجرة التي ظهر من ناحيتها النداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص104، تحت عنوان «دلالة إعراب قوله: ﴿من الشجرة﴾»","url":""}]},{"id":"s28-51","number":51,"surah":28,"verses":[31],"references":[{"surah":28,"verses":[31]}],"verseLabel":"القصص: 31","question":"ما النكتة من تنكير لفظ ﴿جَانٌّ﴾؟","answer":"أفاد فردًا من جنس الجان يحمل خصائصه، فوضح المراد وأبرز الصورة التشبيهية من غير تعيين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص114، تحت عنوان «النكتة من تنكير لفظ ﴿جان﴾»","url":""}]},{"id":"s28-52","number":52,"surah":28,"verses":[31],"references":[{"surah":28,"verses":[31]}],"verseLabel":"القصص: 31","question":"ما دلالة الأمر في قوله: ﴿أَقْبِلْ﴾؟","answer":"أفاد وجوب الرجوع والثبات، وخرج إلى التأنيس وإزالة الروع ليباشر موسى التكليف مطمئنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص116، تحت عنوان «دلالة الأمر في قوله: ﴿أقبل﴾»","url":""}]},{"id":"s28-164","number":164,"surah":28,"verses":[31],"references":[{"surah":28,"verses":[31]}],"verseLabel":"القصص: 31","question":"ما دلالة النهي في قوله: ﴿وَلَا تَخَفْ﴾؟","answer":"نهى عن استمرار الخوف لا عن خوف وقع وانقضى، فثبته بعد انقلاب العصا ووعده بزوال دواعي الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص117، تحت عنوان «دلالة النهي في قوله: ﴿لا تخف﴾»","url":""}]},{"id":"s28-165","number":165,"surah":28,"verses":[31],"references":[{"surah":28,"verses":[31]}],"verseLabel":"القصص: 31","question":"ما سر التعبير بالجملة الاسمية في قوله: ﴿إِنَّكَ مِنَ الْآمِنِينَ﴾؟","answer":"قررت ثبات الأمن واستمراره، وأكدته بإن ليكون وعدًا ملازمًا لموسى في دعوته ومواجهة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص119، تحت عنوان «سر التعبير بالاسمية دون الفعلية»","url":""}]},{"id":"s28-53","number":53,"surah":28,"verses":[32],"references":[{"surah":28,"verses":[32]}],"verseLabel":"القصص: 32","question":"ما سر التعبير بالفعل ﴿اسْلُكْ﴾؟","answer":"هو بمعنى أدخل، لكنه يوحي بالاستقامة والخفة والرشاقة في إدخال اليد في الجيب وإخراجها، فناسب ظهور المعجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص124، تحت عنوان «سر التعبير بقوله: ﴿اسلك﴾»","url":""}]},{"id":"s28-54","number":54,"surah":28,"verses":[32],"references":[{"surah":28,"verses":[32]}],"verseLabel":"القصص: 32","question":"ما أوجه معنى ﴿وَاضْمُمْ إِلَيْكَ جَنَاحَكَ مِنَ الرَّهْبِ﴾؟","answer":"يحتمل التعبير الحقيقة، فيكون الجناح اليد ويؤمر موسى بإدخالها أو بضم عضده إلى بدنه عند الفزع. ويحتمل المجاز: السكون والثبات وترك الاضطراب، تشبيهًا بالطائر الذي يضم جناحه عند الأمن؛ وعلى هذا الوجه لا يلزم أن يراد بالجناح اليد.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص128، تحت عنوان «بلاغة التعبير بضم الجناح»","url":""}]},{"id":"s28-55","number":55,"surah":28,"verses":[33],"references":[{"surah":28,"verses":[33]}],"verseLabel":"القصص: 33","question":"ما غرض الإخبار بقوله: ﴿إِنِّي قَتَلْتُ مِنْهُمْ نَفْسًا﴾؟","answer":"لم يكن اعتذارًا عن الرسالة، بل عرض سبب الخطر تمهيدًا لطلب الأمان والتأييد والنصرة على أداء التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص138، تحت عنوان «غرض الإخبار بقوله: ﴿إني قتلت منهم نفسا﴾»","url":""}]},{"id":"s28-166","number":166,"surah":28,"verses":[33],"references":[{"surah":28,"verses":[33]}],"verseLabel":"القصص: 33","question":"ما معنى الفاء في جملة: ﴿فَأَخَافُ﴾؟","answer":"فرعت خوف القتل على الحادثة السابقة، فبينت اتصال السبب بالنتيجة واستمرار توقع الانتقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص139–140، تحت عنوان «معنى الفاء في جملة: ﴿فأخاف﴾»","url":""}]},{"id":"s28-167","number":167,"surah":28,"verses":[33],"references":[{"surah":28,"verses":[33]}],"verseLabel":"القصص: 33","question":"ما دلالة التصريح والتلويح في طلب موسى الوقاية والبلاغ؟","answer":"صرح بخوفه من القتل ولوح بالحاجة إلى من يحفظه ويعينه، ثم صرح بطلب إرسال هارون ليقويه في البيان؛ فجمع الوقاية والتبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص149، تحت عنوان «دلالة التصريح والتلويح في وقاية موسى وبلاغه»","url":""}]},{"id":"s28-56","number":56,"surah":28,"verses":[34],"references":[{"surah":28,"verses":[34]}],"verseLabel":"القصص: 34","question":"ما دلالة أفعل التفضيل ﴿أَفْصَحُ﴾ في وصف هارون؟","answer":"أثبت الفصاحة لموسى وجعل هارون أزيد منه فيها؛ فلم ينف عن نفسه البيان، وإنما ذكر مزية أخيه المناسبة للمهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص145، تحت عنوان «دلالة أفعل التفضيل ﴿أفصح﴾»","url":""}]},{"id":"s28-57","number":57,"surah":28,"verses":[35],"references":[{"surah":28,"verses":[35]}],"verseLabel":"القصص: 35","question":"ما سر ذكر العضد دون غيره في قوله: ﴿سَنَشُدُّ عَضُدَكَ﴾؟","answer":"لأن العضد قوام اليد وموضع شدتها، فكان ذكره أنسب تصوير لتقوية موسى وتثبيت عزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص155، تحت عنوان «ذكر العضد دون غيره في قوله: ﴿عضدك﴾»","url":""}]},{"id":"s28-168","number":168,"surah":28,"verses":[35],"references":[{"surah":28,"verses":[35]}],"verseLabel":"القصص: 35","question":"ما بلاغة التعبير بقوله: ﴿سَنَشُدُّ عَضُدَكَ﴾؟","answer":"صور تقويته بأخيه بصورة شد العضد حتى تقوى اليد على العمل؛ فهو مجاز أو استعارة أو كناية عن الإعانة بحسب التوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص155–156، تحت عنوان «بلاغة التعبير بقوله: ﴿سنشد عضدك﴾»","url":""}]},{"id":"s28-169","number":169,"surah":28,"verses":[35],"references":[{"surah":28,"verses":[35]}],"verseLabel":"القصص: 35","question":"ما معنى الباء في قوله: ﴿بِأَخِيكَ﴾؟","answer":"هي للاستعانة؛ أي سنقويك بأخيك ونجعله سببًا في شد أزرك وتمكينك من تبليغ الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص156، تحت عنوان «معنى الباء في قوله: ﴿بأخيك﴾»","url":""}]},{"id":"s28-58","number":58,"surah":28,"verses":[38],"references":[{"surah":28,"verses":[38]}],"verseLabel":"القصص: 38","question":"ما نكتة التعبير بالماضي المنفي في قول فرعون: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾؟","answer":"صاغ نفي العلم بالماضي ليوهم قومه أن جهله بإله غيره أمر ثابت مستقر بعد نظر وتمحيص، وأنه لا يقول ذلك عن عارض أو تردد؛ فلبّس عليهم دعواه وأظهرها في صورة اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص191، تحت عنوان «نكتة التعبير بالماضي المنفي ﴿ما علمت﴾»","url":""}]},{"id":"s28-170","number":170,"surah":28,"verses":[38],"references":[{"surah":28,"verses":[38]}],"verseLabel":"القصص: 38","question":"ما بلاغة الكناية في قول فرعون: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾؟","answer":"جعل فرعون نفي علمه بإله سواه كناية عن نفي وجود ذلك الإله، منزّلًا علمه القاصر منزلة العلم المحيط؛ وهي مغالطة لأن عدم علم المخلوق بالشيء لا يستلزم عدم وجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص193، تحت عنوان «بلاغة الكناية في الآية الكريمة»","url":""}]},{"id":"s28-59","number":59,"surah":28,"verses":[38],"references":[{"surah":28,"verses":[38]}],"verseLabel":"القصص: 38","question":"ما بلاغة إسناد الإيقاد على الطين إلى هامان؟","answer":"الإسناد مجاز عقلي؛ لأن هامان هو الآمر المشرف على العمل لا المباشر للإيقاد بنفسه، فنسب إليه فعل أعوانه لكونه المتسبب في إنجازه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص197، تحت عنوان «بلاغة إسناد الإيقاد إلى هامان»","url":""}]},{"id":"s28-171","number":171,"surah":28,"verses":[38],"references":[{"surah":28,"verses":[38]}],"verseLabel":"القصص: 38","question":"ما بلاغة الكناية في قول فرعون: ﴿فَأَوْقِدْ لِي يَا هَامَانُ عَلَى الطِّينِ﴾؟","answer":"كنى بالإيقاد على الطين عن صنع الآجر الذي يبنى به الصرح، فذكر مقدمة البناء بدل التصريح به؛ وفي ذلك حث على تهيئة أسبابه والشروع فيه سريعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص197–198، تحت عنوان «بلاغة الكناية في الإيقاد على الطين»","url":""}]},{"id":"s28-60","number":60,"surah":28,"verses":[39],"references":[{"surah":28,"verses":[39]}],"verseLabel":"القصص: 39","question":"ما بلاغة العطف في قوله: ﴿وَظَنُّوا أَنَّهُمْ إِلَيْنَا لَا يُرْجَعُونَ﴾؟","answer":"عطف سوء ظنهم بعدم الرجوع إلى الله على استكبارهم في الأرض؛ لأن الأمرين متلازمان: جرّأهم إنكار البعث على العتو، وكشف العطف اجتماع فساد الاعتقاد وفساد السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص209، تحت عنوان «بلاغة العطف في جملة ﴿وظنوا﴾»","url":""}]},{"id":"s28-172","number":172,"surah":28,"verses":[39],"references":[{"surah":28,"verses":[39]}],"verseLabel":"القصص: 39","question":"ما سر تقديم ﴿إِلَيْنَا﴾ في قوله: ﴿إِلَيْنَا لَا يُرْجَعُونَ﴾؟","answer":"قدّم شبه الجملة لإبراز أن المرجع إلى الله وحده، ولتقوية الوعيد بإحضار الجهة التي أنكروها قبل ذكر الرجوع نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص210، تحت عنوان «سر تقديم شبه الجملة ﴿إلينا﴾»","url":""}]},{"id":"s28-61","number":61,"surah":28,"verses":[40],"references":[{"surah":28,"verses":[40]}],"verseLabel":"القصص: 40","question":"ما سرّ التعبير بـ﴿فَأَخَذْنَاهُ وَجُنُودَهُ فَنَبَذْنَاهُمْ فِي الْيَمِّ﴾؟","answer":"صور الأخذ والنبذ هوان فرعون وجنوده على الله، مع عظم قوته وسلطانه في أعين الناس؛ كأنهم حصيات تؤخذ بالكف فتطرح في البحر. فجمع التصوير قهر القدرة وحقارة المستكبرين عند إهلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج41، ص216، تحت عنوان «بلاغة التعبير بالأخذ والنبذ»","url":""}]}]);
